const COURSE = [{"id":1,"title":"مقدمة للبحوث والبحث العلمي","source":"المحاضرة الأولى","units":[{"title":"العلم والمعرفة وطريقة التفكير","steps":[{"title":"واقع البحث العلمي في العالم العربي كما تعرضه الشرائح","body":["تعرض الشريحتان 3–4 مقارنات تاريخية مثل 7 دولارات للفرد في الدول العربية مقابل 124 دولارًا في دول صناعية، ومتوسط إنفاق 0.5% من إجمالي الدخل القومي مقابل 2.52% في الدول المتقدمة؛ وتذكران أيضًا أدوار الحكومة والقطاع الخاص وهجرة الكفاءات.","هذه أرقام واردة في مادة المحاضرة دون سنة مرجعية موحدة، وبعض الشرائح تورد مقارنات أخرى مختلفة؛ لذلك احفظ هدف المقارنة — إبراز فجوة التمويل والتنظيم — ولا تعامل الأرقام على أنها إحصاءات حالية متحقق منها."],"example":["إذا سُئلت عن سبب ضعف النشاط العلمي في المحاضرة، اذكر التمويل المحدود وضعف شراكة القطاع الخاص والتنسيق وسوق البحث، مع التمييز بين هذه الأسباب والأرقام التاريخية."],"source":"الشريحة 3.","table":[]},{"title":"العلم وأهدافه","body":["العلم نشاط إنساني لفهم الظواهر وقوانينها والتنبؤ بها وضبطها. وتذكر الشرائح ثلاثة أهداف: الفهم، والتنبؤ، والضبط والتحكم.","الفهم يفسر لماذا يحدث الشيء، والتنبؤ يتوقع ما قد يحدث بناءً على معرفة قابلة للاختبار، والضبط يحاول التأثير في العوامل المؤدية للنتيجة."],"example":["إذا تكرر غياب الموظفين، يبدأ الباحث بفهم أسبابه، ثم يتنبأ بأوقات ارتفاعه، ثم يقترح تعديلًا في بيئة العمل."],"source":"الشريحة 11.","table":[]},{"title":"المعرفة وأنواعها","body":["المعرفة حصيلة الخبرات وفهم العلاقات بين الأشياء. وتذكر المحاضرة معرفة حسية وفلسفية وعلمية.","الحسية تنتج من المشاهدة، والفلسفية من التأمل العقلي، والعلمية من التقصي والتجريب وفق منهج قابل للفحص."],"example":["مشاهدة ازدحام مكتب = حسية؛ التفكير في معنى العدالة التنظيمية = فلسفية؛ دراسة أثر عدد الموظفين على زمن الانتظار = علمية."],"source":"الشريحة 12.","table":[]},{"title":"مصادر المعرفة","body":["تحدد الشرائح الخبرة والاستدلال والتساؤل العلمي كمصادر للمعرفة.","تساعدنا الخبرة في البدء، لكنها لا تكفي وحدها لإثبات علاقة سببية. أما الطريقة العلمية فتستخدم أسئلة وأدلة منظمة."],"example":["مدير يعرف من خبرته أن التأخير قد يرتبط بالمواصلات، لكنه يحتاج بيانات قبل اعتماد السبب."],"source":"الشريحة 13.","table":[]},{"title":"الاستدلال الاستنباطي والاستقرائي","body":["الاستنباط ينتقل من العام إلى الخاص؛ والاستقراء من حالات جزئية إلى تعميم محتمل.","الاستنباط يبدأ بمبدأ أو نظرية ويشتق منها توقعًا قابلًا للفحص؛ والاستقراء يبدأ بمشاهدات ويحاول استنتاج نمط عام."],"example":["استنباط: «التدريب يرفع المهارة» ← توقع تحسن مجموعة متدربة. استقراء: ملاحظة تحسن عدة مجموعات ← اقتراح قاعدة أوسع."],"source":"الشريحة 13.","table":[]}]},{"title":"ما البحث العلمي وما خصائصه؟","steps":[{"title":"معنى البحث","body":["تصف المحاضرة البحث بأنه دراسة معمقة للمتغيرات والظروف المحيطة بالمشكلات للوصول إلى حلول أو تفسير.","البحث ليس مجرد جمع أرقام؛ لا بد من سؤال واضح وخطة لجمع الأدلة وتحليلها للوصول إلى نتيجة قابلة للمناقشة."],"example":["انخفاض المبيعات ليس بحثًا بحد ذاته، بل صياغة سؤال عن أسبابه وجمع بيانات الأسعار والجودة والمنافسة."],"source":"الشريحة 14.","table":[]},{"title":"تعريف البحث العلمي","body":["البحث العلمي استقصاء منظم ودقيق وناقد يُبنى على بيانات وفحص واختبار للوصول إلى معرفة أو حل مشكلة.","لذلك يتصف البحث الجيد بالمنهجية، والتوثيق، وإمكان مراجعة النتائج؛ ولا يعتمد فقط على سلطة المتحدث أو شعوره."],"example":["دراسة أثر تدريب الموظفين على جودة الخدمة باستخدام مقاييس محددة وقبل/بعد وبرهان."],"source":"الشريحة 15.","table":[]},{"title":"البحث بوصفه نظامًا","body":["تمثل المحاضرة البحث كنظام: مدخلات ← عمليات ← مخرجات.","المدخلات تشمل الباحث والمعرفة والهدف والفرضيات؛ والعمليات تشمل جمع البيانات وتحليلها؛ والمخرجات تقرير النتائج والتوصيات."],"example":["مدخلات: سؤال عن تأخر الخدمات. عمليات: استبيان وملاحظة وتحليل. مخرجات: أسباب محتملة وتوصيات تشغيلية."],"source":"الشريحة 17.","table":[]},{"title":"خصائص البحث العلمي","body":["من علامات البحث العلمي: هدف واضح، دقة، اختبار، قابلية تكرار، موضوعية، قابلية تعميم مناسبة، تبسيط، تنبؤ، مرونة، والسعي لتفسير الأسباب.","التعميم يجب أن يتناسب مع اختيار العينة؛ والتكرار يعني أن المنهج مفصل بحيث يمكن فحص نتائجه مجددًا؛ والموضوعية تعني عدم ليّ الدليل لموافقة رأي مسبق."],"example":["إذا جمع الباحث عينة ملائمة لا يصح أن يقول إن النتائج تمثل كل السكان دون دليل على التمثيل."],"source":"الشريحة 8.","table":[]}]},{"title":"الباحث الجيد وأخلاقيات المعرفة","steps":[{"title":"الاتجاهات العلمية للباحث","body":["تسرد الشرائح الثقة بالعلم، والتعلم المستمر، والانفتاح العقلي، وتقبل الحقائق، والأمانة، والدقة، والتأني، والبحث عن الأسباب.","الاتجاه العلمي هو موقف ذهني يقبل تغيير الاستنتاج عند ظهور دليل جديد ويبتعد عن الادعاء غير المدعوم."],"example":["إذا خالفت البيانات توقعات الباحث، يعرض النتيجة بدل إخفائها."],"source":"الشريحة 6.","table":[]},{"title":"صفات الباحث الجيد","body":["من الصفات الرغبة الجادة، والصبر، ووضوح التفكير، والموضوعية، والمعرفة بالمشكلة، والقدرة اللغوية والتحليلية، وعدم إخفاء القصور أو الأدلة المخالفة.","صفات الباحث تمس طريقة العمل وصدق العرض أكثر من كونها مجرد حفظ تعريفات."],"example":["باحث يذكر قصور حجم العينة ويصيغ التوصيات في حدود ما تدعمه بياناته."],"source":"الشريحة 7.","table":[]},{"title":"معوقات البحث العلمي","body":["تعرض الشرائح ضعف التمويل وتعاون المؤسسات والقطاع الخاص والبيئة الإدارية، إضافة إلى صعوبة عزل العوامل المؤثرة في الظواهر الإنسانية.","الظواهر الاجتماعية متعددة الأسباب؛ وقد يتأثر المبحوث بالعاطفة أو السياق، ويصعب محاكاة الواقع في المختبر أو تعميم نتيجة عينة ضيقة."],"example":["تقييم الرضا الوظيفي يتأثر بالراتب والإدارة والأمان والظروف الشخصية في الوقت نفسه."],"source":"الشريحة 5.","table":[]},{"title":"الانتحال وسرقة الأبحاث","body":["تعد سرقة بحث كامل أو تجميع نصوص بلا إحالة أو ترجمة أعمال دون نسبتها لأصحابها من صور الانتحال المذكورة.","الأمانة العلمية تتطلب ذكر المصادر وتحديد المساهمة الفعلية للباحث، وعدم نسب نتائج الطلاب أو الزملاء إلى شخص آخر."],"example":["ينبغي الاقتباس الموثق وإعادة الصياغة الأصلية مع الإحالة، لا نسخ نتائج منشورة وتغيير عنوانها فقط."],"source":"الشريحة 10.","table":[]}]},{"title":"الإدارة والبحث العلمي","steps":[{"title":"علاقة المدير بالبحوث","body":["لا يلزم أن ينفذ المدير البحث بنفسه، لكنه يحتاج فهمه لتحديد المشكلات وتمييز البحث الجيد واستخدام الأدلة لاتخاذ قرارات أفضل.","يساعد البحث المدير على رؤية تعدد الأسباب وتقييم المخاطر بدل الاعتماد على تفسير واحد حدسي."],"example":["انخفاض الأرباح قد يرتبط بالتكلفة أو الطلب أو المنافسة؛ البحث يساعد في فرز البدائل."],"source":"الشريحة 18.","table":[]},{"title":"علاقة المدير بالمستشار","body":["يجب توضيح نطاق المهمة والتوقعات والقيم والقيود وتوفير تعاون الموظفين للباحث.","هدف الاستشارة حل المشكلة المؤسسية لا إثبات رأي المدير مسبقًا؛ ولهذا يلزم استقلالية منهجية كافية."],"example":["قبل التعاقد، يتفق الطرفان على سؤال البحث والمدة والسرية والتقارير وآلية الوصول للسجلات."],"source":"الشريحة 19.","table":[]},{"title":"مزايا وعيوب الباحث الداخلي","body":["يعرف الباحث الداخلي بيئة المؤسسة وتكلفته أقل ويسهل متابعة تنفيذ التوصيات، لكن قد يتأثر بثقافتها وضغوط أصحاب النفوذ.","يكون مناسبًا للمشكلات الروتينية أو الحاجة الملحة، مع وضع ضوابط تمنع تضارب المصالح."],"example":["فريق تحسين الجودة داخل الشركة مناسب لمتابعة إجراءات متكررة، لكن تحقيقًا حساسًا قد يحتاج حيادًا إضافيًا."],"source":"الشريحة 22.","table":[]},{"title":"مزايا وعيوب الباحث الخارجي","body":["يأتي الباحث الخارجي بخبرات متنوعة ونظرة مستقلة نسبيًا، لكن قد يكون مكلفًا ويحتاج وقتًا لفهم المؤسسة.","القرار ليس «داخلي أفضل» دائمًا، بل يعتمد على التعقيد والموارد والاستقلالية والخبرة."],"example":["دراسة تغيير هيكل منظمة قد تستفيد من مستشار مستقل مع مشاركة فريق داخلي لتوفير السياق."],"source":"الشريحة 24.","table":[]},{"title":"عيوب فريق البحث الخارجي","body":["تذكر الشرائح التكلفة المرتفعة والحاجة لوقت لفهم المؤسسة وضعف تقبل بعض الموظفين له، واحتمال ارتفاع أتعاب متابعة تنفيذ الحلول.","قد تساعد الإدارة بتقديم معلومات تمهيدية وشرح هدف الفريق وتحديد عقد واضح يقلل هذه المشكلات."],"example":["المستشار الممتاز علميًا قد يتعثر إذا رفض الموظفون المقابلات بسبب ضعف التواصل الداخلي."],"source":"الشريحة 25.","table":[]}]},{"title":"تصنيفات البحوث","steps":[{"title":"البحث الأساسي","body":["يركز البحث الأساسي على اكتشاف المبادئ والعلاقات وبناء النظريات حتى دون تطبيق فوري.","السؤال المركزي: ما القاعدة أو التفسير العام؟"],"example":["دراسة العلاقة العامة بين دوافع الموظفين وسلوكهم عبر بيئات متعددة."],"source":"الشريحة 28.","table":[]},{"title":"البحث التطبيقي","body":["يهدف البحث التطبيقي إلى معالجة مشكلة واقعية محددة تواجه مؤسسة أو مجتمعًا.","السؤال المركزي: ماذا نفعل لعلاج هذه المشكلة هنا؟"],"example":["تحديد أسباب انخفاض مبيعات منتج معين واقتراح خطوات قابلة للتنفيذ."],"source":"الشريحة 27.","table":[]},{"title":"تصنيفات أخرى للبحوث","body":["تذكر المحاضرة تصنيفًا حسب المنهج: تاريخية، وصفية، وتجريبية؛ وتصنيفًا أكاديميًا مثل البحوث المحكمة ورسائل الماجستير والدكتوراه.","التصنيفات تختلف بحسب معيار التقسيم؛ الغرض شيء والمنهج شيء آخر والمخرج الأكاديمي شيء ثالث.","خرائط ذهنية ورسومات تعليمية قابلة للتعديل"],"example":["بحث تطبيقي قد يستخدم منهجًا وصفيًا، فلا يوجد تعارض بين الوصفين."],"source":"الشريحة 30.","table":[]},{"title":"خريطة ذهنية متفرعة: موضوعات المحاضرة","body":[],"example":[],"source":null,"table":[[["العلم والمعرفة وطريقة التفكير","↘","ما البحث العلمي وما خصائصه؟"],["الباحث الجيد وأخلاقيات المعرفة","مقدمة للبحوث والبحث العلمي","الإدارة والبحث العلمي"],["تصنيفات البحوث","↖","واقع البحث العلمي في العالم العربي كما تعرضه الشرائح"]]]},{"title":"الرسم 2: تسلسل المفاهيم","body":["جداول المقارنة والمراجعة السريعة"],"example":[],"source":null,"table":[]},{"title":"الفرق بين أنواع المعرفة","body":[],"example":[],"source":null,"table":[[["النوع","طريقة الوصول","مثال"],["حسية","الملاحظة والتجربة اليومية","شاهدت ازدحامًا"],["فلسفية","التفكير والتأمل","ما معنى العدالة؟"],["علمية","منهج منظم واختبار","ما الذي يزيد الانتظار؟"]]]},{"title":"اختيار فريق البحث","body":[],"example":[],"source":null,"table":[[["البند","داخلي","خارجي"],["المعرفة بالمنظمة","مرتفعة غالبًا","تحتاج فترة للتعرف"],["التكلفة","أقل غالبًا","أعلى غالبًا"],["الاستقلال عن الثقافة الداخلية","قد يتأثر بها","قد يوفر زاوية مختلفة"],["متابعة التنفيذ","أسهل غالبًا","تتطلب تنسيقًا"]]]},{"title":"أساسي أم تطبيقي؟","body":["تمارين محلولة خطوة بخطوة"],"example":[],"source":null,"table":[[["البعد","أساسي","تطبيقي"],["الهدف","بناء معرفة أو نظرية","حل مشكلة محددة"],["الأولوية","فهم الظاهرة","اتخاذ إجراء"],["مثال","نظرية الدافعية","تقليل غياب موظفي فرع معين"]]]},{"title":"تمرين 1 | وضع بحثي أم مجرد قرار؟","body":["المسألة: قرر مدير زيادة رواتب جميع العاملين بعد سماع شكوى من موظف واحد. هل اتبع البحث العلمي؟ وما الخطوات التي تنقصه؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: لم يتبع بحثًا منظمًا؛ يحتاج تحديد المشكلة، جمع بيانات تمثيلية، تحليل أسباب الشكاوى، ثم تقييم بدائل مناسبة."],"source":null,"table":[]},{"title":"تمرين 2 | استنباط أم استقراء؟","body":["المسألة: لاحظ باحث أن ثلاثة أقسام استخدمت نظام مكافآت جديدًا وارتفعت إنتاجيتها؛ فاقترح أن الحوافز ترتبط بالإنتاجية. حدد اتجاه الاستدلال.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: استقراء من ملاحظات جزئية إلى تعميم محتمل؛ يحتاج التعميم إلى اختبار إضافي."],"source":null,"table":[]},{"title":"تمرين 3 | الباحث المناسب","body":["المسألة: شركة صغيرة لديها مشكلة معقدة مرتبطة بثقافتها الداخلية، وتخشى التحيز. هل تستخدم داخليًا أم خارجيًا؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: قد يلائمها فريق خارجي لخبرته واستقلاله النسبي، مع موظف داخلي يوفر المعلومات؛ يعتمد القرار على الموارد والسرية."],"source":null,"table":[]},{"title":"تمرين 4 | أساسي أم تطبيقي؟","body":["المسألة: قارن بين دراسة نظرية حول دوافع العمل ودراسة لمعالجة تأخر شحنات مؤسسة محددة.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: الأولى أقرب إلى البحث الأساسي؛ الثانية بحث تطبيقي بسبب مشكلة تشغيلية مباشرة."],"source":null,"table":[]},{"title":"مسألة رقمية تدريبية إضافية","body":["المعطيات: تذكر الشرائح مقارنة تاريخية بين 0.5% و2.52% من الإنفاق على البحث. كم مرة تمثل النسبة الثانية الأولى؟","ورقة حفظ مركزة قبل الاختبار"],"example":["النتيجة | الحل خطوة بخطوة: 2.52 ÷ 0.50 = 5.04 مرات. هذه عملية على أرقام الشرائح وليست تأكيدًا لحداثتها."],"source":null,"table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"الهدف الذي لا يدخل ضمن الأهداف الثلاثة للعلم هو:","options":["الضبط والتحكم","تأكيد آراء الباحث دون دليل","الفهم","التنبؤ"],"correct":1,"explain":"تأكيد آراء الباحث دون دليل"},{"num":2,"kind":"mc","question":"معرفة تنتج عن المشاهدة والمعايشة المباشرة تسمى:","options":["المعرفة الفلسفية","المعرفة العلمية التجريبية حصراً","الاستدلال الاستنباطي","المعرفة الحسية"],"correct":3,"explain":"المعرفة الحسية"},{"num":3,"kind":"mc","question":"الانتقال من نظرية عامة إلى توقع حول حالة خاصة يسمى:","options":["التصنيف","الاقتباس","الاستقراء","الاستنباط"],"correct":3,"explain":"الاستنباط"},{"num":4,"kind":"mc","question":"البحث العلمي يختلف عن التخمين لأنه:","options":["يعتمد على استقصاء منظم وأدلة قابلة للفحص","يستبعد جميع الفرضيات","لا يحتاج إلى بيانات","يلغي كل احتمال للخطأ"],"correct":0,"explain":"يعتمد على استقصاء منظم وأدلة قابلة للفحص"},{"num":5,"kind":"mc","question":"في نموذج المدخلات والعمليات والمخرجات، تحليل البيانات يُعد:","options":["عاملًا خارجيًا","مدخلًا فقط","عملية","مخرجًا فقط"],"correct":2,"explain":"عملية"},{"num":6,"kind":"mc","question":"من خصائص البحث العلمي الجيد:","options":["إمكانية اختبار النتائج","التمسك بالرأي رغم الأدلة","عدم بيان المنهج","غياب الهدف"],"correct":0,"explain":"إمكانية اختبار النتائج"},{"num":7,"kind":"mc","question":"أي سلوك يوافق الاتجاه العلمي للباحث؟","options":["إخفاء عيوب الأداة","حذف النتائج المخالفة","التسرع في التعميم","تقبل نتائج مخالفة للتوقعات"],"correct":3,"explain":"تقبل نتائج مخالفة للتوقعات"},{"num":8,"kind":"mc","question":"أحد التحديات الخاصة بالبحوث الاجتماعية هو:","options":["توحد ظروف جميع المبحوثين","سهولة عزل سلوك الإنسان في كل موقف","غياب أي أثر للمجتمع","تعدد العوامل المؤثرة في السلوك"],"correct":3,"explain":"تعدد العوامل المؤثرة في السلوك"},{"num":9,"kind":"mc","question":"أي مثال يعد انتحالًا علميًا؟","options":["توثيق اقتباس قصير بمصدره","عرض القيود في التقرير","ترجمة بحث ونشره دون ذكر مؤلفه","ذكر مساهمة كل باحث"],"correct":2,"explain":"ترجمة بحث ونشره دون ذكر مؤلفه"},{"num":10,"kind":"mc","question":"ما الدور الصحيح للمدير في البحث؟","options":["فهم نتائج البحث واستخدامها في القرارات","اشتراط أن يجمع كل البيانات بنفسه","تجاهل نتائج لا توافق رأيه","منع الموظفين من التعاون"],"correct":0,"explain":"فهم نتائج البحث واستخدامها في القرارات"},{"num":11,"kind":"mc","question":"الميزة البارزة للباحث الداخلي غالبًا:","options":["سرعة فهم سياق المؤسسة","انعدام أي تحيز","الاستقلال المطلق دائمًا","ارتفاع التكلفة دائمًا"],"correct":0,"explain":"سرعة فهم سياق المؤسسة"},{"num":12,"kind":"mc","question":"ميزة محتملة للباحث الخارجي:","options":["خبرات متنوعة ورؤية مختلفة","معرفة فورية بكل التفاصيل","سهولة وصول بلا تنسيق","تكلفة أقل دائمًا"],"correct":0,"explain":"خبرات متنوعة ورؤية مختلفة"},{"num":13,"kind":"mc","question":"بحث يختبر مبادئ عامة دون تطبيق مباشر يصنف:","options":["أساسيًا","تطبيقيًا حصريًا","تنفيذيًا","توثيقيًا فقط"],"correct":0,"explain":"أساسيًا"},{"num":14,"kind":"mc","question":"بحث لعلاج انخفاض مبيعات منتج في شركة محددة يصنف:","options":["فلسفيًا","أساسيًا حصريًا","تاريخيًا بالضرورة","تطبيقيًا"],"correct":3,"explain":"تطبيقيًا"},{"num":15,"kind":"mc","question":"الفرق بين المنهج والغرض من البحث هو أن:","options":["هما مصطلحان متطابقان","كل بحث تطبيقي تجريبي بالضرورة","المنهج يحدد فقط العنوان","الغرض يحدد لماذا نبحث والمنهج كيف نبحث"],"correct":3,"explain":"الغرض يحدد لماذا نبحث والمنهج كيف نبحث"},{"num":16,"kind":"tf","question":"التنبؤ والضبط والتحكم من أهداف العلم.","options":["صح","خطأ"],"correct":true,"explain":"صح — التنبؤ والضبط والتحكم من أهداف العلم."},{"num":17,"kind":"tf","question":"المعرفة الحسية تعتمد أساسًا على المشاهدة.","options":["صح","خطأ"],"correct":true,"explain":"صح — المعرفة الحسية تعتمد أساسًا على المشاهدة."},{"num":18,"kind":"tf","question":"الاستقراء يبدأ من قاعدة عامة وينتهي بحالة خاصة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الاستقراء ينتقل من حالات جزئية إلى تعميم محتمل."},{"num":19,"kind":"tf","question":"البحث العلمي عملية منظمة تعتمد على جمع الأدلة.","options":["صح","خطأ"],"correct":true,"explain":"صح — البحث العلمي عملية منظمة تعتمد على جمع الأدلة."},{"num":20,"kind":"tf","question":"التقرير النهائي من مخرجات البحث.","options":["صح","خطأ"],"correct":true,"explain":"صح — التقرير النهائي من مخرجات البحث."},{"num":21,"kind":"tf","question":"الموضوعية تعني تجاهل الأدلة المخالفة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الموضوعية تقتضي عرض الأدلة المخالفة وعدم تحريفها."},{"num":22,"kind":"tf","question":"يمكن أن تكون صعوبة التعميم من تحديات البحث الاجتماعي.","options":["صح","خطأ"],"correct":true,"explain":"صح — يمكن أن تكون صعوبة التعميم من تحديات البحث الاجتماعي."},{"num":23,"kind":"tf","question":"ترجمة كتاب بلا الإشارة إلى المؤلف الأصلـي ممارسة مقبولة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — تعد الترجمة دون نسبتها لصاحبها انتحالًا."},{"num":24,"kind":"tf","question":"الباحث الجيد يذكر أوجه القصور في بحثه.","options":["صح","خطأ"],"correct":true,"explain":"صح — الباحث الجيد يذكر أوجه القصور في بحثه."},{"num":25,"kind":"tf","question":"على المدير أن يجري جميع البحوث بنفسه ليتخذ قرارًا جيدًا.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — على المدير فهم البحث دون ضرورة تنفيذه بنفسه."},{"num":26,"kind":"tf","question":"الباحث الداخلي قد يفهم ثقافة المنظمة بسرعة.","options":["صح","خطأ"],"correct":true,"explain":"صح — الباحث الداخلي قد يفهم ثقافة المنظمة بسرعة."},{"num":27,"kind":"tf","question":"الباحث الخارجي يكون أقل تكلفة من الداخلي في جميع الحالات.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الباحث الخارجي قد يكون أكثر تكلفة من الداخلي."},{"num":28,"kind":"tf","question":"البحث الأساسي يسعى إلى بناء معرفة عامة.","options":["صح","خطأ"],"correct":true,"explain":"صح — البحث الأساسي يسعى إلى بناء معرفة عامة."},{"num":29,"kind":"tf","question":"البحث التطبيقي يعالج مشكلات واقعية محددة.","options":["صح","خطأ"],"correct":true,"explain":"صح — البحث التطبيقي يعالج مشكلات واقعية محددة."},{"num":30,"kind":"tf","question":"يمكن تصنيف البحث حسب غرضه وكذلك حسب منهجه.","options":["صح","خطأ"],"correct":true,"explain":"صح — يمكن تصنيف البحث حسب غرضه وكذلك حسب منهجه."},{"num":31,"kind":"short","question":"اشرح المقصود بمفهوم «واقع البحث العلمي في العالم العربي كما تعرضه الشرائح» واذكر مثالًا يوضحه.","options":[],"answer":"واقع البحث العلمي في العالم العربي كما تعرضه الشرائح: تعرض الشريحتان 3–4 مقارنات تاريخية مثل 7 دولارات للفرد في الدول العربية مقابل 124 دولارًا في دول صناعية، ومتوسط إنفاق 0.5% من إجمالي الدخل القومي مقابل 2.52% في الدول المتقدمة؛ وتذكران أيضًا أدوار الحكومة والقطاع الخاص وهجرة الكفاءات.  مثال: إذا سُئلت عن سبب ضعف النشاط العلمي في المحاضرة، اذكر التمويل المحدود وضعف شراكة القطاع الخاص والتنسيق وسوق البحث، مع التمييز بين هذه الأسباب والأرقام التاريخية."},{"num":32,"kind":"short","question":"اشرح المقصود بمفهوم «العلم وأهدافه» واذكر مثالًا يوضحه.","options":[],"answer":"العلم وأهدافه: العلم نشاط إنساني لفهم الظواهر وقوانينها والتنبؤ بها وضبطها. وتذكر الشرائح ثلاثة أهداف: الفهم، والتنبؤ، والضبط والتحكم.  مثال: إذا تكرر غياب الموظفين، يبدأ الباحث بفهم أسبابه، ثم يتنبأ بأوقات ارتفاعه، ثم يقترح تعديلًا في بيئة العمل."},{"num":33,"kind":"short","question":"اشرح المقصود بمفهوم «المعرفة وأنواعها» واذكر مثالًا يوضحه.","options":[],"answer":"المعرفة وأنواعها: المعرفة حصيلة الخبرات وفهم العلاقات بين الأشياء. وتذكر المحاضرة معرفة حسية وفلسفية وعلمية.  مثال: مشاهدة ازدحام مكتب = حسية؛ التفكير في معنى العدالة التنظيمية = فلسفية؛ دراسة أثر عدد الموظفين على زمن الانتظار = علمية."},{"num":34,"kind":"short","question":"اشرح المقصود بمفهوم «مصادر المعرفة» واذكر مثالًا يوضحه.","options":[],"answer":"مصادر المعرفة: تحدد الشرائح الخبرة والاستدلال والتساؤل العلمي كمصادر للمعرفة.  مثال: مدير يعرف من خبرته أن التأخير قد يرتبط بالمواصلات، لكنه يحتاج بيانات قبل اعتماد السبب."},{"num":35,"kind":"short","question":"اشرح المقصود بمفهوم «الاستدلال الاستنباطي والاستقرائي» واذكر مثالًا يوضحه.","options":[],"answer":"الاستدلال الاستنباطي والاستقرائي: الاستنباط ينتقل من العام إلى الخاص؛ والاستقراء من حالات جزئية إلى تعميم محتمل.  مثال: استنباط: «التدريب يرفع المهارة» ← توقع تحسن مجموعة متدربة. استقراء: ملاحظة تحسن عدة مجموعات ← اقتراح قاعدة أوسع."},{"num":36,"kind":"short","question":"اشرح المقصود بمفهوم «معنى البحث» واذكر مثالًا يوضحه.","options":[],"answer":"معنى البحث: تصف المحاضرة البحث بأنه دراسة معمقة للمتغيرات والظروف المحيطة بالمشكلات للوصول إلى حلول أو تفسير.  مثال: انخفاض المبيعات ليس بحثًا بحد ذاته، بل صياغة سؤال عن أسبابه وجمع بيانات الأسعار والجودة والمنافسة."},{"num":37,"kind":"short","question":"اشرح المقصود بمفهوم «تعريف البحث العلمي» واذكر مثالًا يوضحه.","options":[],"answer":"تعريف البحث العلمي: البحث العلمي استقصاء منظم ودقيق وناقد يُبنى على بيانات وفحص واختبار للوصول إلى معرفة أو حل مشكلة.  مثال: دراسة أثر تدريب الموظفين على جودة الخدمة باستخدام مقاييس محددة وقبل/بعد وبرهان."},{"num":38,"kind":"short","question":"اشرح المقصود بمفهوم «البحث بوصفه نظامًا» واذكر مثالًا يوضحه.","options":[],"answer":"البحث بوصفه نظامًا: تمثل المحاضرة البحث كنظام: مدخلات ← عمليات ← مخرجات.  مثال: مدخلات: سؤال عن تأخر الخدمات. عمليات: استبيان وملاحظة وتحليل. مخرجات: أسباب محتملة وتوصيات تشغيلية."},{"num":39,"kind":"short","question":"اشرح المقصود بمفهوم «خصائص البحث العلمي» واذكر مثالًا يوضحه.","options":[],"answer":"خصائص البحث العلمي: من علامات البحث العلمي: هدف واضح، دقة، اختبار، قابلية تكرار، موضوعية، قابلية تعميم مناسبة، تبسيط، تنبؤ، مرونة، والسعي لتفسير الأسباب.  مثال: إذا جمع الباحث عينة ملائمة لا يصح أن يقول إن النتائج تمثل كل السكان دون دليل على التمثيل."},{"num":40,"kind":"short","question":"اشرح المقصود بمفهوم «الاتجاهات العلمية للباحث» واذكر مثالًا يوضحه.","options":[],"answer":"الاتجاهات العلمية للباحث: تسرد الشرائح الثقة بالعلم، والتعلم المستمر، والانفتاح العقلي، وتقبل الحقائق، والأمانة، والدقة، والتأني، والبحث عن الأسباب.  مثال: إذا خالفت البيانات توقعات الباحث، يعرض النتيجة بدل إخفائها."},{"num":41,"kind":"short","question":"اشرح المقصود بمفهوم «صفات الباحث الجيد» واذكر مثالًا يوضحه.","options":[],"answer":"صفات الباحث الجيد: من الصفات الرغبة الجادة، والصبر، ووضوح التفكير، والموضوعية، والمعرفة بالمشكلة، والقدرة اللغوية والتحليلية، وعدم إخفاء القصور أو الأدلة المخالفة.  مثال: باحث يذكر قصور حجم العينة ويصيغ التوصيات في حدود ما تدعمه بياناته."},{"num":42,"kind":"short","question":"اشرح المقصود بمفهوم «معوقات البحث العلمي» واذكر مثالًا يوضحه.","options":[],"answer":"معوقات البحث العلمي: تعرض الشرائح ضعف التمويل وتعاون المؤسسات والقطاع الخاص والبيئة الإدارية، إضافة إلى صعوبة عزل العوامل المؤثرة في الظواهر الإنسانية.  مثال: تقييم الرضا الوظيفي يتأثر بالراتب والإدارة والأمان والظروف الشخصية في الوقت نفسه."},{"num":43,"kind":"short","question":"اشرح المقصود بمفهوم «الانتحال وسرقة الأبحاث» واذكر مثالًا يوضحه.","options":[],"answer":"الانتحال وسرقة الأبحاث: تعد سرقة بحث كامل أو تجميع نصوص بلا إحالة أو ترجمة أعمال دون نسبتها لأصحابها من صور الانتحال المذكورة.  مثال: ينبغي الاقتباس الموثق وإعادة الصياغة الأصلية مع الإحالة، لا نسخ نتائج منشورة وتغيير عنوانها فقط."},{"num":44,"kind":"short","question":"اشرح المقصود بمفهوم «علاقة المدير بالبحوث» واذكر مثالًا يوضحه.","options":[],"answer":"علاقة المدير بالبحوث: لا يلزم أن ينفذ المدير البحث بنفسه، لكنه يحتاج فهمه لتحديد المشكلات وتمييز البحث الجيد واستخدام الأدلة لاتخاذ قرارات أفضل.  مثال: انخفاض الأرباح قد يرتبط بالتكلفة أو الطلب أو المنافسة؛ البحث يساعد في فرز البدائل."},{"num":45,"kind":"short","question":"اشرح المقصود بمفهوم «علاقة المدير بالمستشار» واذكر مثالًا يوضحه.","options":[],"answer":"علاقة المدير بالمستشار: يجب توضيح نطاق المهمة والتوقعات والقيم والقيود وتوفير تعاون الموظفين للباحث.  مثال: قبل التعاقد، يتفق الطرفان على سؤال البحث والمدة والسرية والتقارير وآلية الوصول للسجلات."},{"num":46,"kind":"case","question":"[وضع بحثي أم مجرد قرار؟] قرر مدير زيادة رواتب جميع العاملين بعد سماع شكوى من موظف واحد. هل اتبع البحث العلمي؟ وما الخطوات التي تنقصه؟","options":[],"answer":"لم يتبع بحثًا منظمًا؛ يحتاج تحديد المشكلة، جمع بيانات تمثيلية، تحليل أسباب الشكاوى، ثم تقييم بدائل مناسبة."},{"num":47,"kind":"case","question":"[استنباط أم استقراء؟] لاحظ باحث أن ثلاثة أقسام استخدمت نظام مكافآت جديدًا وارتفعت إنتاجيتها؛ فاقترح أن الحوافز ترتبط بالإنتاجية. حدد اتجاه الاستدلال.","options":[],"answer":"استقراء من ملاحظات جزئية إلى تعميم محتمل؛ يحتاج التعميم إلى اختبار إضافي."},{"num":48,"kind":"case","question":"[الباحث المناسب] شركة صغيرة لديها مشكلة معقدة مرتبطة بثقافتها الداخلية، وتخشى التحيز. هل تستخدم داخليًا أم خارجيًا؟","options":[],"answer":"قد يلائمها فريق خارجي لخبرته واستقلاله النسبي، مع موظف داخلي يوفر المعلومات؛ يعتمد القرار على الموارد والسرية."},{"num":49,"kind":"case","question":"[أساسي أم تطبيقي؟] قارن بين دراسة نظرية حول دوافع العمل ودراسة لمعالجة تأخر شحنات مؤسسة محددة.","options":[],"answer":"الأولى أقرب إلى البحث الأساسي؛ الثانية بحث تطبيقي بسبب مشكلة تشغيلية مباشرة."},{"num":50,"kind":"case","question":"[أمانة علمية] عثر طالب على بحث باللغة الإنجليزية وترجمه ونشره باسمه بلا إحالة. قيّم التصرف.","options":[],"answer":"يعد انتحالًا لأنه نسب فكرًا ونصًا لغير صاحبه؛ يجب النسبة للمؤلف الأصلي والالتزام بقواعد الاقتباس."}]},{"id":2,"title":"خطوات البحث وتحديد المشكلة","source":"المحاضرة الثانية","units":[{"title":"خطة البحث والطريقة العلمية","steps":[{"title":"خطة البحث","body":["خطة البحث تصور مبدئي منظم يحدد الهيكل العام للدراسة ويُراجع قبل اعتمادها النهائي.","تشرح الشرائح تشبيه الخطة بخارطة البناء وتذكر مناقشتها في سيمنار، وإمكان تعديل بعض عناصرها وفق إجراءات المؤسسة."],"example":["خطة لدراسة عدم استخدام نظام معلومات جديد: عنوان ومشكلة وأهداف ومنهج وعينة وزمن ومراجع."],"source":"الشريحة 2.","table":[]},{"title":"محتويات خطة البحث","body":["تشمل العنوان والمقدمة والمشكلة والفرضيات والأهداف والأهمية والمنهجية والمجتمع والعينة والحدود والافتراضات والدراسات السابقة والمصطلحات والهيكل والمراجع.","الهدف من وجود هذه العناصر هو التأكد من وضوح سبب إجراء الدراسة وكيف ستُنفذ وكيف ستُستخدم النتائج."],"example":["المجتمع: جميع موظفي شركة؛ العينة: عدد مختار منهم وفق تصميم واضح."],"source":"الشريحة 3.","table":[]},{"title":"الطريقة العلمية","body":["منهج منتظم يبدأ بالملاحظة وتحديد المشكلة ويمر بالإطار النظري والفرضيات والتعريفات الإجرائية والتصميم والجمع والتحليل والتفسير والتقرير.","لا تعني العلمية تجاهل الخبرة، بل عدم الاعتماد على التخمين وحده في المشكلات التي تتطلب دليلًا."],"example":["لاحظ مدير ضعف استخدام نظام: اجمع بيانات، اختبر أسبابًا محتملة، ثم اعتمد تدخلًا مناسبًا."],"source":"الشريحة 4.","table":[]},{"title":"هل تطبق الشركات المنهج دائمًا؟","body":["تقول الشرائح إن المؤسسات قد لا تستخدم البحث العلمي في كل مشكلة، بسبب بساطة المشكلة أحيانًا أو رغبتها في تقليل التكلفة.","الحكم الرشيد يوازن قيمة المعلومات المطلوبة مع وقت البحث وتكلفته وخطر القرار غير المدروس."],"example":["إصلاح مصباح معطل لا يحتاج بحثًا أكاديميًا؛ إعادة هيكلة نظام خدمة قد تحتاج بحثًا."],"source":"الشريحة 5.","table":[]}]},{"title":"من الملاحظة إلى المشكلة العامة","steps":[{"title":"منطقة المشكلة العامة","body":["هي حالة يلاحظ فيها الباحث حاجة إلى بحث، دون أن تكون جميع حدود المشكلة معروفة بعد.","قد تكون مشكلة حالية أو فرصة للتحسين أو حاجة نظرية أو سؤالًا ميدانيًا."],"example":["عبارة «المبيعات لا تتحسن» منطقة مشكلة عامة؛ لم تحدد بعد المنتج أو الفترة أو السبب."],"source":"الشريحة 10.","table":[]},{"title":"مفهوم مشكلة البحث","body":["توضح الشرائح أن المشكلة فجوة بين الوضع القائم والوضع المرغوب أو موقف يحتاج تفسيرًا علميًا.","كل مشكلة عملية ليست بالضرورة مشكلة بحثية صالحة؛ يجب أن تقبل صياغتها في سؤال يمكن جمع بيانات مناسبة للإجابة عنه."],"example":["الفجوة: متوسط انتظار العملاء 60 دقيقة بدل الهدف 20 دقيقة."],"source":"الشريحة 11.","table":[]},{"title":"مصادر مشكلة البحث","body":["تشمل الخبرة العملية، والقراءة، والدراسات السابقة، والرسائل الجامعية، ومناقشات الباحثين، والمؤتمرات وورش العمل.","الاختيار الجيد ينشأ من ملاحظة قابلة للفحص وليس فقط من رغبة شخصية في عنوان جذاب."],"example":["تقرير مصرفي يظهر ارتفاع القروض المتعثرة؛ قد يقود إلى موضوع بحث."],"source":"الشريحة 13.","table":[]},{"title":"معايير ذاتية لاختيار المشكلة","body":["تضم اهتمام الباحث وقدرته وإمكاناته المالية وتوفر المعلومات والمساعدة الإدارية.","إذا كانت المشكلة مهمة ولكن البيانات غير متاحة إطلاقًا فقد يكون تنفيذها متعذرًا ضمن شروط الباحث."],"example":["طالب لديه شهران لا يختار بحثًا يستلزم سفرًا لست محافظات دون ميزانية."],"source":"الشريحة 14.","table":[]},{"title":"معايير علمية واجتماعية","body":["تركز على الفائدة العملية والإضافة المعرفية وإمكان تعميم مناسب وفتح آفاق لدراسات أخرى.","الجودة ليست في حداثة العنوان فقط؛ بل في الوضوح والجدوى وإمكان إنجاز البحث بدقة."],"example":["دراسة مشكلة متكررة ذات أثر فعلي على الأسر قد تكون أكثر قيمة من عنوان مبهر بلا بيانات."],"source":"الشريحة 15.","table":[]}]},{"title":"البيانات الأولية والدراسات السابقة","steps":[{"title":"البيانات الأولية","body":["هي البيانات التي يجمعها الباحث مباشرة من المشاركين أو الملاحظة أو الاستبيانات لتلبية سؤال دراسته.","يمكن أن تكون مقابلات مبدئية للتعرف على المشكلة أو بيانات منظمة في مرحلة التنفيذ؛ والشرائح تركز هنا على الجمع المبدئي."],"example":["مقابلة موظفين حول صعوبات استخدام نظام معلومات."],"source":"الشريحة 19.","table":[]},{"title":"البيانات الثانوية","body":["بيانات موجودة مسبقًا في السجلات الحكومية أو تقارير المؤسسة أو الإنترنت أو المكتبات.","تفيد في فهم السياق وصقل المشكلة وتوفير وقت جمع البيانات، مع ضرورة تقييم ملاءمتها وجودتها."],"example":["الاستفادة من سجل الشكاوى القديم لتحديد اتجاه المشكلة."],"source":"الشريحة 19.","table":[]},{"title":"مراجعة الدراسات السابقة","body":["تساعد على معرفة المتغيرات المهمة وبناء النظرية والفرضيات، وتحسين صياغة المشكلة وقابلية اختبار النتائج وتجنب تكرار عمل معروف.","المراجعة الجيدة ليست نسخ ملخصات فقط؛ بل مقارنة النتائج والمنهجيات والحدود والفراغ البحثي."],"example":["اكتشاف أن معظم الدراسات تناولت الشركات الكبرى بينما السؤال يخص المؤسسات الصغيرة."],"source":"الشريحة 20.","table":[]},{"title":"مراحل مراجعة الأدبيات","body":["تذكر الشرائح تحديد المصادر المتاحة، وجمع المعلومات ذات الصلة، ثم كتابة نتائج المراجعة.","يمكن تنظيم المقالات بجدول: مؤلف وسنة ومشكلة ومنهج ونتائج وحدود، ثم تركيب صورة موحدة من الأدلة."],"example":["جدول دراسات أسباب غياب الموظفين عبر قطاعات مختلفة."],"source":"الشريحة 21.","table":[]},{"title":"قواعد المعلومات الثلاث","body":["تميز المحاضرة قواعد ببليوجرافية تقدم وصف المصادر، وقواعد ملخصات، وقواعد نصوص كاملة.","ليس كل سجل في قاعدة بيانات يعني أن كامل المقال متاح؛ انتبه إلى نوع القاعدة قبل التخطيط للمراجعة."],"example":["عنوان مؤلف وتاريخ فقط = ببليوجرافية؛ ملخص بحث = ملخصات؛ المقال كاملًا = نص كامل."],"source":"الشريحة 22.","table":[]}]},{"title":"الصياغة الدقيقة والأخلاقيات","steps":[{"title":"صياغة المشكلة","body":["يمكن عرض المشكلة تقريرًا خبريًا أو في صورة سؤال أو عدة أسئلة تحدد المتغيرات والعلاقة بينها.","انتقل من «هناك مشاكل في الإنتاج» إلى «ما أثر ساعات التدريب على إنتاجية موظفي فرع معين في فترة محددة؟»."],"example":["تقريرية: تدرس الدراسة أثر التدريب في الإنتاجية. استفهامية: ما أثر التدريب في الإنتاجية؟"],"source":"الشريحة 23.","table":[]},{"title":"فوائد التحديد الدقيق","body":["يوحد فهم الباحث والمشرف والقارئ، ويوجه الأسئلة والفرضيات والمنهج وحدود الدراسة والأساليب الإحصائية.","كلما كان السؤال أوضح، أمكن تحديد البيانات المطلوبة والاختبار الملائم قبل النزول الميداني."],"example":["سؤال يحدد «مقارنة رضا عميلين» يوجه أداة الدراسة وتصميم العينة."],"source":"الشريحة 25.","table":[]},{"title":"أخلاقيات المراحل الأولية","body":["تؤكد الشرائح إخطار المشاركين بطبيعة الدراسة، وسرية الإجابات الفردية، وعدم استخدام الخداع للحصول على معلومات.","تذكر الهدف والخصوصية والطوعية بوضوح قبل المقابلات أو جمع البيانات.","خرائط ذهنية ورسومات تعليمية قابلة للتعديل"],"example":["تخبر الموظف أن رأيه لن يسلم باسمه لمديره المباشر وأن مشاركته اختيارية."],"source":"الشريحة 27.","table":[]},{"title":"خريطة ذهنية متفرعة: موضوعات المحاضرة","body":[],"example":[],"source":null,"table":[[["خطة البحث والطريقة العلمية","↘","من الملاحظة إلى المشكلة العامة"],["البيانات الأولية والدراسات السابقة","الخطوات الأولى للبحث العلمي وتحديد المشكلة","الصياغة الدقيقة والأخلاقيات"],["خطة البحث","↖","محتويات خطة البحث"]]]},{"title":"الرسم 2: تسلسل المفاهيم","body":["جداول المقارنة والمراجعة السريعة"],"example":[],"source":null,"table":[]},{"title":"مكونات خطة البحث","body":[],"example":[],"source":null,"table":[[["المجموعة","العناصر"],["ماذا ولماذا؟","العنوان، المقدمة، المشكلة، الأهداف، الأهمية، الفرضيات"],["كيف ومن؟","المنهجية، المجتمع والعينة، الحدود، الافتراضات"],["على أي أساس؟","الدراسات السابقة، المصطلحات، الهيكل، المراجع"]]]},{"title":"عام أم محدد؟","body":[],"example":[],"source":null,"table":[[["الصياغة العامة","الصياغة المحددة"],["الخدمة بطيئة","ما أثر عدد موظفي الاستقبال على متوسط انتظار العملاء في فرع عدن خلال 2026؟"],["هناك ضعف تدريب","ما العلاقة بين ساعات التدريب ومتوسط الإنتاج اليومي للعاملين؟"]]]},{"title":"أنواع المعلومات","body":["تمارين محلولة خطوة بخطوة"],"example":[],"source":null,"table":[[["العنصر","بيانات أولية","بيانات ثانوية"],["المصدر","جمع الباحث المباشر","سجلات أو مصادر منشورة"],["مثال","استبيان جديد","تقرير سابق"],["انتباه","الوقت/التكلفة/الأخلاقيات","الجودة والملاءمة والحداثة"]]]},{"title":"تمرين 1 | تضييق المشكلة","body":["المسألة: بدأ باحث بعنوان «مشاكل التعليم». صغ سؤالًا أكثر تحديدًا وقابلًا للدراسة.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: مثلًا: ما أثر عدد الطلاب في الفصل على متوسط درجات الرياضيات في مدارس محددة خلال فصل دراسي؟"],"source":null,"table":[]},{"title":"تمرين 2 | مصدر البيانات","body":["المسألة: لديك شكاوى مسجلة منذ عامين وتريد معرفة أسبابها الحالية. صنف المصدرين المناسبين.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: السجل السابق بيانات ثانوية، ومقابلات أو استبيان جديد مع المتأثرين بيانات أولية."],"source":null,"table":[]},{"title":"تمرين 3 | اختيار المشكلة","body":["المسألة: طالب يريد دراسة ظاهرة مهمة ولكن لا يمكن الوصول إلى أي بيانات عنها ولا يتوفر الوقت. ما المعيار الإشكالي؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: قابلية التنفيذ: توفر المعلومات والوقت والإمكانات والقدرة البحثية."],"source":null,"table":[]},{"title":"تمرين 4 | الصياغة","body":["المسألة: حوّل عبارة «الموظفون لا يستخدمون النظام» إلى صياغة استفهامية.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: ما العوامل المرتبطة بانخفاض استخدام الموظفين لنظام المعلومات الجديد في المؤسسة؟"],"source":null,"table":[]},{"title":"مسألة رقمية تدريبية إضافية","body":["المعطيات: في استطلاع مبدئي افتراضي شمل 40 موظفًا، ذكر 12 منهم ضعف التدريب. ما نسبة أصحاب هذا الرأي؟","ورقة حفظ مركزة قبل الاختبار"],"example":["النتيجة | الحل خطوة بخطوة: 12 ÷ 40 × 100 = 30%. هذا رقم تعليمي افتراضي لا يمثل نتائج دراسة فعلية."],"source":null,"table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"ما التشبيه المستخدم لخطة البحث في الشرائح؟","options":["كشف المصروفات","الملخص النهائي","النتائج فقط","خارطة البناء"],"correct":3,"explain":"خارطة البناء"},{"num":2,"kind":"mc","question":"أي عنصر من الآتي يرد ضمن خطة البحث؟","options":["مجتمع وعينة البحث","النتائج المفترضة كحقائق","قائمة مكافآت المشاركين فقط","القرار النهائي قبل النتائج"],"correct":0,"explain":"مجتمع وعينة البحث"},{"num":3,"kind":"mc","question":"تبدأ الطريقة العلمية عادة بـ:","options":["رفض الفروض","كتابة النتائج","تعميم الاستنتاج","الملاحظة المبدئية"],"correct":3,"explain":"الملاحظة المبدئية"},{"num":4,"kind":"mc","question":"أي وصف لمشكلة البحث أدق؟","options":["فجوة تحتاج تفسيرًا بين الوضع الحالي والمرغوب","اسم المؤسسة فقط","توقع لا يمكن قياسه","نتيجة محسومة مسبقًا"],"correct":0,"explain":"فجوة تحتاج تفسيرًا بين الوضع الحالي والمرغوب"},{"num":5,"kind":"mc","question":"«خدمات العملاء ضعيفة» تمثل غالبًا:","options":["فرضية صفرية","نتيجة تحليل","منطقة مشكلة عامة","عنوانًا محددًا كفاية"],"correct":2,"explain":"منطقة مشكلة عامة"},{"num":6,"kind":"mc","question":"من مصادر مشكلة البحث:","options":["النتائج التي لم تجمع بعد","التخمين وحده","الدراسات السابقة والخبرة العملية","إجابات عشوائية"],"correct":2,"explain":"الدراسات السابقة والخبرة العملية"},{"num":7,"kind":"mc","question":"من المعايير الذاتية لاختيار المشكلة:","options":["أهمية المجتمع فقط","قدرة الباحث وتوفر الموارد","شهرة المجلة فقط","إسهامها النظري فقط"],"correct":1,"explain":"قدرة الباحث وتوفر الموارد"},{"num":8,"kind":"mc","question":"من المعايير العلمية والاجتماعية:","options":["الفائدة العملية والإضافة المعرفية","حجم الخط المستخدم","الميل الشخصي وحده","سهولة السفر وحدها"],"correct":0,"explain":"الفائدة العملية والإضافة المعرفية"},{"num":9,"kind":"mc","question":"جمع استجابات جديدة باستبيان من الموظفين هو:","options":["فرضية جاهزة","تحليل مسبق","بيانات ثانوية","بيانات أولية"],"correct":3,"explain":"بيانات أولية"},{"num":10,"kind":"mc","question":"استخدام تقرير حكومي منشور سابقًا هو:","options":["بيانات أولية مباشرة","تجربة عشوائية","بيانات ثانوية","تقدير رأي شخصي"],"correct":2,"explain":"بيانات ثانوية"},{"num":11,"kind":"mc","question":"تساعد مراجعة الأدبيات أساسًا على:","options":["إلغاء الحاجة إلى صياغة المشكلة","نسخ النتائج دون مصادر","ضمان صحة الفرضية","تحديد المتغيرات والفجوة البحثية"],"correct":3,"explain":"تحديد المتغيرات والفجوة البحثية"},{"num":12,"kind":"mc","question":"قاعدة تقدم عنوان المقال ومؤلفه وناشره تسمى:","options":["قائمة العينة","أداة تجربة","نصوصًا كاملة","ببليوجرافية"],"correct":3,"explain":"ببليوجرافية"},{"num":13,"kind":"mc","question":"«ما أثر التدريب على الإنتاجية؟» مثال على:","options":["النتيجة النهائية","المدخلات","الصياغة الاستفهامية","الصياغة التقريرية"],"correct":2,"explain":"الصياغة الاستفهامية"},{"num":14,"kind":"mc","question":"الوظيفة الأساسية للتحديد الدقيق للمشكلة:","options":["تقليل أهمية المراجع","ضمان قبول الفروض","توجيه الأسئلة والمنهج وجمع البيانات","إلغاء أي حدود للدراسة"],"correct":2,"explain":"توجيه الأسئلة والمنهج وجمع البيانات"},{"num":15,"kind":"mc","question":"الممارسة الأخلاقية في مقابلات الموظفين هي:","options":["إخفاء الغرض عمدًا","إجبارهم دون إعلام","إرسال الإجابات الفردية لجميع المديرين","توضيح الدراسة والحفاظ على سرية الإجابات"],"correct":3,"explain":"توضيح الدراسة والحفاظ على سرية الإجابات"},{"num":16,"kind":"tf","question":"الخطة البحثية تصور منظم لما سينفذه الباحث.","options":["صح","خطأ"],"correct":true,"explain":"صح — الخطة البحثية تصور منظم لما سينفذه الباحث."},{"num":17,"kind":"tf","question":"المراجع ليست ضمن مكونات خطة البحث.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — المراجع من عناصر خطة البحث."},{"num":18,"kind":"tf","question":"تحديد المشكلة من الخطوات المهمة للطريقة العلمية.","options":["صح","خطأ"],"correct":true,"explain":"صح — تحديد المشكلة من الخطوات المهمة للطريقة العلمية."},{"num":19,"kind":"tf","question":"قد تكفي الخبرة لحل بعض المشكلات البسيطة دون بحث مطول.","options":["صح","خطأ"],"correct":true,"explain":"صح — قد تكفي الخبرة لحل بعض المشكلات البسيطة دون بحث مطول."},{"num":20,"kind":"tf","question":"منطقة المشكلة العامة أكثر تحديدًا من سؤال بحث جيد.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — المشكلة العامة أقل تحديدًا من السؤال البحثي الجيد."},{"num":21,"kind":"tf","question":"يمكن الاستفادة من المؤتمرات العلمية لتوليد مشكلة بحث.","options":["صح","خطأ"],"correct":true,"explain":"صح — يمكن الاستفادة من المؤتمرات العلمية لتوليد مشكلة بحث."},{"num":22,"kind":"tf","question":"توافر المعلومات أحد معايير اختيار المشكلة.","options":["صح","خطأ"],"correct":true,"explain":"صح — توافر المعلومات أحد معايير اختيار المشكلة."},{"num":23,"kind":"tf","question":"الأهمية العلمية وحدها تغني عن قابلية تنفيذ الدراسة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — قابلية التنفيذ شرط مهم إلى جانب الأهمية."},{"num":24,"kind":"tf","question":"الاستبيان الذي ينفذه الباحث مباشرة ينتج بيانات أولية.","options":["صح","خطأ"],"correct":true,"explain":"صح — الاستبيان الذي ينفذه الباحث مباشرة ينتج بيانات أولية."},{"num":25,"kind":"tf","question":"السجلات المنشورة مسبقًا تعد بيانات ثانوية.","options":["صح","خطأ"],"correct":true,"explain":"صح — السجلات المنشورة مسبقًا تعد بيانات ثانوية."},{"num":26,"kind":"tf","question":"مراجعة الدراسات السابقة تساعد على تحديد المتغيرات.","options":["صح","خطأ"],"correct":true,"explain":"صح — مراجعة الدراسات السابقة تساعد على تحديد المتغيرات."},{"num":27,"kind":"tf","question":"القاعدة الببليوجرافية تضمن دائمًا توفير النص الكامل.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الببليوجرافية تقدم بيانات وصفية ولا تضمن النص الكامل."},{"num":28,"kind":"tf","question":"صياغة المشكلة الاستفهامية تتم في صورة سؤال.","options":["صح","خطأ"],"correct":true,"explain":"صح — صياغة المشكلة الاستفهامية تتم في صورة سؤال."},{"num":29,"kind":"tf","question":"وضوح المشكلة يساعد على اختيار الأساليب الإحصائية.","options":["صح","خطأ"],"correct":true,"explain":"صح — وضوح المشكلة يساعد على اختيار الأساليب الإحصائية."},{"num":30,"kind":"tf","question":"يجوز الحصول على معلومات الموظفين بالخداع إذا كان البحث مهمًا.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — لا يجوز استخدام الخداع لإجبار المشاركين على الإفصاح."},{"num":31,"kind":"short","question":"اشرح المقصود بمفهوم «خطة البحث» واذكر مثالًا يوضحه.","options":[],"answer":"خطة البحث: خطة البحث تصور مبدئي منظم يحدد الهيكل العام للدراسة ويُراجع قبل اعتمادها النهائي.  مثال: خطة لدراسة عدم استخدام نظام معلومات جديد: عنوان ومشكلة وأهداف ومنهج وعينة وزمن ومراجع."},{"num":32,"kind":"short","question":"اشرح المقصود بمفهوم «محتويات خطة البحث» واذكر مثالًا يوضحه.","options":[],"answer":"محتويات خطة البحث: تشمل العنوان والمقدمة والمشكلة والفرضيات والأهداف والأهمية والمنهجية والمجتمع والعينة والحدود والافتراضات والدراسات السابقة والمصطلحات والهيكل والمراجع.  مثال: المجتمع: جميع موظفي شركة؛ العينة: عدد مختار منهم وفق تصميم واضح."},{"num":33,"kind":"short","question":"اشرح المقصود بمفهوم «الطريقة العلمية» واذكر مثالًا يوضحه.","options":[],"answer":"الطريقة العلمية: منهج منتظم يبدأ بالملاحظة وتحديد المشكلة ويمر بالإطار النظري والفرضيات والتعريفات الإجرائية والتصميم والجمع والتحليل والتفسير والتقرير.  مثال: لاحظ مدير ضعف استخدام نظام: اجمع بيانات، اختبر أسبابًا محتملة، ثم اعتمد تدخلًا مناسبًا."},{"num":34,"kind":"short","question":"اشرح المقصود بمفهوم «هل تطبق الشركات المنهج دائمًا؟» واذكر مثالًا يوضحه.","options":[],"answer":"هل تطبق الشركات المنهج دائمًا؟: تقول الشرائح إن المؤسسات قد لا تستخدم البحث العلمي في كل مشكلة، بسبب بساطة المشكلة أحيانًا أو رغبتها في تقليل التكلفة.  مثال: إصلاح مصباح معطل لا يحتاج بحثًا أكاديميًا؛ إعادة هيكلة نظام خدمة قد تحتاج بحثًا."},{"num":35,"kind":"short","question":"اشرح المقصود بمفهوم «منطقة المشكلة العامة» واذكر مثالًا يوضحه.","options":[],"answer":"منطقة المشكلة العامة: هي حالة يلاحظ فيها الباحث حاجة إلى بحث، دون أن تكون جميع حدود المشكلة معروفة بعد.  مثال: عبارة «المبيعات لا تتحسن» منطقة مشكلة عامة؛ لم تحدد بعد المنتج أو الفترة أو السبب."},{"num":36,"kind":"short","question":"اشرح المقصود بمفهوم «مفهوم مشكلة البحث» واذكر مثالًا يوضحه.","options":[],"answer":"مفهوم مشكلة البحث: توضح الشرائح أن المشكلة فجوة بين الوضع القائم والوضع المرغوب أو موقف يحتاج تفسيرًا علميًا.  مثال: الفجوة: متوسط انتظار العملاء 60 دقيقة بدل الهدف 20 دقيقة."},{"num":37,"kind":"short","question":"اشرح المقصود بمفهوم «مصادر مشكلة البحث» واذكر مثالًا يوضحه.","options":[],"answer":"مصادر مشكلة البحث: تشمل الخبرة العملية، والقراءة، والدراسات السابقة، والرسائل الجامعية، ومناقشات الباحثين، والمؤتمرات وورش العمل.  مثال: تقرير مصرفي يظهر ارتفاع القروض المتعثرة؛ قد يقود إلى موضوع بحث."},{"num":38,"kind":"short","question":"اشرح المقصود بمفهوم «معايير ذاتية لاختيار المشكلة» واذكر مثالًا يوضحه.","options":[],"answer":"معايير ذاتية لاختيار المشكلة: تضم اهتمام الباحث وقدرته وإمكاناته المالية وتوفر المعلومات والمساعدة الإدارية.  مثال: طالب لديه شهران لا يختار بحثًا يستلزم سفرًا لست محافظات دون ميزانية."},{"num":39,"kind":"short","question":"اشرح المقصود بمفهوم «معايير علمية واجتماعية» واذكر مثالًا يوضحه.","options":[],"answer":"معايير علمية واجتماعية: تركز على الفائدة العملية والإضافة المعرفية وإمكان تعميم مناسب وفتح آفاق لدراسات أخرى.  مثال: دراسة مشكلة متكررة ذات أثر فعلي على الأسر قد تكون أكثر قيمة من عنوان مبهر بلا بيانات."},{"num":40,"kind":"short","question":"اشرح المقصود بمفهوم «البيانات الأولية» واذكر مثالًا يوضحه.","options":[],"answer":"البيانات الأولية: هي البيانات التي يجمعها الباحث مباشرة من المشاركين أو الملاحظة أو الاستبيانات لتلبية سؤال دراسته.  مثال: مقابلة موظفين حول صعوبات استخدام نظام معلومات."},{"num":41,"kind":"short","question":"اشرح المقصود بمفهوم «البيانات الثانوية» واذكر مثالًا يوضحه.","options":[],"answer":"البيانات الثانوية: بيانات موجودة مسبقًا في السجلات الحكومية أو تقارير المؤسسة أو الإنترنت أو المكتبات.  مثال: الاستفادة من سجل الشكاوى القديم لتحديد اتجاه المشكلة."},{"num":42,"kind":"short","question":"اشرح المقصود بمفهوم «مراجعة الدراسات السابقة» واذكر مثالًا يوضحه.","options":[],"answer":"مراجعة الدراسات السابقة: تساعد على معرفة المتغيرات المهمة وبناء النظرية والفرضيات، وتحسين صياغة المشكلة وقابلية اختبار النتائج وتجنب تكرار عمل معروف.  مثال: اكتشاف أن معظم الدراسات تناولت الشركات الكبرى بينما السؤال يخص المؤسسات الصغيرة."},{"num":43,"kind":"short","question":"اشرح المقصود بمفهوم «مراحل مراجعة الأدبيات» واذكر مثالًا يوضحه.","options":[],"answer":"مراحل مراجعة الأدبيات: تذكر الشرائح تحديد المصادر المتاحة، وجمع المعلومات ذات الصلة، ثم كتابة نتائج المراجعة.  مثال: جدول دراسات أسباب غياب الموظفين عبر قطاعات مختلفة."},{"num":44,"kind":"short","question":"اشرح المقصود بمفهوم «قواعد المعلومات الثلاث» واذكر مثالًا يوضحه.","options":[],"answer":"قواعد المعلومات الثلاث: تميز المحاضرة قواعد ببليوجرافية تقدم وصف المصادر، وقواعد ملخصات، وقواعد نصوص كاملة.  مثال: عنوان مؤلف وتاريخ فقط = ببليوجرافية؛ ملخص بحث = ملخصات؛ المقال كاملًا = نص كامل."},{"num":45,"kind":"short","question":"اشرح المقصود بمفهوم «صياغة المشكلة» واذكر مثالًا يوضحه.","options":[],"answer":"صياغة المشكلة: يمكن عرض المشكلة تقريرًا خبريًا أو في صورة سؤال أو عدة أسئلة تحدد المتغيرات والعلاقة بينها.  مثال: تقريرية: تدرس الدراسة أثر التدريب في الإنتاجية. استفهامية: ما أثر التدريب في الإنتاجية؟"},{"num":46,"kind":"case","question":"[تضييق المشكلة] بدأ باحث بعنوان «مشاكل التعليم». صغ سؤالًا أكثر تحديدًا وقابلًا للدراسة.","options":[],"answer":"مثلًا: ما أثر عدد الطلاب في الفصل على متوسط درجات الرياضيات في مدارس محددة خلال فصل دراسي؟"},{"num":47,"kind":"case","question":"[مصدر البيانات] لديك شكاوى مسجلة منذ عامين وتريد معرفة أسبابها الحالية. صنف المصدرين المناسبين.","options":[],"answer":"السجل السابق بيانات ثانوية، ومقابلات أو استبيان جديد مع المتأثرين بيانات أولية."},{"num":48,"kind":"case","question":"[اختيار المشكلة] طالب يريد دراسة ظاهرة مهمة ولكن لا يمكن الوصول إلى أي بيانات عنها ولا يتوفر الوقت. ما المعيار الإشكالي؟","options":[],"answer":"قابلية التنفيذ: توفر المعلومات والوقت والإمكانات والقدرة البحثية."},{"num":49,"kind":"case","question":"[الصياغة] حوّل عبارة «الموظفون لا يستخدمون النظام» إلى صياغة استفهامية.","options":[],"answer":"ما العوامل المرتبطة بانخفاض استخدام الموظفين لنظام المعلومات الجديد في المؤسسة؟"},{"num":50,"kind":"case","question":"[أخلاقيات] طلب مدير معرفة الأسماء والإجابات الفردية للمبحوثين. ما الاستجابة المهنية؟","options":[],"answer":"احترام السرية المتفق عليها، وتقديم نتائج إجمالية وعدم مشاركة بيانات تعريفية دون أساس وموافقة مناسبة."}]},{"id":3,"title":"الإطار النظري والمتغيرات","source":"المحاضرة الثالثة والرابعة، الشرائح 1–27","units":[{"title":"بناء الإطار النظري","steps":[{"title":"الإطار النظري","body":["هو نموذج يشرح شبكة العلاقات المنطقية بين المتغيرات المرتبطة بمشكلة البحث بالاستفادة من الأدبيات السابقة.","ليس قائمة تعريفات، بل تفسير لماذا نتوقع وجود العلاقات وكيف ترتبط بالعوامل المؤثرة في المشكلة."],"example":["نموذج يربط جودة التدريب بالتعلم ويضع الحاجة للنمو عاملًا قد يغيّر قوة العلاقة."],"source":"الشريحة 2.","table":[]},{"title":"معنى المتغير","body":["المتغير خاصية أو كمية تتخذ قيمًا أو فئات مختلفة بين أفراد أو أزمنة.","قد يكون كميًا مثل عدد الوحدات المنتجة أو نوعيًا مثل نوع الوظيفة. القابلية للاختلاف هي جوهر كونه متغيرًا."],"example":["إنتاج العامل 1 وحدة في دقيقة و5 وحدات في دقيقة أخرى؛ تغير في الزمن."],"source":"الشريحة 3.","table":[]},{"title":"أهمية مراجعة الأدبيات في بناء الإطار","body":["تُبنى العلاقات المتوقعة على المعرفة والدراسات السابقة؛ لذلك يعد الإطار النظري أساسًا منطقيًا للخطوات اللاحقة.","لا يجوز رسم أسهم سببية لمجرد أنها تبدو منطقية؛ ينبغي تفسيرها بما تسمح به النظرية والأدلة."],"example":["دراسات سابقة تربط التدريب بالأداء تساعد على صياغة مسار النموذج."],"source":"الشريحة 2.","table":[]}]},{"title":"المتغيران الأساسيان","steps":[{"title":"المتغير التابع (Dependent)","body":["هو النتيجة أو الظاهرة التي يريد الباحث تفسير تغيرها أو التنبؤ بها.","اسأل: ما النتيجة التي تهم الدراسة؟ قد يحتوي البحث على أكثر من متغير تابع."],"example":["في «أثر التدريب على الإنتاجية»، الإنتاجية متغير تابع."],"source":"الشريحة 5.","table":[]},{"title":"المتغير المستقل (Independent)","body":["هو العامل التفسيري الذي يُفترض أن يرتبط بالتغير في المتغير التابع أو يؤثر فيه.","تسميته مستقلًا في النموذج لا تثبت السببية وحدها؛ يلزم تصميم مناسب وأدلة للاختبار."],"example":["في المثال نفسه: التدريب متغير مستقل."],"source":"الشريحة 9.","table":[]},{"title":"اتجاه العلاقة بين المتغيرات","body":["قد تكون العلاقة موجبة أو سالبة، وقد تختلف قوة العلاقة بحسب الظروف والافتراضات.","العلاقة الموجبة تعني اتجاه تغير متوافق، والسالبة تعني تغيرًا متعاكسًا، ولا يصح الخلط بين الارتباط والسببية."],"example":["زيادة جودة الدليل قد ترتبط بانخفاض نسبة المنتجات المعيبة: علاقة سالبة."],"source":"الشريحة 11.","table":[]}]},{"title":"المتغيرات التي تغير أو تفسر العلاقة","steps":[{"title":"المتغير المُعدِّل (Moderator)","body":["هو متغير يغير قوة العلاقة أو اتجاهها بين المتغير المستقل والتابع؛ أي يحدد متى أو لمن تكون العلاقة أقوى.","يسمى أثره «شرطيًا»؛ ولا يشرح بالضرورة الآلية التي تحدث بها العلاقة."],"example":["جودة التدريب تؤثر في الرغبة في التعلم بقوة أكبر لدى الموظفين ذوي الحاجة العالية للنمو."],"source":"الشريحة 10.","table":[]},{"title":"مثال المهارات الإدارية كمُعدِّل","body":["تعرض الشرائح التنوع في قوة العمل كمستقل وكفاءة المنظمة كتابع، والمهارات الإدارية كعامل يعدل أثر التنوع.","قد لا تستفيد المؤسسة من التنوع ما لم تُنسق الإدارة المعارف والمهارات المختلفة."],"example":["في فريق ذي تنوع عالٍ: إذا كانت مهارات الإدارة ضعيفة فقد لا يظهر التحسن نفسه."],"source":"الشريحة 12.","table":[]},{"title":"مثال العمر كمُعدِّل","body":["يعرض المصدر مثالًا تتوقف فيه فاعلية التدريب خارج العمل على عمر المتدرب، فيختلف الأثر بين فئات العمر.","على الرغم من استخدام الشرائح تعبير «الوسيط» في جملة واحدة، فوظيفة العمر الواردة بالمثال هي تعديل قوة أثر التدريب؛ نميز الدور تبعًا لصياغة العلاقة."],"example":["التدريب قد يرتبط بإنتاجية أعلى لفئة عمرية دون أخرى في بيانات المثال الافتراضي بالمحاضرة."],"source":"الشريحة 13.","table":[]},{"title":"المتغير الوسيط (Mediator)","body":["متغير يفسر مسار انتقال أثر المستقل إلى التابع أو الآلية التي عبرها تظهر العلاقة.","اسأل: لماذا وكيف يؤدي X إلى Y؟ مثال المحاضرة: القيادة بالقيم ← الولاء التنظيمي ← الأداء."],"example":["قد تعزز القيادة الولاء، ويسهم الولاء بدوره في رفع الأداء."],"source":"الشريحة 18.","table":[]},{"title":"المتغير المعترض أو الفاصل (Intervening)","body":["تستخدمه المحاضرة لوصف عامل يظهر بين بداية أثر المستقل وظهور النتيجة، مع التأكيد على التسلسل الزمني.","في بعض المراجع يتداخل مع مفهوم الوسيط؛ لذا نوضح مصطلح الشرائح ونقارن وظيفته بالمسار الوسيط."],"example":["تنوع القوة العاملة ← تنشيط الابتكار مع الزمن ← كفاءة المنظمة."],"source":"الشريحة 22.","table":[]},{"title":"المتغير العرضي (Extraneous)","body":["عامل آخر محتمل قد يؤثر في العلاقة الأصلية بين المتغيرين، ويهتم الباحث بضبطه أو مراعاته.","عدم الانتباه له قد يعطي انطباعًا مضللًا عن قوة العلاقة أو اتجاهها."],"example":["تقييم أثر التدريب على الإنتاجية قد يتأثر باختلاف الخبرة السابقة للموظفين."],"source":"الشريحة 25.","table":[]},{"title":"الفرق بين المُعدِّل والوسيط","body":["المُعدِّل يجيب «متى أو لمن تتغير قوة العلاقة؟»؛ والوسيط يجيب «كيف أو لماذا يحدث الأثر؟».","تمييز الدور يتوقف على النموذج البحثي لا على الاسم الثابت للمتغير في جميع الدراسات."],"example":["العمر كمُعدِّل: يغير تأثير التدريب. الولاء كوسيط: يشرح طريق تأثير القيادة على الأداء."],"source":"الشريحة 26.","table":[]}]},{"title":"إعداد النموذج النظري","steps":[{"title":"مكونات الإطار النظري الخمسة","body":["تحدد الشرائح تسمية المتغيرات، وبيان العلاقات بينها، وافتراض اتجاهها، وشرح أسباب توقعها اعتمادًا على الأدبيات، ورسم مخطط يوضح النموذج.","في كل سهم اكتب سبب توقع العلاقة، وأوضح إذا كان المتغير تابعًا أو مستقلًا أو معدّلًا أو وسيطًا."],"example":["جودة التدريب → إتقان المهارة → الإنتاجية، مع مهارة المدرب كعامل مُعدِّل محتمل."],"source":"الشريحة 27.","table":[]},{"title":"العلاقات الموجبة والسالبة","body":["تصف العلاقة الموجبة تغيرًا في الاتجاه نفسه والسالبة تغيرًا عكسيًا، ويمكن أن تكون العلاقة خطية أو غير خطية.","لا تستنتج الاتجاه من اسم المتغير وحده؛ فكّر في تعريفه التشغيلي وكيفية ترميزه."],"example":["إذا رُمز الأداء الأعلى بقيم أكبر، فمن المتوقع علاقة موجبة بين التمرين الجيد والأداء."],"source":"الشريحة 27.","table":[]},{"title":"تحديد وظيفة المتغير حسب السؤال","body":["قد يكون المتغير مستقلًا في نموذج ومُعدِّلًا في نموذج آخر؛ تحدد وظيفته بطريقة دخوله في الفرضية.","تعرض الشرائح حالتين تتغير فيهما وظيفة «الحاجة للنمو» من مستقل إلى مُعدِّل رغم بقاء أسماء المتغيرات نفسها.","خرائط ذهنية ورسومات تعليمية قابلة للتعديل"],"example":["حالة 1: الجودة والحاجة للنمو تؤثران منفصلتين. حالة 2: أثر الجودة مشروط بالحاجة للنمو."],"source":"الشريحة 14.","table":[]},{"title":"خريطة ذهنية متفرعة: موضوعات المحاضرة","body":[],"example":[],"source":null,"table":[[["بناء الإطار النظري","↘","المتغيران الأساسيان"],["المتغيرات التي تغير أو تفسر العلاقة","الإطار النظري وأنواع المتغيرات","إعداد النموذج النظري"],["الإطار النظري","↖","معنى المتغير"]]]},{"title":"الرسم 2: تسلسل المفاهيم","body":["جداول المقارنة والمراجعة السريعة"],"example":[],"source":null,"table":[]},{"title":"قاموس المتغيرات","body":[],"example":[],"source":null,"table":[[["النوع","السؤال المفتاح","المثال"],["تابع","ما النتيجة؟","الإنتاجية"],["مستقل","ما العامل المفسر؟","التدريب"],["مُعدِّل","متى/لمن تختلف العلاقة؟","العمر أو الحاجة للنمو"],["وسيط","كيف/لماذا يحدث الأثر؟","الولاء التنظيمي"],["معترض","ما الذي يظهر بين البداية والنتيجة؟","التنشيط الابتكاري"],["عرضي","ما العامل الآخر الذي يجب ضبطه؟","الخبرة السابقة"]]]},{"title":"علاقتان مختلفتان بالمتغيرات نفسها","body":["تمارين محلولة خطوة بخطوة"],"example":[],"source":null,"table":[[["النموذج","وظيفة الحاجة للنمو","المعنى"],["الأول","مستقل","حاجة النمو والجودة عاملان يفسران الرغبة في التعلم"],["الثاني","مُعدِّل","أثر جودة التدريب يختلف باختلاف مستوى الحاجة للنمو"]]]},{"title":"تمرين 1 | المتغيرات الأساسية","body":["المسألة: دراسة «أثر الإنفاق الإعلاني على المبيعات». حدد المستقل والتابع.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: المستقل هو الإنفاق الإعلاني، والتابع هو المبيعات."],"source":null,"table":[]},{"title":"تمرين 2 | تحديد المُعدِّل","body":["المسألة: أثر التدريب في الأداء أعلى لدى ذوي الخبرة القليلة مقارنة بذوي الخبرة الكبيرة. ما دور الخبرة؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: الخبرة مُعدِّل لأنها تغير قوة علاقة التدريب بالأداء."],"source":null,"table":[]},{"title":"تمرين 3 | تحديد الوسيط","body":["المسألة: تساهم القيادة بالقيم في تعزيز الولاء التنظيمي الذي يزيد الأداء. أرسم مسار العلاقة.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: القيادة بالقيم (مستقل) → الولاء التنظيمي (وسيط) → الأداء (تابع)."],"source":null,"table":[]},{"title":"تمرين 4 | العامل العرضي","body":["المسألة: تريد تقدير أثر التدريب على الإنتاجية، لكن بعض الموظفين يستخدمون معدات أحدث. كيف تعامل المعدات؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: تعد عاملًا آخر محتملًا يحتاج ضبطًا أو قياسًا في التصميم حتى لا يختلط أثره بأثر التدريب."],"source":null,"table":[]},{"title":"مسألة رقمية تدريبية إضافية","body":["المعطيات: أنتجت مجموعة متدربة في مثال افتراضي 9 وحدات يوميًا، ومجموعة أخرى 6 وحدات. ما الفرق؟","ورقة حفظ مركزة قبل الاختبار"],"example":["النتيجة | الحل خطوة بخطوة: 9 − 6 = 3 وحدات يوميًا. الفرق لا يثبت بمفرده أن التدريب هو السبب."],"source":null,"table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"الإطار النظري هو أساسًا:","options":["شبكة منطقية للعلاقات بين المتغيرات","قائمة مراجع فقط","النتيجة النهائية","أداة جمع بيانات فقط"],"correct":0,"explain":"شبكة منطقية للعلاقات بين المتغيرات"},{"num":2,"kind":"mc","question":"المتغير هو خاصية:","options":["يمكن أن تتخذ قيمًا مختلفة","تبقى ثابتة دائمًا","تعني السبب دائمًا","لا يمكن تسجيلها بأي صورة"],"correct":0,"explain":"يمكن أن تتخذ قيمًا مختلفة"},{"num":3,"kind":"mc","question":"في «تأثير التدريب على الإنتاجية» المتغير التابع هو:","options":["التدريب","نوع الاستبانة","اسم المؤسسة","الإنتاجية"],"correct":3,"explain":"الإنتاجية"},{"num":4,"kind":"mc","question":"المتغير المستقل في الدراسة نفسها هو:","options":["التدريب","الإنتاجية","حجم التقرير","نتيجة التحليل"],"correct":0,"explain":"التدريب"},{"num":5,"kind":"mc","question":"المتغير الذي يغير قوة علاقة X بـY يسمى:","options":["مُعدِّلًا","مقياسًا نسبيًا","تابعًا فقط","متغيرًا اسميًا"],"correct":0,"explain":"مُعدِّلًا"},{"num":6,"kind":"mc","question":"المتغير الذي يشرح مسار انتقال الأثر يسمى:","options":["عنوانًا","معترضًا إحصائيًا عشوائيًا","مُعدِّلًا بالضرورة","وسيطًا"],"correct":3,"explain":"وسيطًا"},{"num":7,"kind":"mc","question":"«الولاء التنظيمي» بين القيادة والأداء مثال على:","options":["نتيجة نهائية وحدها","أداة ترميز","متغير وسيط","مقياس فتري"],"correct":2,"explain":"متغير وسيط"},{"num":8,"kind":"mc","question":"«المهارة الإدارية» التي تحدد الاستفادة من تنوع الفريق مثال على:","options":["متغير اسمي","فرضية صفرية","متغير تابع فقط","متغير مُعدِّل"],"correct":3,"explain":"متغير مُعدِّل"},{"num":9,"kind":"mc","question":"في الشرائح، يرتبط المتغير المعترض خصوصًا بـ:","options":["عامل يظهر في مسار زمني بين المستقل والتابع","حذف المراجع","طريقة ترتيب الفقرات","رمز المبحوث"],"correct":0,"explain":"عامل يظهر في مسار زمني بين المستقل والتابع"},{"num":10,"kind":"mc","question":"عامل آخر قد يربك العلاقة ويُراد ضبطه يسمى:","options":["الفرضية البديلة","متغيرًا عرضيًا","عنوان البحث","مقياس ليكرت"],"correct":1,"explain":"متغيرًا عرضيًا"},{"num":11,"kind":"mc","question":"عند سؤال «متى يكون أثر التدريب أقوى؟» نفكر في:","options":["المتغير المُعدِّل","المنوال","الوسيط حصريًا","المقياس الاسمي"],"correct":0,"explain":"المتغير المُعدِّل"},{"num":12,"kind":"mc","question":"عند سؤال «كيف يؤثر X في Y؟» نفكر في:","options":["حجم الصفحة","الترتيب الزمني وحده","المسار الوسيط","نوع الخط"],"correct":2,"explain":"المسار الوسيط"},{"num":13,"kind":"mc","question":"أحد مكونات الإطار النظري:","options":["إخفاء الشكل التوضيحي","استبعاد كل متغير","حذف الأدبيات السابقة","تحديد اتجاه العلاقات وتفسيرها"],"correct":3,"explain":"تحديد اتجاه العلاقات وتفسيرها"},{"num":14,"kind":"mc","question":"يمكن أن يصبح المتغير نفسه مُعدِّلًا بدل مستقل عندما:","options":["يُكتب بالأحمر","تكبر العينة فقط","يتغير اسمه في الملف","يتغير دوره في العلاقة الموصوفة"],"correct":3,"explain":"يتغير دوره في العلاقة الموصوفة"},{"num":15,"kind":"mc","question":"العلاقة السالبة تعني أن:","options":["ارتفاع أحد المتغيرين يرتبط بانخفاض الآخر","لا يوجد ارتباط قطعًا","العلاقة سببية مؤكدة","كلا المتغيرين يرتفع دائمًا"],"correct":0,"explain":"ارتفاع أحد المتغيرين يرتبط بانخفاض الآخر"},{"num":16,"kind":"tf","question":"الإطار النظري يصف شبكة العلاقات بين المتغيرات.","options":["صح","خطأ"],"correct":true,"explain":"صح — الإطار النظري يصف شبكة العلاقات بين المتغيرات."},{"num":17,"kind":"tf","question":"المتغير لا يتبدل بين الأفراد أو الأوقات.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — المتغير خاصية يمكن أن تختلف قيمها."},{"num":18,"kind":"tf","question":"المتغير التابع هو النتيجة المراد تفسيرها.","options":["صح","خطأ"],"correct":true,"explain":"صح — المتغير التابع هو النتيجة المراد تفسيرها."},{"num":19,"kind":"tf","question":"المستقل هو العامل التفسيري في النموذج.","options":["صح","خطأ"],"correct":true,"explain":"صح — المستقل هو العامل التفسيري في النموذج."},{"num":20,"kind":"tf","question":"المُعدِّل يغير قوة العلاقة أو اتجاهها.","options":["صح","خطأ"],"correct":true,"explain":"صح — المُعدِّل يغير قوة العلاقة أو اتجاهها."},{"num":21,"kind":"tf","question":"المُعدِّل يفسر دائمًا الآلية الداخلية للأثر.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — المُعدِّل يغير قوة العلاقة؛ الوسيط يشرح مسار التأثير."},{"num":22,"kind":"tf","question":"الولاء التنظيمي وسيط محتمل في علاقة القيادة بالأداء.","options":["صح","خطأ"],"correct":true,"explain":"صح — الولاء التنظيمي وسيط محتمل في علاقة القيادة بالأداء."},{"num":23,"kind":"tf","question":"الخبرة السابقة قد تكون عاملًا عرضيًا يحتاج ضبطًا.","options":["صح","خطأ"],"correct":true,"explain":"صح — الخبرة السابقة قد تكون عاملًا عرضيًا يحتاج ضبطًا."},{"num":24,"kind":"tf","question":"المتغير المعترض في عرض المحاضرة له بعد زمني.","options":["صح","خطأ"],"correct":true,"explain":"صح — المتغير المعترض في عرض المحاضرة له بعد زمني."},{"num":25,"kind":"tf","question":"قد تتغير وظيفة المتغير بحسب شكل الفرضية.","options":["صح","خطأ"],"correct":true,"explain":"صح — قد تتغير وظيفة المتغير بحسب شكل الفرضية."},{"num":26,"kind":"tf","question":"العلاقة السالبة تعني بالضرورة عدم وجود ارتباط.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — العلاقة السالبة تعني اتجاهًا معاكسًا للتغير."},{"num":27,"kind":"tf","question":"كل سهم مرسوم بين متغيرين يثبت علاقة سببية علميًا.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — رسم سهم فرضي لا يثبت سببية دون دليل."},{"num":28,"kind":"tf","question":"وجود رسم توضيحي أحد مكونات الإطار النظري.","options":["صح","خطأ"],"correct":true,"explain":"صح — وجود رسم توضيحي أحد مكونات الإطار النظري."},{"num":29,"kind":"tf","question":"يمكن أن يتضمن البحث أكثر من متغير تابع.","options":["صح","خطأ"],"correct":true,"explain":"صح — يمكن أن يتضمن البحث أكثر من متغير تابع."},{"num":30,"kind":"tf","question":"لا أهمية لمراجعة الدراسات السابقة عند بناء الإطار.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الأدبيات أساس بناء العلاقات المتوقعة."},{"num":31,"kind":"short","question":"اشرح المقصود بمفهوم «الإطار النظري» واذكر مثالًا يوضحه.","options":[],"answer":"الإطار النظري: هو نموذج يشرح شبكة العلاقات المنطقية بين المتغيرات المرتبطة بمشكلة البحث بالاستفادة من الأدبيات السابقة.  مثال: نموذج يربط جودة التدريب بالتعلم ويضع الحاجة للنمو عاملًا قد يغيّر قوة العلاقة."},{"num":32,"kind":"short","question":"اشرح المقصود بمفهوم «معنى المتغير» واذكر مثالًا يوضحه.","options":[],"answer":"معنى المتغير: المتغير خاصية أو كمية تتخذ قيمًا أو فئات مختلفة بين أفراد أو أزمنة.  مثال: إنتاج العامل 1 وحدة في دقيقة و5 وحدات في دقيقة أخرى؛ تغير في الزمن."},{"num":33,"kind":"short","question":"اشرح المقصود بمفهوم «أهمية مراجعة الأدبيات في بناء الإطار» واذكر مثالًا يوضحه.","options":[],"answer":"أهمية مراجعة الأدبيات في بناء الإطار: تُبنى العلاقات المتوقعة على المعرفة والدراسات السابقة؛ لذلك يعد الإطار النظري أساسًا منطقيًا للخطوات اللاحقة.  مثال: دراسات سابقة تربط التدريب بالأداء تساعد على صياغة مسار النموذج."},{"num":34,"kind":"short","question":"اشرح المقصود بمفهوم «المتغير التابع (Dependent)» واذكر مثالًا يوضحه.","options":[],"answer":"المتغير التابع (Dependent): هو النتيجة أو الظاهرة التي يريد الباحث تفسير تغيرها أو التنبؤ بها.  مثال: في «أثر التدريب على الإنتاجية»، الإنتاجية متغير تابع."},{"num":35,"kind":"short","question":"اشرح المقصود بمفهوم «المتغير المستقل (Independent)» واذكر مثالًا يوضحه.","options":[],"answer":"المتغير المستقل (Independent): هو العامل التفسيري الذي يُفترض أن يرتبط بالتغير في المتغير التابع أو يؤثر فيه.  مثال: في المثال نفسه: التدريب متغير مستقل."},{"num":36,"kind":"short","question":"اشرح المقصود بمفهوم «اتجاه العلاقة بين المتغيرات» واذكر مثالًا يوضحه.","options":[],"answer":"اتجاه العلاقة بين المتغيرات: قد تكون العلاقة موجبة أو سالبة، وقد تختلف قوة العلاقة بحسب الظروف والافتراضات.  مثال: زيادة جودة الدليل قد ترتبط بانخفاض نسبة المنتجات المعيبة: علاقة سالبة."},{"num":37,"kind":"short","question":"اشرح المقصود بمفهوم «المتغير المُعدِّل (Moderator)» واذكر مثالًا يوضحه.","options":[],"answer":"المتغير المُعدِّل (Moderator): هو متغير يغير قوة العلاقة أو اتجاهها بين المتغير المستقل والتابع؛ أي يحدد متى أو لمن تكون العلاقة أقوى.  مثال: جودة التدريب تؤثر في الرغبة في التعلم بقوة أكبر لدى الموظفين ذوي الحاجة العالية للنمو."},{"num":38,"kind":"short","question":"اشرح المقصود بمفهوم «مثال المهارات الإدارية كمُعدِّل» واذكر مثالًا يوضحه.","options":[],"answer":"مثال المهارات الإدارية كمُعدِّل: تعرض الشرائح التنوع في قوة العمل كمستقل وكفاءة المنظمة كتابع، والمهارات الإدارية كعامل يعدل أثر التنوع.  مثال: في فريق ذي تنوع عالٍ: إذا كانت مهارات الإدارة ضعيفة فقد لا يظهر التحسن نفسه."},{"num":39,"kind":"short","question":"اشرح المقصود بمفهوم «مثال العمر كمُعدِّل» واذكر مثالًا يوضحه.","options":[],"answer":"مثال العمر كمُعدِّل: يعرض المصدر مثالًا تتوقف فيه فاعلية التدريب خارج العمل على عمر المتدرب، فيختلف الأثر بين فئات العمر.  مثال: التدريب قد يرتبط بإنتاجية أعلى لفئة عمرية دون أخرى في بيانات المثال الافتراضي بالمحاضرة."},{"num":40,"kind":"short","question":"اشرح المقصود بمفهوم «المتغير الوسيط (Mediator)» واذكر مثالًا يوضحه.","options":[],"answer":"المتغير الوسيط (Mediator): متغير يفسر مسار انتقال أثر المستقل إلى التابع أو الآلية التي عبرها تظهر العلاقة.  مثال: قد تعزز القيادة الولاء، ويسهم الولاء بدوره في رفع الأداء."},{"num":41,"kind":"short","question":"اشرح المقصود بمفهوم «المتغير المعترض أو الفاصل (Intervening)» واذكر مثالًا يوضحه.","options":[],"answer":"المتغير المعترض أو الفاصل (Intervening): تستخدمه المحاضرة لوصف عامل يظهر بين بداية أثر المستقل وظهور النتيجة، مع التأكيد على التسلسل الزمني.  مثال: تنوع القوة العاملة ← تنشيط الابتكار مع الزمن ← كفاءة المنظمة."},{"num":42,"kind":"short","question":"اشرح المقصود بمفهوم «المتغير العرضي (Extraneous)» واذكر مثالًا يوضحه.","options":[],"answer":"المتغير العرضي (Extraneous): عامل آخر محتمل قد يؤثر في العلاقة الأصلية بين المتغيرين، ويهتم الباحث بضبطه أو مراعاته.  مثال: تقييم أثر التدريب على الإنتاجية قد يتأثر باختلاف الخبرة السابقة للموظفين."},{"num":43,"kind":"short","question":"اشرح المقصود بمفهوم «الفرق بين المُعدِّل والوسيط» واذكر مثالًا يوضحه.","options":[],"answer":"الفرق بين المُعدِّل والوسيط: المُعدِّل يجيب «متى أو لمن تتغير قوة العلاقة؟»؛ والوسيط يجيب «كيف أو لماذا يحدث الأثر؟».  مثال: العمر كمُعدِّل: يغير تأثير التدريب. الولاء كوسيط: يشرح طريق تأثير القيادة على الأداء."},{"num":44,"kind":"short","question":"اشرح المقصود بمفهوم «مكونات الإطار النظري الخمسة» واذكر مثالًا يوضحه.","options":[],"answer":"مكونات الإطار النظري الخمسة: تحدد الشرائح تسمية المتغيرات، وبيان العلاقات بينها، وافتراض اتجاهها، وشرح أسباب توقعها اعتمادًا على الأدبيات، ورسم مخطط يوضح النموذج.  مثال: جودة التدريب → إتقان المهارة → الإنتاجية، مع مهارة المدرب كعامل مُعدِّل محتمل."},{"num":45,"kind":"short","question":"اشرح المقصود بمفهوم «العلاقات الموجبة والسالبة» واذكر مثالًا يوضحه.","options":[],"answer":"العلاقات الموجبة والسالبة: تصف العلاقة الموجبة تغيرًا في الاتجاه نفسه والسالبة تغيرًا عكسيًا، ويمكن أن تكون العلاقة خطية أو غير خطية.  مثال: إذا رُمز الأداء الأعلى بقيم أكبر، فمن المتوقع علاقة موجبة بين التمرين الجيد والأداء."},{"num":46,"kind":"case","question":"[المتغيرات الأساسية] دراسة «أثر الإنفاق الإعلاني على المبيعات». حدد المستقل والتابع.","options":[],"answer":"المستقل هو الإنفاق الإعلاني، والتابع هو المبيعات."},{"num":47,"kind":"case","question":"[تحديد المُعدِّل] أثر التدريب في الأداء أعلى لدى ذوي الخبرة القليلة مقارنة بذوي الخبرة الكبيرة. ما دور الخبرة؟","options":[],"answer":"الخبرة مُعدِّل لأنها تغير قوة علاقة التدريب بالأداء."},{"num":48,"kind":"case","question":"[تحديد الوسيط] تساهم القيادة بالقيم في تعزيز الولاء التنظيمي الذي يزيد الأداء. أرسم مسار العلاقة.","options":[],"answer":"القيادة بالقيم (مستقل) → الولاء التنظيمي (وسيط) → الأداء (تابع)."},{"num":49,"kind":"case","question":"[العامل العرضي] تريد تقدير أثر التدريب على الإنتاجية، لكن بعض الموظفين يستخدمون معدات أحدث. كيف تعامل المعدات؟","options":[],"answer":"تعد عاملًا آخر محتملًا يحتاج ضبطًا أو قياسًا في التصميم حتى لا يختلط أثره بأثر التدريب."},{"num":50,"kind":"case","question":"[الموقفان المختلفان] قد تؤثر الحاجة للنمو بنفسها في التعلم، أو تُغيّر أثر جودة التدريب في التعلم. ما الفرق؟","options":[],"answer":"في الحالة الأولى مستقل إضافي، وفي الثانية مُعدِّل يؤثر على قوة العلاقة بين التدريب والتعلم."}]},{"id":4,"title":"تنمية الفرضيات وصياغة عنوان البحث","source":"المحاضرة الثالثة والرابعة، الشرائح 28–45","units":[{"title":"الفرضية العلمية: المعنى والبناء","steps":[{"title":"تعريف الفرضية","body":["الفرضية إجابة أو تفسير مؤقت ومبني على معرفة سابقة لسؤال بحثي، ويخضع للفحص بالبيانات.","لا تعني الفرضية رأيًا شخصيًا مؤكدًا؛ ينبغي أن تكون واضحة وقابلة للاختبار وربط متغيرات أو توزيع متوقع."],"example":["«توجد علاقة موجبة بين جودة التدريب ومستوى الإنتاجية» فرضية يمكن قياسها."],"source":"الشريحة 28.","table":[]},{"title":"موقع الفرضية في سير البحث","body":["تُصاغ الفروض بعد تحديد المشكلة والمتغيرات وبناء إطار نظري يستند إلى الأدبيات.","تحدد الفرضية نوع البيانات المطلوبة وطريقة القياس والتحليل اللاحق."],"example":["إذا كانت الفرضية عن الفرق في الأداء بين مجموعتين، فعلى التصميم جمع نتائج قابلة للمقارنة."],"source":"الشريحة 28.","table":[]},{"title":"صفات الفرضية الجيدة","body":["توضح الشرائح أنها واضحة وموجزة ومعقولة ومسنودة بالدراسات السابقة وقابلة للفحص وتحدد العلاقة والمتغيرات تعريفًا إجرائيًا.","إذا لم نستطع تعريف متغيراتها أو قياسها فلن نستطيع اختبارها بشكل مقنع."],"example":["عبارة «الشركات الناجحة رائعة» ليست فرضية قابلة للقياس، بينما «ترتبط سرعة الاستجابة برضا العميل» أدق."],"source":"الشريحة 29.","table":[]},{"title":"صياغة الفروض بالاستقراء","body":["يبدأ الاستقراء من ملاحظات وحقائق جزئية ثم يُقترح نمط أو علاقة عامة قابلة للاختبار.","الملاحظة المتكررة أساس للاقتراح لا لإثبات التعميم مسبقًا."],"example":["ملاحظة انخفاض الأخطاء في عدة فرق تلقت تدريبًا تقود لفرضية عن التدريب والأخطاء."],"source":"الشريحة 30.","table":[]},{"title":"صياغة الفروض بالاستنباط","body":["يبدأ الاستنباط من نظرية أو مبدأ عام ويشتق توقعًا خاصًا مناسبًا للسياق.","يساعد في ربط الفرضية بنموذج مفاهيمي قائم بدل بناء توقع بلا أساس."],"example":["من نظرية التعلم بالممارسة تُشتق فرضية عن أثر التمرين العملي في الأداء."],"source":"الشريحة 30.","table":[]},{"title":"أهمية الفرضيات","body":["توجه جمع البيانات، وتحدد العلاقات التي ستُختبر، وتربط النظرية بالواقع وتساعد على تفسير النتائج.","الفرضية الجيدة تُسهّل اتخاذ قرارات مسبقة حول المتغيرات وطرق التحليل، وتمنع توسع البحث بلا هدف."],"example":["بدل جمع أي شيء عن المؤسسة، تُجمع معلومات التدريب والأداء عند اختبار علاقتهما."],"source":"الشريحة 31.","table":[]}]},{"title":"أشكال الفرضيات بحسب الصياغة","steps":[{"title":"الجمل الشرطية (If–Then)","body":["تصاغ على هيئة «إذا حدث X، فإن Y سيتغير/يحدث».","تصلح عندما تكون العلاقة المتوقعة محددة بما يكفي لتُختبر، لا لتمثل وعدًا قطعيًا."],"example":["إذا زادت ساعات التدريب الجيد فستتحسن مهارات الموظفين في متوسط المجموعة."],"source":"الشريحة 33.","table":[]},{"title":"الفرضية الاتجاهية (Directional)","body":["تنص على اتجاه العلاقة أو الفرق المتوقع: زيادة، نقصان، أعلى، أقل.","تستخدم عندما يعطي الإطار النظري مسوغًا لاتجاه محدد."],"example":["يرتبط التدريب بزيادة الإنتاجية؛ أو متوسط رضى مجموعة أ أعلى من ب."],"source":"الشريحة 34.","table":[]},{"title":"الفرضية غير الاتجاهية (Non-directional)","body":["تتوقع وجود علاقة أو فرق، دون تحديد إن كان موجبًا أو سالبًا.","ملائمة حين لا يدعم الدليل اتجاهًا واحدًا بثقة."],"example":["توجد علاقة بين ساعات العمل والرضا الوظيفي."],"source":"الشريحة 35.","table":[]},{"title":"الفرضية الصفرية (H0)","body":["تقرر عدم وجود علاقة أو فرق وفق صياغة الاختبار الإحصائي.","تستعمل أساسًا مرجعيًا في اختبار الفرضيات؛ رفضها أو عدم رفضها يعتمد على الأدلة ومستوى الدلالة المحدد."],"example":["لا يوجد فرق في متوسط الأداء بين مجموعتي التدريب والمقارنة."],"source":"الشريحة 36.","table":[]},{"title":"الفرضية البديلة (H1)","body":["تتوقع وجود علاقة أو فرق ويمكن أن تكون اتجاهية أو غير اتجاهية.","الفرضية البديلة تُقابل الصفرية؛ لا يكفي ظهور فرق في العينة وحده للحكم بالقبول."],"example":["يوجد فرق في متوسط الأداء بين المجموعتين."],"source":"الشريحة 37.","table":[]},{"title":"الفرق بين البديلة والاتجاهية","body":["«بديلة» تصف علاقتها بالفرضية الصفرية؛ و«اتجاهية» تصف تحديد اتجاه العلاقة أو الفرق.","يمكن للفرضية البديلة أن تكون اتجاهية (أكبر من) أو غير اتجاهية (يختلف عن)."],"example":["H1: متوسط أ ≠ متوسط ب = بديلة غير اتجاهية. H1: أ > ب = بديلة اتجاهية."],"source":"الشريحة 37.","table":[]}]},{"title":"أنواع الفرضيات بحسب موضوعها","steps":[{"title":"الفرضية الوصفية (Descriptive)","body":["تتعلق بوجود متغير أو حجمه أو توزيعه في المجتمع.","قد تختبر نسبة أو متوسطًا أو انتشار ظاهرة بدل علاقة بين متغيرين."],"example":["أكثر من نصف العملاء يستخدمون الخدمات الإلكترونية أسبوعيًا."],"source":"الشريحة 40.","table":[]},{"title":"الفرضية الارتباطية (Relational)","body":["تتوقع علاقة بين متغيرين أو أكثر دون الجزم بأن أحدهما سبب الآخر.","قد يرتبط تغير المتغيرين بعامل ثالث؛ لذلك لا تفسر الارتباط وحده كسببية."],"example":["توجد علاقة بين الرضا الوظيفي والالتزام المؤسسي."],"source":"الشريحة 41.","table":[]},{"title":"الفرضية السببية (Causal)","body":["تفترض أن تغير متغير يؤدي إلى تغير في متغير آخر.","يتطلب اختبار السببية تصميمًا أقوى من مجرد جمع آراء في وقت واحد."],"example":["تؤدي زيادة التدريب المصمم جيدًا إلى انخفاض أخطاء العمل وفق اختبار مناسب."],"source":"الشريحة 42.","table":[]}]},{"title":"عنوان البحث وتطويره","steps":[{"title":"وظيفة عنوان البحث","body":["يوضح العنوان موضوع البحث ومجاله ومشكلته ومتغيراته الأساسية بإيجاز.","العنوان الجيد يعد القارئ بما ستبحثه فعلًا، فلا يستخدم مصطلحات واسعة يتعذر الوفاء بها."],"example":["«أثر جودة التدريب على إنتاجية العاملين في مصانع مدينة محددة» أوضح من «التدريب والتنمية»."],"source":"الشريحة 43.","table":[]},{"title":"صفات العنوان الجيد","body":["تذكر الشرائح الإيجاز والشمول والوضوح، مع تحديد المتغيرات والمجتمع أو المجال الزمني/المكاني عند الحاجة.","تشير الشرائح إلى أن بعض الباحثين يفضل ألا يزيد العنوان عن 15 كلمة، لكن الأهم الدقة لا الالتزام العددي الجامد."],"example":["تجنب «دراسة مهمة جدًا عن كل مشكلات الإدارة»؛ حدّد المتغيرات والمجتمع."],"source":"الشريحة 44.","table":[]},{"title":"تدرج صياغة العنوان","body":["تشرح الشرائح الانتقال من موضوع بالغ العمومية إلى عنوان أكثر تحديدًا بالمجال والمتغيرات والسياق.","ابدأ بمجال عام، ثم عيّن الظاهرة والعلاقة والمجتمع والفترة إن كانت لازمة.","خرائط ذهنية ورسومات تعليمية قابلة للتعديل"],"example":["«السياسات الإدارية» ← «أثر سياسات التدريب على إنتاجية العمال في قطاع معين»."],"source":"الشريحة 45.","table":[]},{"title":"خريطة ذهنية متفرعة: موضوعات المحاضرة","body":[],"example":[],"source":null,"table":[[["الفرضية العلمية: المعنى والبناء","↘","أشكال الفرضيات بحسب الصياغة"],["أنواع الفرضيات بحسب موضوعها","تنمية الفرضيات وصياغة عنوان البحث","عنوان البحث وتطويره"],["تعريف الفرضية","↖","موقع الفرضية في سير البحث"]]]},{"title":"الرسم 2: تسلسل المفاهيم","body":["جداول المقارنة والمراجعة السريعة"],"example":[],"source":null,"table":[]},{"title":"أنواع الفروض","body":[],"example":[],"source":null,"table":[[["المصطلح","سؤال التمييز","مثال"],["اتجاهية","هل يحدد الاتجاه؟","يزيد التدريب الإنتاجية"],["غير اتجاهية","علاقة دون اتجاه؟","توجد علاقة بين التدريب والإنتاجية"],["صفرية","هل ينفي وجود فرق/علاقة؟","لا فرق بين متوسطَي الأداء"],["بديلة","هل يتوقع فرقًا/علاقة؟","يوجد فرق بين متوسطَي الأداء"]]]},{"title":"بحسب موضوع الفرضية","body":["تمارين محلولة خطوة بخطوة"],"example":[],"source":null,"table":[[["النوع","تتناول","مثال"],["وصفية","حجم أو توزيع متغير","60% يستخدمون الخدمة"],["ارتباطية","ارتباط دون جزم بالسبب","الرضا يرتبط بالإنتاجية"],["سببية","أثر يؤدي لنتيجة","تغيير الحافز يرفع الأداء"]]]},{"title":"تمرين 1 | تحويل سؤال لفرضية","body":["المسألة: سؤال: «ما العلاقة بين التدريب والإنتاجية؟» صغ فرضية اتجاهية وأخرى غير اتجاهية.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: الاتجاهية: ترتبط ساعات التدريب الجيد إيجابًا بالإنتاجية. غير الاتجاهية: توجد علاقة بين ساعات التدريب والإنتاجية."],"source":null,"table":[]},{"title":"تمرين 2 | H0 وH1","body":["المسألة: نريد مقارنة متوسط الرضا بين مجموعتين. اكتب فرضيتين صفريّة وبديلة غير اتجاهية.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: H0: لا يوجد فرق في متوسط الرضا بين المجموعتين؛ H1: يوجد فرق في متوسط الرضا بينهما."],"source":null,"table":[]},{"title":"تمرين 3 | نوع الفرضية","body":["المسألة: «أكثر من 70% من العملاء يستخدمون التطبيق». ما نوع الفرضية؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: وصفية لأنها تتوقع نسبة أو توزيعًا لمتغير واحد."],"source":null,"table":[]},{"title":"تمرين 4 | ارتباط أم سببية؟","body":["المسألة: «ترتبط ساعات النوم بالأداء الدراسي». هل تفترض العبارة السببية؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: لا؛ هي ارتباطية لأنها لا تقول إن النوم سبب النتيجة."],"source":null,"table":[]},{"title":"مسألة رقمية تدريبية إضافية","body":["المعطيات: افترض أن 35 من أصل 50 مشاركًا يستخدمون تطبيقًا. ما النسبة لدعم فرضية وصفية؟","ورقة حفظ مركزة قبل الاختبار"],"example":["النتيجة | الحل خطوة بخطوة: 35 ÷ 50 × 100 = 70%. ثم تُفحص الفرضية بأسلوب مناسب للتصميم والعينة."],"source":null,"table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"الفرضية هي:","options":["حقيقة ثابتة لا تقبل المراجعة","عنوان دون متغيرات","قائمة مصادر","تفسير أو إجابة مؤقتة قابلة للاختبار"],"correct":3,"explain":"تفسير أو إجابة مؤقتة قابلة للاختبار"},{"num":2,"kind":"mc","question":"تُصاغ الفرضيات عادة بعد:","options":["إعلان النتائج النهائية","نشر البحث فقط","بناء الإطار النظري ومراجعة الأدبيات","اختيار لون الاستبانة"],"correct":2,"explain":"بناء الإطار النظري ومراجعة الأدبيات"},{"num":3,"kind":"mc","question":"أي خاصية من خصائص الفرضية الجيدة؟","options":["وضوح وقابلية قياس واختبار","الغموض والعمومية","التأكيد على النتيجة دون دليل","عدم ارتباطها بالمشكلة"],"correct":0,"explain":"وضوح وقابلية قياس واختبار"},{"num":4,"kind":"mc","question":"الاستقراء ينتقل من:","options":["نظرية عامة إلى حالة خاصة","نتائج نهائية إلى بيانات","ملاحظات جزئية إلى تعميم محتمل","تعريف إلى عنوان فقط"],"correct":2,"explain":"ملاحظات جزئية إلى تعميم محتمل"},{"num":5,"kind":"mc","question":"الاستنباط ينتقل من:","options":["قاعدة عامة إلى توقع محدد","إجابة إلى سؤال","مثال فردي إلى قانون حتمي","عينة إلى مجتمع بلا اختبار"],"correct":0,"explain":"قاعدة عامة إلى توقع محدد"},{"num":6,"kind":"mc","question":"«إذا زادت جودة الخدمة زاد رضا العملاء» مثال على:","options":["فرضية وصفية حصريًا","عنوان بحث","فرضية شرطية","عدم وجود علاقة"],"correct":2,"explain":"فرضية شرطية"},{"num":7,"kind":"mc","question":"فرضية تذكر أن العلاقة موجبة تسمى:","options":["غير اتجاهية","تاريخية","صفرية بالضرورة","اتجاهية"],"correct":3,"explain":"اتجاهية"},{"num":8,"kind":"mc","question":"«توجد علاقة بين التدريب والرضا» دون اتجاه هي:","options":["اتجاهية سالبة","غير اتجاهية","اتجاهية موجبة","صفرية"],"correct":1,"explain":"غير اتجاهية"},{"num":9,"kind":"mc","question":"H0 تشير عادة إلى:","options":["العنوان المختصر","الأهداف فقط","عدم وجود فرق أو علاقة وفق الاختبار","وجود علاقة موجبة بالضرورة"],"correct":2,"explain":"عدم وجود فرق أو علاقة وفق الاختبار"},{"num":10,"kind":"mc","question":"H1 تشير عادة إلى:","options":["قائمة العينة","وجود علاقة أو فرق متوقع","خطة جمع البيانات","عدم وجود أثر دائمًا"],"correct":1,"explain":"وجود علاقة أو فرق متوقع"},{"num":11,"kind":"mc","question":"يمكن أن تكون H1:","options":["غير قابلة للاختبار","اتجاهية أو غير اتجاهية","اتجاهية فقط","صفرية فقط"],"correct":1,"explain":"اتجاهية أو غير اتجاهية"},{"num":12,"kind":"mc","question":"«أكثر من نصف العملاء يستخدمون الخدمة» فرضية:","options":["سببية","ارتباطية بين متغيرين","وصفية","تجريبية فقط"],"correct":2,"explain":"وصفية"},{"num":13,"kind":"mc","question":"«توجد علاقة بين الرضا والإنتاجية» فرضية:","options":["صفرية","ارتباطية","سببية مؤكدة","وصفية لمتغير وحيد"],"correct":1,"explain":"ارتباطية"},{"num":14,"kind":"mc","question":"«زيادة التدريب تؤدي إلى تقليل الأخطاء» صياغة:","options":["اسمية","وصفية","صفرية","سببية"],"correct":3,"explain":"سببية"},{"num":15,"kind":"mc","question":"العنوان البحثي الجيد يكون:","options":["نسخة حرفية من النتيجة","خاليًا من المشكلة","غامضًا وطويلًا عمدًا","واضحًا ومختصرًا ويعكس موضوع الدراسة"],"correct":3,"explain":"واضحًا ومختصرًا ويعكس موضوع الدراسة"},{"num":16,"kind":"tf","question":"الفرضية تفسير مؤقت لا حقيقة نهائية.","options":["صح","خطأ"],"correct":true,"explain":"صح — الفرضية تفسير مؤقت لا حقيقة نهائية."},{"num":17,"kind":"tf","question":"يمكن اختبار فرضية دون معرفة ما الذي سيتم قياسه.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — ينبغي تحديد مؤشرات القياس لاختبار الفرضية."},{"num":18,"kind":"tf","question":"الدراسات السابقة تساعد على صياغة الفروض.","options":["صح","خطأ"],"correct":true,"explain":"صح — الدراسات السابقة تساعد على صياغة الفروض."},{"num":19,"kind":"tf","question":"الاستقراء ينتقل من الجزئي إلى العام المحتمل.","options":["صح","خطأ"],"correct":true,"explain":"صح — الاستقراء ينتقل من الجزئي إلى العام المحتمل."},{"num":20,"kind":"tf","question":"الاستنباط ينتقل من العام إلى الخاص.","options":["صح","خطأ"],"correct":true,"explain":"صح — الاستنباط ينتقل من العام إلى الخاص."},{"num":21,"kind":"tf","question":"الفرضية الاتجاهية تحدد اتجاه الفرق أو العلاقة.","options":["صح","خطأ"],"correct":true,"explain":"صح — الفرضية الاتجاهية تحدد اتجاه الفرق أو العلاقة."},{"num":22,"kind":"tf","question":"الفرضية غير الاتجاهية تذكر اتجاهًا موجبًا بالضرورة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — غير الاتجاهية لا تحدد اتجاه العلاقة."},{"num":23,"kind":"tf","question":"H0 في الاختبار المعتاد تنفي وجود فرق أو علاقة.","options":["صح","خطأ"],"correct":true,"explain":"صح — H0 في الاختبار المعتاد تنفي وجود فرق أو علاقة."},{"num":24,"kind":"tf","question":"H1 يمكن أن تكون اتجاهية أو غير اتجاهية.","options":["صح","خطأ"],"correct":true,"explain":"صح — H1 يمكن أن تكون اتجاهية أو غير اتجاهية."},{"num":25,"kind":"tf","question":"الفرضية الوصفية تتناول توزيع متغير.","options":["صح","خطأ"],"correct":true,"explain":"صح — الفرضية الوصفية تتناول توزيع متغير."},{"num":26,"kind":"tf","question":"كل ارتباط بين متغيرين يثبت أن أحدهما سبب الآخر.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الارتباط لا يثبت السببية وحده."},{"num":27,"kind":"tf","question":"الفرضية السببية تتوقع أثر متغير في آخر.","options":["صح","خطأ"],"correct":true,"explain":"صح — الفرضية السببية تتوقع أثر متغير في آخر."},{"num":28,"kind":"tf","question":"العنوان ينبغي أن يعكس موضوع البحث ومتغيراته.","options":["صح","خطأ"],"correct":true,"explain":"صح — العنوان ينبغي أن يعكس موضوع البحث ومتغيراته."},{"num":29,"kind":"tf","question":"الأفضل أن يكون عنوان البحث أطول ما يمكن دون حاجة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — العنوان الأفضل واضح ومختصر بالقدر المناسب."},{"num":30,"kind":"tf","question":"المفاهيم الغامضة غير القابلة للقياس صالحة دائمًا لفرضيات جيدة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — ينبغي تعريف المتغيرات بطريقة قابلة للقياس."},{"num":31,"kind":"short","question":"اشرح المقصود بمفهوم «تعريف الفرضية» واذكر مثالًا يوضحه.","options":[],"answer":"تعريف الفرضية: الفرضية إجابة أو تفسير مؤقت ومبني على معرفة سابقة لسؤال بحثي، ويخضع للفحص بالبيانات.  مثال: «توجد علاقة موجبة بين جودة التدريب ومستوى الإنتاجية» فرضية يمكن قياسها."},{"num":32,"kind":"short","question":"اشرح المقصود بمفهوم «موقع الفرضية في سير البحث» واذكر مثالًا يوضحه.","options":[],"answer":"موقع الفرضية في سير البحث: تُصاغ الفروض بعد تحديد المشكلة والمتغيرات وبناء إطار نظري يستند إلى الأدبيات.  مثال: إذا كانت الفرضية عن الفرق في الأداء بين مجموعتين، فعلى التصميم جمع نتائج قابلة للمقارنة."},{"num":33,"kind":"short","question":"اشرح المقصود بمفهوم «صفات الفرضية الجيدة» واذكر مثالًا يوضحه.","options":[],"answer":"صفات الفرضية الجيدة: توضح الشرائح أنها واضحة وموجزة ومعقولة ومسنودة بالدراسات السابقة وقابلة للفحص وتحدد العلاقة والمتغيرات تعريفًا إجرائيًا.  مثال: عبارة «الشركات الناجحة رائعة» ليست فرضية قابلة للقياس، بينما «ترتبط سرعة الاستجابة برضا العميل» أدق."},{"num":34,"kind":"short","question":"اشرح المقصود بمفهوم «صياغة الفروض بالاستقراء» واذكر مثالًا يوضحه.","options":[],"answer":"صياغة الفروض بالاستقراء: يبدأ الاستقراء من ملاحظات وحقائق جزئية ثم يُقترح نمط أو علاقة عامة قابلة للاختبار.  مثال: ملاحظة انخفاض الأخطاء في عدة فرق تلقت تدريبًا تقود لفرضية عن التدريب والأخطاء."},{"num":35,"kind":"short","question":"اشرح المقصود بمفهوم «صياغة الفروض بالاستنباط» واذكر مثالًا يوضحه.","options":[],"answer":"صياغة الفروض بالاستنباط: يبدأ الاستنباط من نظرية أو مبدأ عام ويشتق توقعًا خاصًا مناسبًا للسياق.  مثال: من نظرية التعلم بالممارسة تُشتق فرضية عن أثر التمرين العملي في الأداء."},{"num":36,"kind":"short","question":"اشرح المقصود بمفهوم «أهمية الفرضيات» واذكر مثالًا يوضحه.","options":[],"answer":"أهمية الفرضيات: توجه جمع البيانات، وتحدد العلاقات التي ستُختبر، وتربط النظرية بالواقع وتساعد على تفسير النتائج.  مثال: بدل جمع أي شيء عن المؤسسة، تُجمع معلومات التدريب والأداء عند اختبار علاقتهما."},{"num":37,"kind":"short","question":"اشرح المقصود بمفهوم «الجمل الشرطية (If–Then)» واذكر مثالًا يوضحه.","options":[],"answer":"الجمل الشرطية (If–Then): تصاغ على هيئة «إذا حدث X، فإن Y سيتغير/يحدث».  مثال: إذا زادت ساعات التدريب الجيد فستتحسن مهارات الموظفين في متوسط المجموعة."},{"num":38,"kind":"short","question":"اشرح المقصود بمفهوم «الفرضية الاتجاهية (Directional)» واذكر مثالًا يوضحه.","options":[],"answer":"الفرضية الاتجاهية (Directional): تنص على اتجاه العلاقة أو الفرق المتوقع: زيادة، نقصان، أعلى، أقل.  مثال: يرتبط التدريب بزيادة الإنتاجية؛ أو متوسط رضى مجموعة أ أعلى من ب."},{"num":39,"kind":"short","question":"اشرح المقصود بمفهوم «الفرضية غير الاتجاهية (Non-directional)» واذكر مثالًا يوضحه.","options":[],"answer":"الفرضية غير الاتجاهية (Non-directional): تتوقع وجود علاقة أو فرق، دون تحديد إن كان موجبًا أو سالبًا.  مثال: توجد علاقة بين ساعات العمل والرضا الوظيفي."},{"num":40,"kind":"short","question":"اشرح المقصود بمفهوم «الفرضية الصفرية (H0)» واذكر مثالًا يوضحه.","options":[],"answer":"الفرضية الصفرية (H0): تقرر عدم وجود علاقة أو فرق وفق صياغة الاختبار الإحصائي.  مثال: لا يوجد فرق في متوسط الأداء بين مجموعتي التدريب والمقارنة."},{"num":41,"kind":"short","question":"اشرح المقصود بمفهوم «الفرضية البديلة (H1)» واذكر مثالًا يوضحه.","options":[],"answer":"الفرضية البديلة (H1): تتوقع وجود علاقة أو فرق ويمكن أن تكون اتجاهية أو غير اتجاهية.  مثال: يوجد فرق في متوسط الأداء بين المجموعتين."},{"num":42,"kind":"short","question":"اشرح المقصود بمفهوم «الفرق بين البديلة والاتجاهية» واذكر مثالًا يوضحه.","options":[],"answer":"الفرق بين البديلة والاتجاهية: «بديلة» تصف علاقتها بالفرضية الصفرية؛ و«اتجاهية» تصف تحديد اتجاه العلاقة أو الفرق.  مثال: H1: متوسط أ ≠ متوسط ب = بديلة غير اتجاهية. H1: أ > ب = بديلة اتجاهية."},{"num":43,"kind":"short","question":"اشرح المقصود بمفهوم «الفرضية الوصفية (Descriptive)» واذكر مثالًا يوضحه.","options":[],"answer":"الفرضية الوصفية (Descriptive): تتعلق بوجود متغير أو حجمه أو توزيعه في المجتمع.  مثال: أكثر من نصف العملاء يستخدمون الخدمات الإلكترونية أسبوعيًا."},{"num":44,"kind":"short","question":"اشرح المقصود بمفهوم «الفرضية الارتباطية (Relational)» واذكر مثالًا يوضحه.","options":[],"answer":"الفرضية الارتباطية (Relational): تتوقع علاقة بين متغيرين أو أكثر دون الجزم بأن أحدهما سبب الآخر.  مثال: توجد علاقة بين الرضا الوظيفي والالتزام المؤسسي."},{"num":45,"kind":"short","question":"اشرح المقصود بمفهوم «الفرضية السببية (Causal)» واذكر مثالًا يوضحه.","options":[],"answer":"الفرضية السببية (Causal): تفترض أن تغير متغير يؤدي إلى تغير في متغير آخر.  مثال: تؤدي زيادة التدريب المصمم جيدًا إلى انخفاض أخطاء العمل وفق اختبار مناسب."},{"num":46,"kind":"case","question":"[تحويل سؤال لفرضية] سؤال: «ما العلاقة بين التدريب والإنتاجية؟» صغ فرضية اتجاهية وأخرى غير اتجاهية.","options":[],"answer":"الاتجاهية: ترتبط ساعات التدريب الجيد إيجابًا بالإنتاجية. غير الاتجاهية: توجد علاقة بين ساعات التدريب والإنتاجية."},{"num":47,"kind":"case","question":"[H0 وH1] نريد مقارنة متوسط الرضا بين مجموعتين. اكتب فرضيتين صفريّة وبديلة غير اتجاهية.","options":[],"answer":"H0: لا يوجد فرق في متوسط الرضا بين المجموعتين؛ H1: يوجد فرق في متوسط الرضا بينهما."},{"num":48,"kind":"case","question":"[نوع الفرضية] «أكثر من 70% من العملاء يستخدمون التطبيق». ما نوع الفرضية؟","options":[],"answer":"وصفية لأنها تتوقع نسبة أو توزيعًا لمتغير واحد."},{"num":49,"kind":"case","question":"[ارتباط أم سببية؟] «ترتبط ساعات النوم بالأداء الدراسي». هل تفترض العبارة السببية؟","options":[],"answer":"لا؛ هي ارتباطية لأنها لا تقول إن النوم سبب النتيجة."},{"num":50,"kind":"case","question":"[عنوان البحث] حسّن عنوان «التدريب ومشكلات الشركات في اليمن».","options":[],"answer":"مثال: «العلاقة بين جودة التدريب والإنتاجية لدى العاملين في شركات صناعية مختارة بمدينة عدن»."}]},{"id":5,"title":"تصميم البحث والقياس","source":"المحاضرة الخامسة","units":[{"title":"تصميم البحث وعناصره","steps":[{"title":"مفهوم تصميم البحث","body":["هو خطة متكاملة لجمع البيانات وقياسها وتحليلها للإجابة عن أسئلة البحث أو اختبار فرضياته.","يربط التصميم بين المشكلة والنتائج، ويجيب: من سندرس؟ أين؟ متى؟ وبأي أدوات وتحليل؟"],"example":["في دراسة الرضا: تحديد الفئة المستهدفة والأداة والعينة وموعد الجمع والمقارنات."],"source":"الشريحة 3.","table":[]},{"title":"عناصر التصميم العشرة","body":["تعدد الشرائح الأهداف ونوع الدراسة والتدخل والبيئة والقياس ووحدة التحليل والعينة والزمن والجمع والتحليل.","المحاضرة تتوسع في ستة محاور أساسية، لكنها تعرض العناصر العشرة جميعها؛ لا تهمل ما لم يُفصّل."],"example":["قرار المدة الزمنية يؤثر في التكلفة؛ وقرار وحدة التحليل يؤثر في اختيار العينة."],"source":"الشريحة 4.","table":[]},{"title":"الاختيار بين البدائل","body":["يتأثر التصميم بأهداف الدراسة والدقة والموارد والوقت والتكلفة وطبيعة المشكلة.","التصميم الأقوى ليس الأكثر تعقيدًا تلقائيًا؛ الأنسب هو ما يجيب بدقة ضمن القيود الواقعية."],"example":["استكشاف موضوع غير معروف قد يبدأ بمقابلات قبل مسح كمي واسع."],"source":"الشريحة 6.","table":[]}]},{"title":"أهداف الدراسة الثلاثة","steps":[{"title":"البحوث الاستكشافية (Exploratory)","body":["تستخدم عندما تكون المعلومات عن المشكلة أو متغيراتها محدودة؛ غرضها فهم الظاهرة وطرح أسئلة أو فرضيات أولية.","تعتمد كثيرًا على أدوات كيفية مثل مقابلات متعمقة ومجموعات التركيز، وقد تستعين ببيانات كمية."],"example":["استكشاف أسباب ضعف استخدام تطبيق جديد عبر مقابلات مع مستخدمين."],"source":"الشريحة 8.","table":[]},{"title":"أدوات الاستكشاف","body":["تسرد المحاضرة تحليل بيانات ثانوية، واستطلاع آراء الخبراء، ومجموعات التركيز، والتصميم على مرحلتين.","وتذكر أيضًا الملاحظة والمقابلات ودراسة الحالة والوثائق وأساليب كيفية أخرى."],"example":["ابدأ بمقابلة الخبراء ثم طوّر استبانة للتحقق من الموضوعات المتكررة."],"source":"الشريحة 12.","table":[]},{"title":"فوائد الاستكشاف","body":["تساعد على توضيح المفاهيم، وتحديد الأولويات، وتطوير الفرضيات والتعريفات الإجرائية، وتحسين التصميم النهائي وتوفير الموارد.","الاستكشاف لا يمثل بديلًا آليًا لكل تحليل كمي، بل مرحلة قد تجعل قياسك أكثر ملاءمة."],"example":["تحديد المقصود بـ«جودة الحياة الوظيفية» قبل تصميم مقياس لها."],"source":"الشريحة 9.","table":[]},{"title":"البحوث الوصفية (Descriptive)","body":["تهدف لوصف خصائص الظاهرة أو المجموعة، مثل التكرارات والنسب والأعمار والوظائف والخصائص التنظيمية.","يمكنها الإجابة عن «كم؟ ما النسبة؟ ما التوزيع؟» دون الجزم بسبب الظاهرة."],"example":["قياس نسبة العملاء المتعثرين وخصائصهم الديموغرافية."],"source":"الشريحة 14.","table":[]},{"title":"دراسات اختبار الفرضيات","body":["تختبر علاقات أو فروقًا بين متغيرات أو مجموعات، وقد تسعى لشرح الاختلافات أو توقع النتائج.","الانتقال من الوصف إلى الاختبار يتطلب وضوح المتغيرات والفرضيات والافتراضات التحليلية."],"example":["هل يرتبط الإنفاق الإعلاني بزيادة المبيعات؟ وهل متوسط الدخل مختلف بين مجموعتين؟"],"source":"الشريحة 20.","table":[]},{"title":"دراسة الحالة (Case Study)","body":["تتناول فردًا أو مجموعة أو مؤسسة بصورة متعمقة، وتشمل معلومات حالية وتاريخية وعوامل مؤثرة.","قد تقدم فهمًا عميقًا لعدد محدود من الوحدات؛ لا تستهدف بالضرورة تمثيل المجتمع إحصائيًا."],"example":["دراسة مفصلة لأسباب التحول الرقمي في بنك واحد."],"source":"الشريحة 24.","table":[]}]},{"title":"نوع الدراسة والتدخل والبيئة","steps":[{"title":"الدراسة الارتباطية (Correlational)","body":["تفحص العلاقة بين متغيرات كما تحدث، دون أن يكون للباحث بالضرورة تدخل لتعديلها.","الارتباط لا يثبت أن أحد المتغيرات سبب الآخر؛ قد يوجد عامل ثالث يفسر العلاقة."],"example":["ملاحظة علاقة بين رضا الموظفين وعدد سنوات خبرتهم."],"source":"الشريحة 28.","table":[]},{"title":"الدراسة السببية (Causal)","body":["تبحث أثر تغيير في متغير على نتيجة، وقد تتطلب تدخّلًا ومقارنة مناسبة.","التصميم التجريبي الجيد يحاول ضبط العوامل الأخرى لتمييز أثر التدخل من تغيرات عارضة."],"example":["تقديم تدريب جديد لمجموعة ومقارنة تغير الأداء بمجموعة مناسبة."],"source":"الشريحة 27.","table":[]},{"title":"مدى تدخل الباحث","body":["قد يكتفي الباحث بملاحظة ما يحدث طبيعيًا، أو يتدخل عمدًا لتغيير متغير في دراسة تجريبية.","زيادة التدخل قد تعزز اختبار علاقات سببية، لكنها ترفع متطلبات الأخلاقيات والتصميم والموارد."],"example":["ملاحظة الادخار الطبيعي مقابل تغيير سعر فائدة فرع تجريبي."],"source":"الشريحة 29.","table":[]},{"title":"بيئة الدراسة","body":["قد تكون الدراسة ميدانية في ظروف العمل الطبيعية أو في بيئة مصطنعة يُضبط فيها عدد من العوامل.","البيئة الطبيعية تعطي سياقًا واقعيًا؛ والبيئة المضبوطة تمنح تحكمًا أكبر لكنها قد تختلف عن الواقع."],"example":["اختبار سلوك العملاء في فرع بنك فعلي مقابل مختبر محاكاة."],"source":"الشريحة 31.","table":[]},{"title":"وحدة التحليل","body":["الكيان الذي يجري تحليل بياناته: فرد أو أسرة أو فريق أو مؤسسة أو غير ذلك.","لا تخلط بين وحدة جمع البيانات ووحدة التحليل؛ سؤال المدير عن الشركة لا يجعل المدير وحدة التحليل بالضرورة."],"example":["إذا أردنا قياس معدل غياب كل فرع، فقد تكون الفروع وحدات التحليل."],"source":"الشريحة 5.","table":[]},{"title":"تصميم العينة وأداة الجمع","body":["يشمل اختيار المجتمع والعينة وطرق اختيارها وحجمها، ثم اختيار الملاحظة أو المقابلة أو الاستبيان أو القياس الفعلي.","حجم العينة ونوعها يتأثران بطبيعة النتائج والتكلفة والدقة، ويؤثران في التعميم."],"example":["عينة احتمالية من العملاء للمقارنة الكمية أو مقابلات قصدية للخبراء للاستكشاف."],"source":"الشريحة 5.","table":[]}]},{"title":"المدى الزمني والأخلاقيات","steps":[{"title":"الدراسة المقطعية (Cross-sectional)","body":["تجمع البيانات مرة واحدة خلال فترة قصيرة نسبيًا للإجابة عن سؤال البحث.","قد يمتد جمعها أيامًا أو أسابيع؛ المهم أن القياس يمثل نقطة أو نافذة واحدة في الزمن."],"example":["مسح رضا العملاء في شهر واحد."],"source":"الشريحة 33.","table":[]},{"title":"الدراسة الطولية (Longitudinal)","body":["تجمع البيانات على فترات متعاقبة لقياس التغير عبر الزمن.","أكثر تكلفة غالبًا من المقطعية، وتفيد في دراسة الاتجاهات أو تغير الظاهرة."],"example":["قياس الرضا قبل سياسة جديدة وبعد ثلاثة وستة أشهر."],"source":"الشريحة 34.","table":[]},{"title":"أخلاقيات تصميم التجارب","body":["تحذر الشرائح من الضغط على الأفراد، وإخفاء المعلومات الأساسية، وتعريضهم للخطر، والإضرار بمجموعات المقارنة.","اشرح الإجراءات والمخاطر والحقوق، واحفظ السرية، واختر تدخلًا لا يعرّض المشاركين لأذى غير مبرر."],"example":["لا يجوز إجبار موظف على المشاركة في تجربة تدريبية مخفية المؤشرات المؤثرة على تقييمه."],"source":"الشريحة 38.","table":[]}]},{"title":"التعريف الإجرائي ومستويات القياس","steps":[{"title":"قياس المفاهيم المجردة","body":["بعض المتغيرات قابلة للقياس مباشرة مثل الوزن والطول، وبعضها مثل الاتجاه والرضا يحتاج مؤشرات سلوكية أو أسئلة منظمة.","التعريف الإجرائي يحول مفهومًا عامًا إلى معايير قابلة للملاحظة والقياس."],"example":["الرضا الوظيفي يمكن تمثيله باستجابات لبنود حول الأجر والبيئة وفرص النمو."],"source":"الشريحة 41.","table":[]},{"title":"التعريف الإجرائي (Operationalization)","body":["إجراء يحدد كيف ستُلاحظ الخاصية وما مؤشرها وطريقة تسجيلها.","كلما كان التعريف دقيقًا، استطاع باحث آخر تطبيق الأداة بطريقة متسقة."],"example":["الغياب: عدد الأيام المسجلة كغياب غير مبرر في سجلات آخر ثلاثة أشهر."],"source":"الشريحة 42.","table":[]},{"title":"المقياس الاسمي (Nominal)","body":["يصنف الحالات إلى فئات دون ترتيب؛ الأرقام رموز فقط.","يمكن حساب التكرارات والنسب والمنوال؛ ولا معنى لمتوسط أرقام الفئات."],"example":["التخصص العلمي أو نعم/لا."],"source":"الشريحة 44.","table":[]},{"title":"المقياس الرتبي (Ordinal)","body":["يصنف الفئات ويرتبها، لكن الفروق بينها ليست بالضرورة متساوية.","الوسيط والمنوال والتوزيعات مناسبة للوصف؛ وأرقام الرتب ليست وحدات كمية متساوية."],"example":["منخفض – متوسط – مرتفع؛ أو بند ليكرت مفرد."],"source":"الشريحة 47.","table":[]},{"title":"مقياس ليكرت","body":["تذكر الشرائح بندًا يتضمن عبارة وسلّمًا لدرجة الموافقة أو الاعتراض؛ ويمكن تجميع عدة بنود في مقياس.","توجد مناقشة منهجية بشأن معاملة البنود المفردة كرتبية ومتى يناسب تحليل درجات مركبة بأساليب إضافية."],"example":["«المعلومات متاحة في الوقت المناسب» مع خيارات من غير موافق بشدة إلى موافق بشدة."],"source":"الشريحة 50.","table":[]},{"title":"المقياس الفتري (Interval)","body":["يسمح بفروق متساوية لكنه يفتقد صفرًا حقيقيًا يدل على انعدام الخاصية.","فرق 10 درجات مئوية له المعنى نفسه في مواضع المقياس، لكن 40 مئوية ليست ضعف 20 مئوية من ناحية الحرارة الفيزيائية."],"example":["درجة الحرارة المئوية."],"source":"الشريحة 51.","table":[]},{"title":"المقياس النسبي (Ratio)","body":["يجمع خصائص الفتري مع صفر حقيقي؛ لذا يمكن تفسير نسب بين القيم في المجال المناسب.","يسمح بجميع العمليات الحسابية المعتادة على الكميات الملائمة مثل الوزن والمدة وعدد الوحدات.","خرائط ذهنية ورسومات تعليمية قابلة للتعديل"],"example":["صفر مبيعات يعني عدم بيع أي وحدة، و200 وحدة ضعف 100 وحدة."],"source":"الشريحة 53.","table":[]},{"title":"خريطة ذهنية متفرعة: موضوعات المحاضرة","body":[],"example":[],"source":null,"table":[[["تصميم البحث وعناصره","↘","أهداف الدراسة الثلاثة"],["نوع الدراسة والتدخل والبيئة","تصميم البحث وقياس المتغيرات","المدى الزمني والأخلاقيات"],["التعريف الإجرائي ومستويات القياس","↖","مفهوم تصميم البحث"]]]},{"title":"الرسم 2: تسلسل المفاهيم","body":["جداول المقارنة والمراجعة السريعة"],"example":[],"source":null,"table":[]},{"title":"أهداف الدراسة","body":[],"example":[],"source":null,"table":[[["النوع","سؤال محوري","وسيلة شائعة"],["استكشافي","ماذا يحدث ولماذا قد يحدث؟","مقابلات/مجموعات تركيز"],["وصفي","كم؟ ما الصفات والتوزيع؟","مسح وتكرارات"],["اختبار فرضيات","هل توجد علاقة أو فرق؟","تصميم وتحليل للاختبار"]]]},{"title":"المدى الزمني","body":[],"example":[],"source":null,"table":[[["النوع","التوقيت","مناسب ل"],["مقطعي","مرة واحدة أو نافذة واحدة","الوصف في وقت معين"],["طولي","مرات متتابعة","قياس التغير والاتجاه"]]]},{"title":"مستويات القياس","body":["تمارين محلولة خطوة بخطوة"],"example":[],"source":null,"table":[]},{"title":"تمرين 1 | اختيار هدف البحث","body":["المسألة: لا تتوافر معلومات كافية عن دوافع رفض خدمة جديدة؛ ما نوع الدراسة الأنسب كبداية؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: بحث استكشافي باستخدام مقابلات متعمقة أو مجموعة تركيز ثم يمكن تطوير أداة قياس."],"source":null,"table":[]},{"title":"تمرين 2 | وصف أم اختبار","body":["المسألة: يحسب باحث متوسط أعمار العاملين ونسبة الإناث فقط. ما هدف دراسته؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: وصفية؛ لأنه يصف التوزيعات والخصائص ولا يختبر علاقة محددة."],"source":null,"table":[]},{"title":"تمرين 3 | سببي أم ارتباطي","body":["المسألة: وجد الباحث علاقة بين ساعات التدريب وأداء الموظفين دون تدخل. هل أثبت السببية؟","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: لا؛ دليل ارتباطي فقط. الإثبات السببي يحتاج تصميمًا يحد من التفسيرات البديلة."],"source":null,"table":[]},{"title":"تمرين 4 | زمني","body":["المسألة: قاس الباحث رضا الأسر في يناير ثم أبريل ثم يوليو. صنف الدراسة.","خطوة 1: حدد المفاهيم أو المتغيرات الرئيسية التي تظهر في الحالة.","خطوة 2: اربط الحالة بالتعريف أو المقارنة التي تعلمتها في الوحدة المناسبة."],"example":["الحل | الحل النموذجي: طولية لأنها تتابع القياس عبر فترات زمنية متعددة."],"source":null,"table":[]},{"title":"مسألة رقمية تدريبية إضافية","body":["المعطيات: في بيانات افتراضية، 18 من 45 طالبًا يدرسون المحاسبة. كم نسبتهم؟ وما مقياس متغير التخصص؟","ورقة حفظ مركزة قبل الاختبار"],"example":["النتيجة | الحل خطوة بخطوة: 18 ÷ 45 × 100 = 40%. التخصص متغير اسمي، والنسبة وصف مناسب لتوزيعه."],"source":null,"table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"تصميم البحث هو:","options":["خطة لجمع وقياس وتحليل البيانات","النتيجة المتوقعة","عنوان التقرير فقط","نموذج الفاتورة"],"correct":0,"explain":"خطة لجمع وقياس وتحليل البيانات"},{"num":2,"kind":"mc","question":"من عناصر التصميم:","options":["النتائج النهائية فقط","نوع الورق فقط","وحدة التحليل والمدى الزمني والعينة","أسماء المحكمين فقط"],"correct":2,"explain":"وحدة التحليل والمدى الزمني والعينة"},{"num":3,"kind":"mc","question":"عندما تكون المعلومات قليلة نبدأ غالبًا بـ:","options":["دراسة استكشافية","اختبار سببي معقد بالضرورة","تعميم نتيجة","حذف الأدلة"],"correct":0,"explain":"دراسة استكشافية"},{"num":4,"kind":"mc","question":"أي أداة شائعة للاستكشاف؟","options":["مجموعة تركيز","المتوسط بلا بيانات","اختبار عشوائي فقط","تحليل الفروق حصريًا"],"correct":0,"explain":"مجموعة تركيز"},{"num":5,"kind":"mc","question":"الهدف من الدراسات الوصفية:","options":["إنكار وجود فروق","إثبات السببية دائمًا","إخفاء الظاهرة","وصف خصائص وتوزيعات ظاهرة"],"correct":3,"explain":"وصف خصائص وتوزيعات ظاهرة"},{"num":6,"kind":"mc","question":"دراسة الفروق بين متوسطي مجموعتين تندرج غالبًا ضمن:","options":["اختبار الفرضيات","تصنيف الملفات","الاستكشاف حصريًا","المدخلات"],"correct":0,"explain":"اختبار الفرضيات"},{"num":7,"kind":"mc","question":"دراسة مؤسسة واحدة بعمق تسمى:","options":["دراسة حالة","دراسة تجريبية فقط","استقراء محض","دراسة تعداد شامل دائمًا"],"correct":0,"explain":"دراسة حالة"},{"num":8,"kind":"mc","question":"العلاقة الارتباطية وحدها:","options":["لا تثبت سببية المتغيرات","تستلزم التدخل دائمًا","تعني انعدام العلاقة","تثبت السببية قطعًا"],"correct":0,"explain":"لا تثبت سببية المتغيرات"},{"num":9,"kind":"mc","question":"لدراسة الأثر السببي، يفيد عادة:","options":["اختيار إجابة مفضلة","ملاحظة عابرة واحدة","ضبط المتغيرات والتدخل ومجموعة مقارنة مناسبة","حذف مجموعة المقارنة"],"correct":2,"explain":"ضبط المتغيرات والتدخل ومجموعة مقارنة مناسبة"},{"num":10,"kind":"mc","question":"تجمع الدراسة المقطعية البيانات:","options":["على فترات متباعدة متكررة","دائمًا خلال عشر سنوات","في وقت أو نافذة واحدة","بعد نشر النتائج فقط"],"correct":2,"explain":"في وقت أو نافذة واحدة"},{"num":11,"kind":"mc","question":"الدراسة الطولية تتضمن:","options":["غياب زمن القياس","تغيير الاسم فقط","قياسات في أوقات متعددة","ملاحظة واحدة دائمًا"],"correct":2,"explain":"قياسات في أوقات متعددة"},{"num":12,"kind":"mc","question":"تحويل «الرضا» إلى أسئلة قابلة للقياس يسمى:","options":["التوزيع العشوائي","النتيجة النهائية","التعريف الإجرائي","مراجعة المراجع"],"correct":2,"explain":"التعريف الإجرائي"},{"num":13,"kind":"mc","question":"ما المقياس المناسب لفصيلة الدم؟","options":["رتبي","فتري","نسبي","اسمي"],"correct":3,"explain":"اسمي"},{"num":14,"kind":"mc","question":"«منخفض، متوسط، مرتفع» مستوى:","options":["رتبي","نسبي","اسمي فقط","فتري قطعًا"],"correct":0,"explain":"رتبي"},{"num":15,"kind":"mc","question":"ما المقياس الذي يمتلك صفرًا حقيقيًا؟","options":["فتري","نسبي","اسمي","رتبي"],"correct":1,"explain":"نسبي"},{"num":16,"kind":"tf","question":"تصميم البحث يشمل تخطيط جمع البيانات وتحليلها.","options":["صح","خطأ"],"correct":true,"explain":"صح — تصميم البحث يشمل تخطيط جمع البيانات وتحليلها."},{"num":17,"kind":"tf","question":"لا علاقة للمدى الزمني بتصميم البحث.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — المدى الزمني أحد عناصر التصميم."},{"num":18,"kind":"tf","question":"البحث الاستكشافي مناسب عندما تكون المعلومات محدودة.","options":["صح","خطأ"],"correct":true,"explain":"صح — البحث الاستكشافي مناسب عندما تكون المعلومات محدودة."},{"num":19,"kind":"tf","question":"مجموعات التركيز من تقنيات الاستكشاف.","options":["صح","خطأ"],"correct":true,"explain":"صح — مجموعات التركيز من تقنيات الاستكشاف."},{"num":20,"kind":"tf","question":"الدراسة الوصفية تهتم بالتكرارات والخصائص.","options":["صح","خطأ"],"correct":true,"explain":"صح — الدراسة الوصفية تهتم بالتكرارات والخصائص."},{"num":21,"kind":"tf","question":"اختبار الفرضيات قد يدرس الفروق بين مجموعات.","options":["صح","خطأ"],"correct":true,"explain":"صح — اختبار الفرضيات قد يدرس الفروق بين مجموعات."},{"num":22,"kind":"tf","question":"دراسة الحالة تركز على مفردة أو عدد قليل من المفردات بعمق.","options":["صح","خطأ"],"correct":true,"explain":"صح — دراسة الحالة تركز على مفردة أو عدد قليل من المفردات بعمق."},{"num":23,"kind":"tf","question":"الارتباط وحده دليل قاطع على السببية.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الارتباط وحده لا يثبت السببية."},{"num":24,"kind":"tf","question":"التحكم في المتغيرات مهم عند اختبار السببية.","options":["صح","خطأ"],"correct":true,"explain":"صح — التحكم في المتغيرات مهم عند اختبار السببية."},{"num":25,"kind":"tf","question":"الدراسة المقطعية تكرر القياس على فترات سنوات دائمًا.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — المقطعية تجمع البيانات مرة واحدة ضمن نافذة زمنية."},{"num":26,"kind":"tf","question":"الدراسة الطولية تتضمن قياسًا عبر الزمن.","options":["صح","خطأ"],"correct":true,"explain":"صح — الدراسة الطولية تتضمن قياسًا عبر الزمن."},{"num":27,"kind":"tf","question":"الضغط على الأفراد للمشاركة في تجربة سلوك أخلاقي.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — المشاركة يجب ألا تقوم على الإكراه."},{"num":28,"kind":"tf","question":"التعريف الإجرائي يحدد كيفية ملاحظة المفهوم وقياسه.","options":["صح","خطأ"],"correct":true,"explain":"صح — التعريف الإجرائي يحدد كيفية ملاحظة المفهوم وقياسه."},{"num":29,"kind":"tf","question":"الأرقام في المقياس الاسمي يمكن جمعها لإنتاج معنى كمي.","options":["صح","خطأ"],"correct":false,"explain":"خطأ — الأرقام الاسمية رموز تصنيف بلا معنى حسابي."},{"num":30,"kind":"tf","question":"الصفر الحقيقي من خصائص المقياس النسبي.","options":["صح","خطأ"],"correct":true,"explain":"صح — الصفر الحقيقي من خصائص المقياس النسبي."},{"num":31,"kind":"short","question":"اشرح المقصود بمفهوم «مفهوم تصميم البحث» واذكر مثالًا يوضحه.","options":[],"answer":"مفهوم تصميم البحث: هو خطة متكاملة لجمع البيانات وقياسها وتحليلها للإجابة عن أسئلة البحث أو اختبار فرضياته.  مثال: في دراسة الرضا: تحديد الفئة المستهدفة والأداة والعينة وموعد الجمع والمقارنات."},{"num":32,"kind":"short","question":"اشرح المقصود بمفهوم «عناصر التصميم العشرة» واذكر مثالًا يوضحه.","options":[],"answer":"عناصر التصميم العشرة: تعدد الشرائح الأهداف ونوع الدراسة والتدخل والبيئة والقياس ووحدة التحليل والعينة والزمن والجمع والتحليل.  مثال: قرار المدة الزمنية يؤثر في التكلفة؛ وقرار وحدة التحليل يؤثر في اختيار العينة."},{"num":33,"kind":"short","question":"اشرح المقصود بمفهوم «الاختيار بين البدائل» واذكر مثالًا يوضحه.","options":[],"answer":"الاختيار بين البدائل: يتأثر التصميم بأهداف الدراسة والدقة والموارد والوقت والتكلفة وطبيعة المشكلة.  مثال: استكشاف موضوع غير معروف قد يبدأ بمقابلات قبل مسح كمي واسع."},{"num":34,"kind":"short","question":"اشرح المقصود بمفهوم «البحوث الاستكشافية (Exploratory)» واذكر مثالًا يوضحه.","options":[],"answer":"البحوث الاستكشافية (Exploratory): تستخدم عندما تكون المعلومات عن المشكلة أو متغيراتها محدودة؛ غرضها فهم الظاهرة وطرح أسئلة أو فرضيات أولية.  مثال: استكشاف أسباب ضعف استخدام تطبيق جديد عبر مقابلات مع مستخدمين."},{"num":35,"kind":"short","question":"اشرح المقصود بمفهوم «أدوات الاستكشاف» واذكر مثالًا يوضحه.","options":[],"answer":"أدوات الاستكشاف: تسرد المحاضرة تحليل بيانات ثانوية، واستطلاع آراء الخبراء، ومجموعات التركيز، والتصميم على مرحلتين.  مثال: ابدأ بمقابلة الخبراء ثم طوّر استبانة للتحقق من الموضوعات المتكررة."},{"num":36,"kind":"short","question":"اشرح المقصود بمفهوم «فوائد الاستكشاف» واذكر مثالًا يوضحه.","options":[],"answer":"فوائد الاستكشاف: تساعد على توضيح المفاهيم، وتحديد الأولويات، وتطوير الفرضيات والتعريفات الإجرائية، وتحسين التصميم النهائي وتوفير الموارد.  مثال: تحديد المقصود بـ«جودة الحياة الوظيفية» قبل تصميم مقياس لها."},{"num":37,"kind":"short","question":"اشرح المقصود بمفهوم «البحوث الوصفية (Descriptive)» واذكر مثالًا يوضحه.","options":[],"answer":"البحوث الوصفية (Descriptive): تهدف لوصف خصائص الظاهرة أو المجموعة، مثل التكرارات والنسب والأعمار والوظائف والخصائص التنظيمية.  مثال: قياس نسبة العملاء المتعثرين وخصائصهم الديموغرافية."},{"num":38,"kind":"short","question":"اشرح المقصود بمفهوم «دراسات اختبار الفرضيات» واذكر مثالًا يوضحه.","options":[],"answer":"دراسات اختبار الفرضيات: تختبر علاقات أو فروقًا بين متغيرات أو مجموعات، وقد تسعى لشرح الاختلافات أو توقع النتائج.  مثال: هل يرتبط الإنفاق الإعلاني بزيادة المبيعات؟ وهل متوسط الدخل مختلف بين مجموعتين؟"},{"num":39,"kind":"short","question":"اشرح المقصود بمفهوم «دراسة الحالة (Case Study)» واذكر مثالًا يوضحه.","options":[],"answer":"دراسة الحالة (Case Study): تتناول فردًا أو مجموعة أو مؤسسة بصورة متعمقة، وتشمل معلومات حالية وتاريخية وعوامل مؤثرة.  مثال: دراسة مفصلة لأسباب التحول الرقمي في بنك واحد."},{"num":40,"kind":"short","question":"اشرح المقصود بمفهوم «الدراسة الارتباطية (Correlational)» واذكر مثالًا يوضحه.","options":[],"answer":"الدراسة الارتباطية (Correlational): تفحص العلاقة بين متغيرات كما تحدث، دون أن يكون للباحث بالضرورة تدخل لتعديلها.  مثال: ملاحظة علاقة بين رضا الموظفين وعدد سنوات خبرتهم."},{"num":41,"kind":"short","question":"اشرح المقصود بمفهوم «الدراسة السببية (Causal)» واذكر مثالًا يوضحه.","options":[],"answer":"الدراسة السببية (Causal): تبحث أثر تغيير في متغير على نتيجة، وقد تتطلب تدخّلًا ومقارنة مناسبة.  مثال: تقديم تدريب جديد لمجموعة ومقارنة تغير الأداء بمجموعة مناسبة."},{"num":42,"kind":"short","question":"اشرح المقصود بمفهوم «مدى تدخل الباحث» واذكر مثالًا يوضحه.","options":[],"answer":"مدى تدخل الباحث: قد يكتفي الباحث بملاحظة ما يحدث طبيعيًا، أو يتدخل عمدًا لتغيير متغير في دراسة تجريبية.  مثال: ملاحظة الادخار الطبيعي مقابل تغيير سعر فائدة فرع تجريبي."},{"num":43,"kind":"short","question":"اشرح المقصود بمفهوم «بيئة الدراسة» واذكر مثالًا يوضحه.","options":[],"answer":"بيئة الدراسة: قد تكون الدراسة ميدانية في ظروف العمل الطبيعية أو في بيئة مصطنعة يُضبط فيها عدد من العوامل.  مثال: اختبار سلوك العملاء في فرع بنك فعلي مقابل مختبر محاكاة."},{"num":44,"kind":"short","question":"اشرح المقصود بمفهوم «وحدة التحليل» واذكر مثالًا يوضحه.","options":[],"answer":"وحدة التحليل: الكيان الذي يجري تحليل بياناته: فرد أو أسرة أو فريق أو مؤسسة أو غير ذلك.  مثال: إذا أردنا قياس معدل غياب كل فرع، فقد تكون الفروع وحدات التحليل."},{"num":45,"kind":"short","question":"اشرح المقصود بمفهوم «تصميم العينة وأداة الجمع» واذكر مثالًا يوضحه.","options":[],"answer":"تصميم العينة وأداة الجمع: يشمل اختيار المجتمع والعينة وطرق اختيارها وحجمها، ثم اختيار الملاحظة أو المقابلة أو الاستبيان أو القياس الفعلي.  مثال: عينة احتمالية من العملاء للمقارنة الكمية أو مقابلات قصدية للخبراء للاستكشاف."},{"num":46,"kind":"case","question":"[اختيار هدف البحث] لا تتوافر معلومات كافية عن دوافع رفض خدمة جديدة؛ ما نوع الدراسة الأنسب كبداية؟","options":[],"answer":"بحث استكشافي باستخدام مقابلات متعمقة أو مجموعة تركيز ثم يمكن تطوير أداة قياس."},{"num":47,"kind":"case","question":"[وصف أم اختبار] يحسب باحث متوسط أعمار العاملين ونسبة الإناث فقط. ما هدف دراسته؟","options":[],"answer":"وصفية؛ لأنه يصف التوزيعات والخصائص ولا يختبر علاقة محددة."},{"num":48,"kind":"case","question":"[سببي أم ارتباطي] وجد الباحث علاقة بين ساعات التدريب وأداء الموظفين دون تدخل. هل أثبت السببية؟","options":[],"answer":"لا؛ دليل ارتباطي فقط. الإثبات السببي يحتاج تصميمًا يحد من التفسيرات البديلة."},{"num":49,"kind":"case","question":"[زمني] قاس الباحث رضا الأسر في يناير ثم أبريل ثم يوليو. صنف الدراسة.","options":[],"answer":"طولية لأنها تتابع القياس عبر فترات زمنية متعددة."},{"num":50,"kind":"case","question":"[مستوى القياس] حدد مستوى: فصيلة الدم، درجة الرضا المفردة، الحرارة المئوية، عدد الأطفال.","options":[],"answer":"اسمي، رتبي، فتري، نسبي بالترتيب."}]},{"id":6,"title":"المقاييس والصدق والثبات","source":"المحاضرة السادسة","units":[{"title":"المدخل إلى القياس","steps":[{"title":"ما القياس؟","body":["القياس في البحث هو استخدام قواعد وأسئلة أو أدوات منظمة لإسناد أوصاف أو قيم لخصائص الأشخاص أو الأشياء أو المواقف، بما يسمح بوصفها وتحليلها. أحيانًا نجمع فئات مثل التخصص؛ وأحيانًا نجمع درجات مثل الرضا؛ وأحيانًا نقيس مقادير مثل العمر والدخل."],"example":["باحث يريد تقييم خدمات جامعة: يسأل عن التخصص (تصنيف)، ودرجة الرضا (تقييم)، وترتيب أولويات التحسين (ترتيب). تختلف الإجابات رغم أنها تنتمي للدراسة نفسها."],"source":"الشرائح 1–4","table":[]},{"title":"العوامل السبعة لاختيار المقياس المناسب  —  Selecting a Measurement Scale","body":[],"example":[],"source":"الشرائح 1–4","table":[[["العامل في المحاضرة","سؤال عملي يسهل تذكره"],["أهداف الباحث | Researcher Objectives","لماذا أقيس: اتجاهات المبحوثين أم أحكامهم على تصميم/منتج؟"],["أنواع الاستجابات | Response Types","هل يحتاج المبحوث إلى تقييم أم ترتيب أم تصنيف؟"],["خصائص البيانات | Data Properties","هل الناتج اسمي أم رتبي أم فتري أم نسبي؟"],["متوازن/غير متوازن | Balanced/Unbalanced","هل الأقطاب الإيجابية والسلبية موزعة بالتساوي؟"],["إجباري/غير إجباري | Forced/Unforced","هل أتيح «لا أعرف/لا رأي»؟"],["عدد نقاط المقياس | Number of Scale Points","هل أستخدم ثلاثًا أم خمسًا أم سبع نقاط؟"],["أخطاء المبحوثين | Rater Errors","هل ينحاز المستجيب إلى المنتصف أو التساهل أو التشدد؟"]]]},{"title":"1) أهداف الباحث","body":["تذكر الشرائح هدفين: (أ) قياس خصائص المبحوثين واتجاهاتهم وآرائهم؛ (ب) استخدام المبحوثين كمحكمين لخصائص أشياء معروضة عليهم. مثال: تسأل شركة هل تؤيد تغيير العلامة التجارية؟ (قياس اتجاه). ثم تعرض تصاميم جديدة ويقيّمها العملاء المؤيدون للتغيير (تحكيم خيارات)."],"example":[],"source":"الشرائح 1–4","table":[]},{"title":"2) أنواع الاستجابات","body":["من المهم فصل طريقة الإجابة عن طبيعة المتغير نفسه. فقد يستخدم السؤال متعدد الخيارات بيانات اسمية، وقد يستخدم السؤال الرقمي بيانات نسبية. التفاصيل في الوحدة التالية."],"example":[],"source":"الشرائح 1–4","table":[]},{"title":"3) خصائص البيانات","body":["المعلومات التي يوفرها المقياس تحدد العمليات الإحصائية المناسبة. استخدام أرقام كرموز للفئات لا يحولها إلى قياسات عددية حقيقية."],"example":[],"source":"الشرائح 1–4","table":[]},{"title":"4–5) التوازن والإجبار","body":["التوازن يرتبط بتوزيع خيارات التقييم حول نقطة وسط أو بين اتجاهين؛ والإجبار يتعلق بإلزام الشخص باختيار إجابة من دون إتاحة خيار مستقل لعدم إبداء الرأي."],"example":[],"source":"الشرائح 1–4","table":[]},{"title":"6) عدد نقاط المقياس","body":["ثلاث نقاط قد تكون سهلة لكنها قليلة التفصيل؛ وخمس أو سبع نقاط تمنح قدرة أكبر على التمييز بين الاتجاهات، لكنها قد تزيد العبء الذهني. لم تخصص الشرائح تفصيلًا مستقلًا لهذا العامل، ولذلك فهذا توضيح تعليمي مكمل."],"example":[],"source":"الشرائح 1–4","table":[]},{"title":"7) أخطاء المقيمين","body":["حتى أفضل المقياس تصميمًا قد يتأثر بإجابات لا تعكس الرأي الحقيقي؛ لذلك يجب وصف الخيارات بدقة وتجنب الكلمات المبهمة."],"example":[],"source":"الشرائح 1–4","table":[]}]},{"title":"أنواع الاستجابات ومستويات القياس","steps":[{"title":"ثلاثة أنواع من الاستجابات  —  Response Types","body":[],"example":["احفظها في ثلاث كلمات:  Rating = كم درجته؟  |  Ranking = من الأول؟  |  Categorization = في أي فئة؟"],"source":"الشرائح 4–5","table":[[["النوع","التعريف السهل","مثال"],["Rating – تقييم","إعطاء درجة لشيء دون مقارنته مباشرة بغيره في السؤال نفسه","قيّم الخدمة من 1 إلى 5"],["Ranking – ترتيب","ترتيب أشياء من الأفضل للأقل تفضيلًا","رتّب ثلاث خدمات حسب الأولوية"],["Categorization – تصنيف","تحديد الفئة التي ينتمي إليها شخص أو خاصية","نوع الدراسة: بكالوريوس/ماجستير"]]]},{"title":"أ) الاسمي (Nominal)","body":["يسمح بتصنيف القيم فقط، دون ترتيب منطقي. مثل فصيلة الدم أو نوع التخصص. لو رمزنا «إدارة» بالرقم 1 و«محاسبة» بالرقم 2 فلا يعني ذلك أن المحاسبة ضعف الإدارة أو أعلى منها."],"example":[],"source":"الشرائح 4–5","table":[]},{"title":"ب) الرتبي (Ordinal)","body":["يسمح بالتصنيف والترتيب، لكن المسافات بين الرتب ليست بالضرورة متساوية. مثل: ضعيف، متوسط، جيد، ممتاز؛ أو المراكز في مسابقة."],"example":[],"source":"الشرائح 4–5","table":[]},{"title":"ج) الفتري (Interval)","body":["له فروق عددية متساوية بين القيم لكن الصفر ليس دلالة على انعدام الخاصية. المثال التقليدي: درجة الحرارة بالمئوية؛ فالفرق من 20 إلى 30 يساوي الفرق من 30 إلى 40، ولا تعني 40°م ضعف 20°م حراريًا."],"example":[],"source":"الشرائح 4–5","table":[]},{"title":"د) النسبي (Ratio)","body":["يجمع ميزات الفتري ويضيف صفرًا حقيقيًا يدل على غياب الكمية. أمثلته الوزن والطول والسن وعدد الأطفال. إذا كان الوزن 80 كجم مقابل 40 كجم فالأول ضعف الثاني."],"example":[],"source":"الشرائح 4–5","table":[]},{"title":"خريطة ذهنية قابلة للتعديل: مستويات القياس","body":["خط التطور المفاهيمي: تصنيف ← ترتيب ← فروق متساوية ← صفر حقيقي. هذا التدرج يعبر عن خصائص إضافية متاحة للتحليل، وليس حكمًا بأن جميع الدراسات يجب أن تستخدم بيانات نسبية."],"example":["فخ امتحاني:  إذا كانت الفئات مرمزة بالأرقام 1 و2 و3 فلا تحكم مباشرة بأنها بيانات كمية. اسأل: هل الأرقام كميات فعلية أم مجرد رموز؟"],"source":"الشرائح 4–5","table":[[["الاسمي","الرتبي","الفتري","النسبي"],["فئات مختلفة","فئات + ترتيب","ترتيب + مسافات ثابتة","كل ما سبق + صفر حقيقي"],["مثال: نوع التخصص","مثال: درجة الرضا","مثال: الحرارة °م","مثال: الوزن/الدخل"]]]}]},{"title":"توازن الإجابات والتحيزات","steps":[{"title":"المقياس المتوازن وغير المتوازن  —  Balanced vs. Unbalanced","body":["المقياس المتوازن يحتوي عددًا متساويًا من خيارات التفضيل وعدم التفضيل، مع إمكانية وجود خيار وسط أو عدم وجوده.","تذكر المحاضرة حالتين قد يدفعان لاستخدام المقياس غير المتوازن: توقع تركز الاستجابات في جانب واحد، أو محاولة تقليل بعض أنماط التساهل/التشدد. تنبيه منهجي إضافي: قد يوجه عدم التوازن إجابات المشاركين، ولذلك يحتاج إلى مبرر بحثي واضح."],"example":[],"source":"الشرائح 6–10","table":[]},{"title":"الاختيارات الإجبارية وغير الإجبارية  —  Forced vs. Unforced","body":["المقياس الإجباري يطلب اختيار إجابة من الخيارات المتاحة. أما غير الإجباري فيوفر خيارًا مستقلًا مثل «لا أعرف» أو «لا رأي». يكون الإلزام مضللًا إذا كان بعض المبحوثين يجهلون الموضوع فعلًا؛ إذ قد يخمنون فتتأثر النتائج."],"example":["ملاحظة مهمة:  في المحاضرة يظهر مصطلح «اختيار إجباري» أيضًا ضمن مقاييس الترتيب. هناك يعني ترتيب أو مفاضلة خيارات محددة، وليس فقط منع اختيار «لا أعرف»."],"source":"الشرائح 6–10","table":[[["الاختيار","متى يعني ماذا؟"],["محايد","أفهم موضوع السؤال، لكنني لا أميل مع أو ضد"],["لا أعرف","لا أملك المعلومات التي تتيح لي الحكم"],["لا أرغب في الإجابة","أفضّل عدم الإفصاح عن الإجابة"]]]},{"title":"أخطاء المبحوثين أو المقيمين  —  Rater Errors","body":["تقترح الشرائح ضبط وصف الخيارات، والتمييز الواضح لنقطة الوسط، وزيادة عدد الخيارات عندما يكون ذلك مناسبًا. إضافة تعليمية: جرّب الاستبانة على عدد صغير أولًا، واطلب منهم شرح فهمهم لعبارات الإجابة."],"example":[],"source":"الشرائح 6–10","table":[[["الخطأ","كيف يظهر؟","مثال"],["النزعة المركزية Central Tendency","اختيار الوسط كثيرًا هربًا من الأحكام الحادة","يختار 3 من 5 في جميع العبارات"],["التساهل Leniency","الميل المبالغ فيه إلى التقييم الإيجابي","يعطي كل موظف ممتاز"],["التشدد Severity / Hard Rater","الميل المبالغ فيه إلى تقييمات منخفضة","نادراً ما يمنح أكثر من 1/5"]]]}]},{"title":"مقاييس التقييم العشرة","steps":[{"title":"1. التصنيف البسيط | Simple Category","body":["يتكون من فئتين فقط؛ ويسمى ثنائيًا (Dichotomous).","كيف تتعرف عليه في الاختبار؟ الخياران فقط هما العلامة المميزة."],"example":["مثال:  هل تمتلك سيارة؟ نعم / لا."],"source":"الشرائح 11–25","table":[]},{"title":"2. خيارات متعددة – إجابة واحدة | Single Response","body":["خيارات كثيرة، لكن يسمح بإجابة واحدة فقط.","كيف تتعرف عليه في الاختبار؟ سؤال ذو استجابة منفردة؛ لا تخلطه بالسؤال الذي يسمح بعدة إجابات."],"example":["مثال:  ما المصدر الأساسي للأخبار؟ التلفزيون / الإنترنت / الصحف / أخرى."],"source":"الشرائح 11–25","table":[]},{"title":"3. خيارات متعددة – عدة إجابات | Multiple Response","body":["يستطيع المبحوث وضع علامة على أكثر من خيار.","كيف تتعرف عليه في الاختبار؟ يمكن اختيار 2 أو 3 أو جميع الخدمات المستخدمة."],"example":["مثال:  أي الخدمات استخدمت؟ المكتبة / الإنترنت / المواصلات / التسجيل."],"source":"الشرائح 11–25","table":[]},{"title":"4. مقياس ليكرت | Likert","body":["يقيس درجة الموافقة أو عدم الموافقة على عبارة؛ غالبًا خمس فئات، وقد تستخدم 7 أو 9.","كيف تتعرف عليه في الاختبار؟ في ترميز المحاضرة: 1 = غير موافق بشدة، 5 = موافق بشدة."],"example":["مثال:  «أشعر بالرضا عن وظيفتي»: غير موافق بشدة / غير موافق / محايد / موافق / موافق بشدة."],"source":"الشرائح 11–25","table":[]},{"title":"5. دلالات الألفاظ | Semantic Differential","body":["يضع خاصيتين متضادتين على طرفي التدريج ويحدد الشخص موقعه بينهما.","كيف تتعرف عليه في الاختبار؟ الكلمات المتقابلة مثل قوي/ضعيف هي مفتاح التعرف."],"example":["مثال:  سهل  ○—○—○—○—○  صعب."],"source":"الشرائح 11–25","table":[]},{"title":"6. المقياس الرقمي | Numerical","body":["يشبه دلالات الألفاظ مع أرقام بين طرفي المقياس.","كيف تتعرف عليه في الاختبار؟ الأرقام تساعد في اختيار موضع محدد."],"example":["مثال:  حزن شديد 1–2–3–4–5–6–7 سرور شديد."],"source":"الشرائح 11–25","table":[]},{"title":"7. التقييم المفصل | Itemized Rating","body":["خيارات بدرجات موصوفة، وقد يقيس الاحتمالية أو الأهمية وغيرها.","كيف تتعرف عليه في الاختبار؟ أوسع في استخداماته من صيغة الاتفاق في ليكرت."],"example":["مثال:  ما احتمال تركك الوظيفة؟ 1 غير متوقع إطلاقًا ← 5 متوقع جدًا."],"source":"الشرائح 11–25","table":[]},{"title":"8. المجموع الثابت | Constant Sum","body":["توزيع مقدار نقاط ثابت على عدة خصائص وفق أهميتها النسبية.","كيف تتعرف عليه في الاختبار؟ المجموع يجب أن يساوي الرقم المحدد."],"example":["مثال:  وزع 100 نقطة على رائحة الصابون/لونه/شكله/حجمه/رغوته."],"source":"الشرائح 11–25","table":[]},{"title":"9. ستابل | Stapel","body":["درجات موجبة وسالبة حول خاصية مقيسة، في المثال +3 إلى −3 بلا صفر.","كيف تتعرف عليه في الاختبار؟ يقيس اتجاه التقييم وقوته."],"example":["مثال:  قيم مديرك في «تبني التقنية الحديثة»: +3,+2,+1,−1,−2,−3."],"source":"الشرائح 11–25","table":[]},{"title":"10. التمثيل البياني | Graphic Rating","body":["يستخدم خطًا أو تمثيلًا بصريًا لتحديد مقدار التقييم.","كيف تتعرف عليه في الاختبار؟ التجسيد البصري يسهل تحديد الإجابة."],"example":["مثال:  على تدريج من 1 سيئ جدًا إلى 10 ممتاز، ضع علامة توضح تقييمك."],"source":"الشرائح 11–25","table":[]},{"title":"جدول المقارنة الجامعة للمقاييس العشرة","body":[],"example":[],"source":"الشرائح 11–25","table":[[["المقياس","الكلمة المفتاحية","أقصر مثال"],["تصنيف بسيط","فئتان","نعم / لا"],["متعدد – واحدة","واحدة فقط","مصدر الأخبار الأساسي"],["متعدد – عدة","أكثر من اختيار","مصادر الأخبار المستخدمة"],["ليكرت","درجة الموافقة","موافق بشدة ↔ غير موافق بشدة"],["دلالات الألفاظ","صفتان متضادتان","قوي ↔ ضعيف"],["رقمي","أرقام بين طرفين","1–7 بين حزن وسرور"],["مفصل","مستويات موصوفة","احتمال ترك العمل"],["مجموع ثابت","100 نقطة مثلًا","توزيع أهمية الخصائص"],["ستابل","+ و −","+3 إلى −3"],["بياني","خط تقييم","حدد موقعك على 1–10"]]]},{"title":"مثال 1: المتوسط في ترميز ليكرت","body":["إجابات خمسة أشخاص عن عبارة واحدة: 5، 4، 3، 4، 5. إذا كان 5 يعني «موافق بشدة»، فالمتوسط الحسابي = (5+4+3+4+5) ÷ 5 = 21 ÷ 5 = 4.2. نستخدمه لوصف الميل العام وفق افتراضات طريقة التحليل، ولا نستنتج منه وحده أن المقياس صادق."],"example":[],"source":"الشرائح 11–25","table":[]},{"title":"مثال 2: المجموع الثابت","body":["الرائحة والرغوة متساويتان في الأهمية (30 نقطة لكل منهما)، واللون الأقل أهمية (10). لا ينبغي أن يتجاوز المجموع 100 في هذا المثال."],"example":["تمييز منهجي مكمل:  استجابة ليكرت المفردة ترتيبية بطبيعتها؛ بينما تعرض المحاضرة معاملتها بصورة فترية لأغراض التحليل، وهو افتراض شائع عند تحليل درجات مركبة متعددة البنود، ويحتاج إلى ملاءمة منهجية."],"source":"الشرائح 11–25","table":[[["الخاصية","الأهمية الموزعة"],["الرائحة","30"],["اللون","10"],["الشكل","15"],["الحجم","15"],["الرغوة","30"],["الإجمالي","100"]]]}]},{"title":"مقاييس الترتيب والمقارنة","steps":[{"title":"1) المقارنات الثنائية  —  Paired Comparison Scale","body":["نعرض على المبحوث زوجًا من العناصر في كل مرة، ونطلب اختيار المفضل. في مثال ثلاث صحف: القدس مقابل الأيام؛ القدس مقابل الحياة؛ والأيام مقابل الحياة. نستفيد من كل اختيار لتكوين صورة أوضح عن التفضيلات. يصلح خصوصًا عندما يكون عدد العناصر محدودًا.","مثال: أربعة منتجات → 4 × 3 ÷ 2 = 6 مقارنات. ستة منتجات → 6 × 5 ÷ 2 = 15 مقارنة. لاحظ كيف يزداد العبء بسرعة."],"example":["عدد المقارنات الثنائية (إضافة تطبيقية)\nn × (n − 1) ÷ 2\nحيث n هو عدد العناصر، بافتراض مقارنة كل زوج مرة واحدة دون تكرار أو اعتبار للترتيب."],"source":"الشرائح 26–29","table":[]},{"title":"2) الاختيار الإجباري في الترتيب  —  Forced Choice Scale","body":["يطلب ترتيب المنتجات أو الصحف من الأكثر تفضيلًا إلى الأقل. إذا طُلب ترتيب خمس مجلات، نعطي أفضلها رقم 1 والثانية 2 وهكذا حتى 5. تقارن هذه الطريقة العناصر في قائمة واحدة."],"example":[],"source":"الشرائح 26–29","table":[]},{"title":"3) المقارنات النسبية  —  Comparative Scale","body":["يختار المبحوث درجة مقارنة بشيء آخر مرجعي: هل الاستثمار في السندات أكثر فائدة أم مماثل أم أقل فائدة من الأسهم؟ الفرق هنا وجود معيار مقارنة محدد، دون إلزام بترتيب جميع العناصر."],"example":[],"source":"الشرائح 26–29","table":[[["المقياس","كيف يُطرح السؤال؟","علامة التمييز"],["ثنائي","أي أفضل: أ أم ب؟ ثم أ أم ج؟","كل زوج منفصل"],["ترتيب إجباري","رتب أ، ب، ج، د حسب الأولوية","سلسلة من الأول إلى الأخير"],["نسبي","هل أ أفضل أم أسوأ من ب؟","تقييم على مقياس نسبةً لمرجع"]]]}]},{"title":"صدق الاستبانة","steps":[{"title":"الأنواع الرئيسية الثلاثة","body":[],"example":[],"source":"الشرائح 30–32","table":[[["النوع","المقصود","مثال مختصر"],["صدق المحتوى Content Validity","مدى شمول البنود للجوانب الأساسية للمفهوم","استبانة جودة التعليم تغطي التدريس والمناهج والموارد والتقويم"],["صدق المحك Criterion-Related","ارتباط نتائج المقياس بمعيار خارجي ذي صلة","اختبار توقع النجاح مقارنة بالأداء الدراسي الفعلي"],["الصدق البنائي Construct Validity","مدى صحة تمثيل الأداة للمفهوم النظري الذي تدّعي قياسه","مقياس الثقة بالنفس يقيس الثقة لا الميل إلى إرضاء الآخرين"]]]},{"title":"صدق المحتوى وصدق المحكمين","body":["تذكر الشرائح أن صدق المحتوى يسمى أيضًا الصدق المنطقي أو صدق المحكمين. للتوضيح: يمكن عرض الاستبانة على خبراء في الموضوع؛ فيراجعون ملاءمة الأسئلة، وتغطية المجالات، ووضوح الصياغة، ومدى وجود أسئلة خارج نطاق المفهوم."],"example":[],"source":"الشرائح 30–32","table":[]},{"title":"صدق الاتساق الداخلي كما ورد في المحاضرة","body":["تُحسب معاملات الارتباط بين كل فقرة والاختبار ككل أو الدرجة الكلية للمجال الذي تنتمي إليه. إذا أظهرت فقرة علاقة غير مناسبة بمجالها، فقد يحتاج الباحث إلى مراجعة صياغتها أو انتمائها أو اتجاه ترميزها."],"example":[],"source":"الشرائح 30–32","table":[]},{"title":"صدق الاتساق البنائي كما ورد في المحاضرة","body":["تحسب معاملات الارتباط بين كل مجال من مجالات الاستبانة والدرجة الكلية للاستبانة. مثال: استبانة جودة الخدمات تتضمن السرعة والموثوقية وسلوك الموظفين؛ ونفحص علاقة كل مجال بالمجموع الكلي."],"example":["تنبيه علمي مضاف:  تقدم معاملات ارتباط الفقرة أو المجال بالدرجة الكلية أدلة جزئية على الاتساق، لكنها لا تثبت وحدها صدق المحتوى أو الصدق البنائي بجميع أبعاده. كما أن ارتباط الفقرة بدرجة كلية تحتوي الفقرة نفسها قد يتضخم؛ لذا تستخدم أحيانًا معاملات ارتباط مصححة."],"source":"الشرائح 30–32","table":[]}]},{"title":"ثبات الاستبانة","steps":[{"title":"رسم توضيحي: الصدق والثبات","body":["في الرسم: مركز الهدف يمثل القيمة الصحيحة، والنقاط تمثل القياسات المتكررة. تجمّع النقاط يعني ثباتًا أعلى، واقترابها من المركز يعني دقة أكبر في قياس القيمة الصحيحة. الشكل توضيحي؛ والرسومات المصورة ليست عناصر Word قابلة للتحرير مثل النص والجداول."],"example":[],"source":"الشرائح 33–39","table":[]},{"title":"الطرق الثلاث الرئيسية لتقدير الثبات","body":[],"example":[],"source":"الشرائح 33–39","table":[[["الطريقة","الفكرة","ما الذي نقارنه؟"],["إعادة الاختبار Test–Retest","تطبيق الاختبار نفسه مرتين في ظروف مناسبة","درجات الأشخاص في التطبيق الأول والثاني"],["النماذج المتكافئة Parallel Forms","استخدام نموذجين متكافئين من أداة واحدة","درجات الأشخاص في النموذجين"],["الاتساق الداخلي Internal Consistency","فحص تجانس الفقرات المصممة للمفهوم نفسه","علاقات درجات البنود داخل الأداة"]]]},{"title":"أ) التجزئة النصفية  —  Split-Half Reliability","body":["تطبق الاستبانة مرة واحدة؛ ثم تقسم الفقرات إلى فردية وزوجية مثلًا. نحسب درجات كل نصف، ثم الارتباط بين درجات النصفين. لتقدير ثبات الاستبانة الكاملة نستخدم صيغة سبيرمان–براون المعروضة في المحاضرة."],"example":["معادلة سبيرمان–براون\nR = (2 × r) / (1 + r)\nr معامل الارتباط بين النصفين؛ R معامل الثبات المعدل للمقياس الكامل."],"source":"الشرائح 33–39","table":[]},{"title":"مسألة محلولة 1","body":["إذا كان r = 0.70، فإن R = (2 × 0.70) / (1 + 0.70) = 1.40 / 1.70 ≈ 0.824. أي معامل الثبات المعدل يساوي 0.824 تقريبًا."],"example":[],"source":"الشرائح 33–39","table":[]},{"title":"مسألة محلولة 2","body":["إذا كان r = 0.60، فإن R = 1.20 / 1.60 = 0.75. لا تخلط بين r الأصلي وبين R بعد التصحيح."],"example":[],"source":"الشرائح 33–39","table":[]},{"title":"ب) معامل ألفا كرونباخ  —  Cronbach’s Alpha","body":["يستخدم لتقدير الاتساق الداخلي لمجموعة فقرات يفترض أنها تقيس مفهومًا مشتركًا. تحتوي الشريحتان 37 و38 على الصيغة المعتمدة على التباينات والصيغة المعيارية المعتمدة على متوسط الارتباط."],"example":["الصيغة القائمة على التباينات\nα = [k / (k − 1)] × [1 − (Σ σᵢ² / σₜ²)]\nk عدد الفقرات؛ Σ σᵢ² مجموع تباين الفقرات؛ σₜ² تباين الدرجة الكلية.","الصيغة المعيارية القائمة على الارتباطات\nα = [N × r̄] / [1 + (N − 1) × r̄]\nN عدد الفقرات؛ r̄ متوسط معاملات الارتباط بين الفقرات."],"source":"الشرائح 33–39","table":[]},{"title":"مسألة محلولة 3: صيغة التباينات","body":["المعطيات: k = 5، مجموع تباينات البنود = 10، تباين الدرجة الكلية = 30. التعويض: α = (5/4) × (1 − 10/30) = 1.25 × 0.6667 ≈ 0.833."],"example":[],"source":"الشرائح 33–39","table":[]},{"title":"مسألة محلولة 4: الصيغة المعيارية","body":["المعطيات: N = 5، متوسط ارتباط البنود = 0.50. التعويض: α = (5 × 0.50) / [1 + (5 − 1) × 0.50] = 2.5/3 ≈ 0.833."],"example":[],"source":"الشرائح 33–39","table":[]},{"title":"مسألة محلولة 5: تأثير عدد الفقرات","body":["إذا كان متوسط الارتباط 0.30 وعدد الفقرات 4، فالألفا = 1.2 / (1 + 0.9) ≈ 0.632. وإذا أصبح عدد الفقرات 8 مع بقاء متوسط الارتباط 0.30، فالألفا = 2.4 / (1 + 2.1) ≈ 0.774. زيادة الفقرات المتسقة قد تزيد الألفا، لكنها لا تضمن صدق الأداة."],"example":[],"source":"الشرائح 33–39","table":[]},{"title":"كيف تفسر قيمة ألفا؟","body":["كلما ارتفعت قيمة ألفا ضمن الاستخدام المناسب، دل ذلك غالبًا على اتساق داخلي أكبر. لكن لا توجد قيمة سحرية مناسبة لكل بحث. يستخدم بعض الباحثين 0.70 كقاعدة إرشادية شائعة، مع اختلاف المعايير حسب مرحلة تطوير الأداة وطبيعة المجال والغرض من القياس. هذه القاعدة ليست منصوصًا عليها في الشرائح، وهي توضيح إضافي."],"example":["لا تخلط:  ألفا مرتفعة لا تعني تلقائيًا أن الأداة صادقة أو أحادية البعد. قد ترتفع بسبب كثرة البنود أو تكرارها. يجب النظر في مضمون الأسئلة وافتراضات التحليل."],"source":"الشرائح 33–39","table":[]},{"title":"العلاقة بين الصدق والثبات","body":["تؤكد المحاضرة أن الثبات شرط ضروري للصدق لكنه ليس كافيًا؛ فقد تكون الأداة ثابتة وهي تقيس شيئًا مختلفًا عما صُممت لقياسه. وفي التفسير التطبيقي، يفضل القول: غياب الاتساق المطلوب يضعف أدلة الصدق، ووجود الثبات وحده لا يثبت الصدق."],"example":[],"source":"الشرائح 33–39","table":[[["السؤال","الصدق Validity","الثبات Reliability"],["ماذا يفحص؟","هل نقيس ما قصدنا قياسه؟","هل النتائج مستقرة/متسقة؟"],["كيف نفحصه؟","المحتوى، المحك، البناء، أدلة أخرى","الإعادة، النماذج، الاتساق الداخلي"],["هل يكفي بمفرده؟","يحتاج أدلة ومبررات متكاملة","لا يثبت الصدق بمفرده"]]]}]},{"title":"التطبيق المتكامل وخرائط الحفظ","steps":[{"title":"حالة دراسية: رضا الطلبة عن الخدمات الجامعية","body":[],"example":[],"source":"تطبيق تجميعي من موضوعات الشرائح 1–39","table":[[["الخطوة","المرحلة","التطبيق"],["1","الهدف","تحديد درجة الرضا وأولويات تحسين الخدمات."],["2","نوع الاستجابة","تقييم لدرجة الرضا؛ ترتيب لأولويات التحسين؛ تصنيف للتخصص."],["3","نوع البيانات","التخصص اسمي؛ الرضا المفرد رتبي؛ عمر الطالب نسبي."],["4","خيارات المقياس","ليكرت متوازن، وخيار «لا أعرف» عند الحاجة."],["5","صدق المحتوى","عرض البنود على محكمين وتغطية خدمات المكتبة والإنترنت والتسجيل."],["6","الثبات","اختبار تجريبي وحساب اتساق فقرات كل مجال متجانس."],["7","التحليل","استخدام التحليل الملائم لطبيعة المتغيرات وهدف الدراسة."]]]},{"title":"خريطة ذهنية شاملة قابلة للتعديل","body":[],"example":[],"source":"تطبيق تجميعي من موضوعات الشرائح 1–39","table":[[["الجذر: القياس البحثي"],["أولًا: اختيار المقياس ← الهدف / الاستجابة / البيانات / التوازن / الإجبار / النقاط / أخطاء المبحوثين"],["ثانيًا: نوع الإجابة ← تقييم Rating / ترتيب Ranking / تصنيف Categorization"],["ثالثًا: مستوى القياس ← اسمي / رتبي / فتري / نسبي"],["رابعًا: جودة القياس ← الصدق (محتوى/محك/بناء) + الثبات (إعادة/نماذج/اتساق داخلي)"],["خامسًا: حساب الثبات ← تجزئة نصفية + سبيرمان–براون + ألفا كرونباخ"]]]},{"title":"الكلمات المفتاحية التي تكتشف بها جواب السؤال","body":[],"example":[],"source":"تطبيق تجميعي من موضوعات الشرائح 1–39","table":[[["إذا قرأت في السؤال ...","ففكر مباشرة في ..."],["فئتان فقط","التصنيف البسيط"],["موافق بشدة/غير موافق بشدة","ليكرت"],["صفات متضادة","دلالات الألفاظ"],["توزيع 100 نقطة","المجموع الثابت"],["من +3 إلى −3","ستابل"],["زوجًا زوجًا","المقارنات الثنائية"],["إعادة القياس بعد فترة","إعادة الاختبار"],["نموذجان متكافئان","النماذج المتكافئة"],["فقرات فردية وزوجية","التجزئة النصفية"],["متوسط ارتباط البنود","ألفا كرونباخ المعياري"],["محكمون وتغطية المجال","صدق المحتوى"],["معيار خارجي","صدق المحك"],["قياس المفهوم النظري","الصدق البنائي"]]]}]}],"questions":[{"num":1,"kind":"mc","question":"الهدف من القياس في البحث هو أساسًا:","options":["تحويل الصفات إلى بيانات قابلة للتحليل","زيادة عدد الأسئلة فقط","التخلص من جميع الأخطاء"],"correct":0,"explain":"تحويل الصفات إلى بيانات قابلة للتحليل.  القياس يسند أوصافًا أو قيمًا وفق قواعد منظمة."},{"num":2,"kind":"mc","question":"سؤال «ما تخصصك الجامعي؟» يمثل:","options":["ترتيبًا","تصنيفًا","تقييمًا"],"correct":1,"explain":"تصنيفًا.  لأنه يحدد الفئة التي ينتمي إليها الفرد."},{"num":3,"kind":"mc","question":"السؤال «رتب الخدمات حسب أهميتها» يمثل:","options":["Ranking","Rating","Ratio"],"correct":0,"explain":"Ranking.  المطلوب ترتيب عناصر وفق أفضلية."},{"num":4,"kind":"mc","question":"أي مستوى قياس ليس له ترتيب منطقي؟","options":["النسبي","الرتبي","الاسمي"],"correct":2,"explain":"الاسمي.  الاسمي يميز بين الفئات فقط."},{"num":5,"kind":"mc","question":"درجة الرضا: منخفض، متوسط، مرتفع؛ تمثل غالبًا:","options":["رتبيًا","نسبيًا","اسميًا فقط"],"correct":0,"explain":"رتبيًا.  الفئات مرتبة لكن الفروق غير مضمونة التساوي."},{"num":6,"kind":"mc","question":"الحرارة بالمئوية مثال شائع على:","options":["اسمي","فتري","نسبي"],"correct":1,"explain":"فتري.  فروق متساوية لكن الصفر المئوي ليس انعدام الحرارة."},{"num":7,"kind":"mc","question":"أي المتغيرات الآتية من المستوى النسبي؟","options":["عدد الأطفال","فصيلة الدم","المركز في مسابقة"],"correct":0,"explain":"عدد الأطفال.  عدد الأطفال له صفر حقيقي."},{"num":8,"kind":"mc","question":"المقياس المتوازن يعني:","options":["وجود 5 نقاط حتمًا","تساوي خيارات الاتجاهين","وجود الخيار «لا أعرف»"],"correct":1,"explain":"تساوي خيارات الاتجاهين.  يمكن أن يوجد الوسط أو يغيب، لكن الجانبين متساويان."},{"num":9,"kind":"mc","question":"المقياس غير الإجباري يتيح:","options":["ترتيبًا كاملًا فقط","اختيار قيم موجبة وسالبة","خيارًا مثل «لا أعرف»"],"correct":2,"explain":"خيارًا مثل «لا أعرف».  يسمح بعدم إبداء الرأي."},{"num":10,"kind":"mc","question":"اختيار الوسط في كل مرة يوصف بأنه:","options":["نزعة مركزية","مقارنة نسبية","صدق محك"],"correct":0,"explain":"نزعة مركزية.  هذا خطأ النزعة المركزية."},{"num":11,"kind":"mc","question":"إعطاء جميع الموظفين «ممتاز» دون تمييز قد يعكس:","options":["تشددًا","تساهلًا","قياسًا فترِيًا"],"correct":1,"explain":"تساهلًا.  التساهل ميل للدرجات العالية."},{"num":12,"kind":"mc","question":"مقياس «نعم/لا» يسمى:","options":["ستابل","مقياسًا ثنائيًا","ليكرت"],"correct":1,"explain":"مقياسًا ثنائيًا.  يتكون من فئتين."},{"num":13,"kind":"mc","question":"عند اختيار أكثر من إجابة من قائمة:","options":["Multiple Response","Single Response","Paired Comparison"],"correct":0,"explain":"Multiple Response.  يمكن تعليم عدة خيارات."},{"num":14,"kind":"mc","question":"عبارة «أوافق بشدة» تنتمي غالبًا إلى:","options":["ليكرت","المجموع الثابت","التمثيل البياني فقط"],"correct":0,"explain":"ليكرت.  من علامات ليكرت درجة الاتفاق."},{"num":15,"kind":"mc","question":"وجود «جذاب/غير جذاب» بطرفي التدريج يميز:","options":["ألفا كرونباخ","الدلالات اللفظية","التجزئة النصفية"],"correct":1,"explain":"الدلالات اللفظية.  صفات ثنائية القطب."},{"num":16,"kind":"mc","question":"توزيع 100 نقطة على خصائص الهاتف يمثل:","options":["المجموع الثابت","الرتبي البسيط","المقارنة الثنائية"],"correct":0,"explain":"المجموع الثابت.  المجموع محدد ويُوزع وفق الأهمية."},{"num":17,"kind":"mc","question":"مقياس +3 إلى −3 الذي يضع السمة وسطه يسمى:","options":["ستابل","ليكرت","الرقمي فقط"],"correct":0,"explain":"ستابل.  هكذا يظهر مثال ستابل في المحاضرة."},{"num":18,"kind":"mc","question":"المقياس البياني يتميز باستخدام:","options":["اختبارين","خط أو تدريج مرئي","فئات اسمية فقط"],"correct":1,"explain":"خط أو تدريج مرئي.  تحدد الإجابة بصريًا على خط/تدريج."},{"num":19,"kind":"mc","question":"مقارنة أ مع ب، ثم أ مع ج، ثم ب مع ج تسمى:","options":["مقارنات ثنائية","ثباتًا داخليًا","صدق محك"],"correct":0,"explain":"مقارنات ثنائية.  تقارن كل زوج على حدة."},{"num":20,"kind":"mc","question":"عدد المقارنات الثنائية لأربعة عناصر هو:","options":["4","6","8"],"correct":1,"explain":"6.  4×3÷2=6."},{"num":21,"kind":"mc","question":"صدق الاستبانة يعني:","options":["ثبات المتوسط دائمًا","قياس ما صممت لقياسه","طول الاستبانة"],"correct":1,"explain":"قياس ما صممت لقياسه.  هذا جوهر الصدق."},{"num":22,"kind":"mc","question":"عرض الاستبانة على خبراء لفحص تغطيتها يتعلق بـ:","options":["صدق المحتوى","التجزئة النصفية","الثبات الزمني"],"correct":0,"explain":"صدق المحتوى.  الخبراء يساعدون في فحص شمول البنود وملاءمتها."},{"num":23,"kind":"mc","question":"ربط نتيجة اختبار بإنجاز خارجي فعلي يدل على:","options":["صدق المحك","مقياس ستابل","الانحياز المركزي"],"correct":0,"explain":"صدق المحك.  نستخدم معيارًا خارجيًا مناسبًا."},{"num":24,"kind":"mc","question":"تطبيق الاختبار نفسه على الأشخاص أنفسهم في وقتين هو:","options":["النماذج المتكافئة","إعادة الاختبار","صدق البناء"],"correct":1,"explain":"إعادة الاختبار.  التطبيق يتكرر لفحص الاستقرار الزمني."},{"num":25,"kind":"mc","question":"معامل ألفا كرونباخ يستخدم غالبًا لقياس:","options":["الاتساق الداخلي","حجم العينة","الارتباط المكاني"],"correct":0,"explain":"الاتساق الداخلي.  يرتبط باتساق فقرات المقياس."},{"num":26,"kind":"tf","question":"استخدام الرقمين 1 و2 لترميز نوع التخصص يجعل المتغير نسبيًا.","options":["صح","خطأ"],"correct":false,"explain":"خطأ.  الرقمان رمزان لفئات اسمية لا قياس كمي."},{"num":27,"kind":"tf","question":"المقياس الرتبي يسمح بترتيب الفئات، دون ضمان تساوي المسافات.","options":["صح","خطأ"],"correct":true,"explain":"صح.  الترتيب لا يعني تساوي الفروق."},{"num":28,"kind":"tf","question":"يمكن أن يكون مقياس التقييم متوازنًا دون نقطة حياد.","options":["صح","خطأ"],"correct":true,"explain":"صح.  يكفي تساوي جانبي التدريج."},{"num":29,"kind":"tf","question":"«محايد» و«لا أعرف» يحملان المعنى نفسه دائمًا.","options":["صح","خطأ"],"correct":false,"explain":"خطأ.  الأول موقف متوسط والثاني نقص معرفة."},{"num":30,"kind":"tf","question":"مقياس ليكرت يجب أن يتكون من خمس نقاط فقط.","options":["صح","خطأ"],"correct":false,"explain":"خطأ.  تذكر الشرائح إمكان استخدام 7 أو 9 نقاط."},{"num":31,"kind":"tf","question":"كلما زاد عدد عناصر المقارنة الثنائية زاد عدد المقارنات المطلوبة.","options":["صح","خطأ"],"correct":true,"explain":"صح.  العدد n(n−1)/2."},{"num":32,"kind":"tf","question":"صدق المحتوى يعني مقارنة نتائج الأداة بمعيار خارجي.","options":["صح","خطأ"],"correct":false,"explain":"خطأ.  هذا وصف أقرب لصدق المحك."},{"num":33,"kind":"tf","question":"النماذج المتكافئة تستخدم نموذجين يقيسان الخاصية نفسها.","options":["صح","خطأ"],"correct":true,"explain":"صح.  يُفترض تكافؤ النموذجين."},{"num":34,"kind":"tf","question":"الثبات وحده ضمان كافٍ لصدق الأداة.","options":["صح","خطأ"],"correct":false,"explain":"خطأ.  الأداة قد تكون متسقة لكنها تقيس غير المطلوب."},{"num":35,"kind":"tf","question":"ألفا كرونباخ المرتفعة تثبت وحدها أن جميع فقرات الأداة تقيس بُعدًا واحدًا.","options":["صح","خطأ"],"correct":false,"explain":"خطأ.  لا تكفي وحدها لإثبات أحادية البعد أو الصدق."},{"num":36,"kind":"short","question":"اذكر العوامل السبعة التي تؤثر في اختيار المقياس المناسب.","options":[],"answer":"الإجابة:  الأهداف؛ الاستجابات؛ خصائص البيانات؛ التوازن؛ الإجبار؛ عدد النقاط؛ أخطاء المقيمين."},{"num":37,"kind":"short","question":"فرّق بين Rating وRanking وCategorization بمثال لكل نوع.","options":[],"answer":"الإجابة:  التقييم درجة للشيء؛ الترتيب أفضلية بين أشياء؛ التصنيف تحديد الفئة."},{"num":38,"kind":"short","question":"بيّن الفروق بين الاسمي والرتبي والفتري والنسبي.","options":[],"answer":"الإجابة:  الاسمي تصنيف؛ الرتبي يضيف ترتيبًا؛ الفتري يضيف فروقًا متساوية؛ النسبي يضيف صفرًا حقيقيًا."},{"num":39,"kind":"short","question":"ما الفرق بين المقياس المتوازن وغير المتوازن؟","options":[],"answer":"الإجابة:  المتوازن فيه عدد متساوٍ من الخيارات الإيجابية والسلبية؛ غير المتوازن لا يتساوى فيه العدد."},{"num":40,"kind":"short","question":"اشرح خطأ النزعة المركزية وخطأ التساهل.","options":[],"answer":"الإجابة:  الأول اختيار الوسط مرارًا؛ الثاني الإفراط في منح تقييمات مرتفعة."},{"num":41,"kind":"short","question":"اذكر عشرة مقاييس للتقييم وردت في المحاضرة.","options":[],"answer":"الإجابة:  الثنائي، المتعدد الواحد، المتعدد المتعدد، ليكرت، الدلالات، الرقمي، المفصل، المجموع الثابت، ستابل، البياني."},{"num":42,"kind":"short","question":"قارن بين مقياس ليكرت ومقياس دلالات الألفاظ.","options":[],"answer":"الإجابة:  ليكرت يقيس الاتفاق مع عبارة؛ والدلالات اللفظية تقيس الموضع بين صفتين متضادتين."},{"num":43,"kind":"short","question":"اذكر أنواع الصدق الرئيسية الثلاثة وما يميز كلًا منها.","options":[],"answer":"الإجابة:  المحتوى: شمول المجال؛ المحك: معيار خارجي؛ البناء: المفهوم النظري."},{"num":44,"kind":"short","question":"اذكر الطرق الرئيسية الثلاث لتقدير الثبات.","options":[],"answer":"الإجابة:  إعادة الاختبار، النماذج المتكافئة، الاتساق الداخلي."},{"num":45,"kind":"short","question":"فسر عبارة «الثبات شرط ضروري للصدق ولكنه غير كافٍ».","options":[],"answer":"الإجابة:  النتائج غير المستقرة تضعف القياس، لكن الثبات وحده لا يثبت أننا نقيس الصفة الصحيحة."},{"num":46,"kind":"case","question":"كم مقارنة ثنائية نحتاج عند تقييم ستة منتجات دون تكرار كل زوج؟","options":[],"answer":"الحل:  عدد المقارنات = 6×5÷2 = 15."},{"num":47,"kind":"case","question":"في التجزئة النصفية إذا كان الارتباط بين النصفين 0.60، احسب معامل سبيرمان–براون.","options":[],"answer":"الحل:  R = (2×0.60)/(1+0.60) = 1.2/1.6 = 0.75."},{"num":48,"kind":"case","question":"مقياس به 5 فقرات؛ مجموع تباينات الفقرات 8 وتباين الدرجة الكلية 20. احسب ألفا.","options":[],"answer":"الحل:  α = (5/4)×(1−8/20) = 1.25×0.60 = 0.75."},{"num":49,"kind":"case","question":"إذا كان عدد الفقرات 6 ومتوسط الارتباط بينها 0.40، احسب ألفا المعياري.","options":[],"answer":"الحل:  α = (6×0.4)/(1+(6−1)×0.4) = 2.4/3 ≈ 0.80."},{"num":50,"kind":"case","question":"وزّع 100 نقطة على السعر والجودة والتصميم وخدمة ما بعد البيع، بحيث تكون الجودة الأهم والتصميم الأقل؛ ثم فسّر التوزيع.","options":[],"answer":"الحل:  مثال صحيح: الجودة 40، السعر 30، خدمة ما بعد البيع 20، التصميم 10. المجموع 100 والجودة الأهم."}]},{"id":7,"title":"طرق جمع البيانات وتصميم الاستبيان","source":"العرض 07.ppt — المحاضرة السابعة","units":[{"title":"مصادر البيانات والمجموعات","steps":[{"title":"مصادر البيانات Sources of Data","body":["يوجد نوعين من مصادر البيانات وهما:","أولاً: البيانات الأولية:","هي تلك البيانات التي يجمعها الباحث لأول مرة عن المتغيرات التي يهتم بها لأغراض محددة ذات أهمية للدراسة التي يقوم بها.","مصادرها:","الأفراد من خلال: (من خلال توزيع الاستبيانات أو المقابلات)","تتبع أو ملاحظة آثار الأشياء (أسلوب الملاحظة).","مجموعات التركيز Focus Groups."],"example":["البيانات الأولية تُجمع خصيصًا للدراسة الحالية، بينما الثانوية جُمعت لأغراض سابقة؛ ابدأ بتحديد سبب جمع البيانات."],"source":"الشريحة 2","table":[]},{"title":"ثانياً: البيانات الثانوية","body":["هي تلك البيانات والمعلومات الموجودة حالياً في مصادر أخرى أي أنها جمعت لأهداف أخرى غير البحث الحالي.","مصادرها:","سجلات الشركات.","الأرشيفات والمطبوعات الحكومية.","التحاليل التي تنشرها وسائل الاتصال المختلفة.","مواقع الإنترنت وغيرها من المصادر."],"example":[],"source":"الشريحة 3","table":[]},{"title":"مصادر البيانات الأولية Primary Sources Of Data","body":["1- مجموعات التركيز:","تتكون هذه الجماعات من عدد يتراوح 8-10 خبراء مع موجه (Moderator) يقود المناقشات التي قد تستمر لما يقرب من الساعتين. ويتم اختيار الأعضاء بناء على خبرتهم في الموضوع الذي يتم تجميع البيانات عنه.","مثال: الموظفات اللاتي يعلن أطفالاً يمكن أن يشكلن مجموعة تركيز لمناقشة أفضل الأساليب التي يمكن أن تتبعها شركات الأعمال من اجل مساعدة هؤلاء الموظفات."],"example":["مثال: يمكن دعوة مجموعة موظفين لمناقشة سبب ضعف استخدام نظام جديد قبل تصميم الاستبانة."],"source":"الشريحة 4","table":[]},{"title":"مزايا وفوائد مجموعات التركيز:","body":["تساعد في التعرف على انطباع أعضاء المجموعة أو أفكارهم أو تفسيرهم لبعض الأحداث، وذلك من خلال حديث الأعضاء عن الوقائع والمفاهيم والمنتجات أو الخدمات.","تقدم مناقشات مجموعات التركيز فرصة ممتازة لانسياب المعلومات بمرونة وحرية بين الأعضاء. كما تعكس الاستجابة السريعة لآراء ومشاعر الأعضاء الحقيقية نحو القضية التي تتم مناقشتها.","يعتبر أسلوب جماعات التركيز أسرع طرق جمع البيانات وأقلها تكلفة، حيث يمكن الحصول منها على معلومات يمكن الاعتماد عليها خلال وقت قصير، والاستناد عليها في إعطاء تعميمات أولية.","توضح أسباب الأداء السيئ لبعض المنتجات، وأسباب نجاح بعض سياسات الإعلان، ولماذا تنجح بعض الأساليب الإدارية ويفشل البعض الآخر ...الخ","تقدم دوراً مهماً في البحوث الاستكشافية كخطوة أولى لإجراء مزيد من البحوث العلمية.","مثال: دور جماعات التركيز مثلا في اكتشاف معنى (الملكية الفكرية)، حيث أن اندماج أفراد المجموعة في المناقشة سيعطي فرصة جيدة لتوارد أفكار جديدة على أذهانهم، وهذا يساعد الباحث نتيجة لكثرة مثل هذه الأفكار الجديدة."],"example":[],"source":"الشريحة 5","table":[]},{"title":"عيوب مجموعات التركيز:","body":["البيانات التي نحصل عليها عبارة عن معلومات وصفية فقط وليست معلومات كمية.","اختيار أعضاء المجموعة لا يتم بطريقة علمية بحيث يمثلون مجتمع البحث، ولذلك فإن آراءهم لا تمثل مجتمع البحث تمثيلا حقيقيا."],"example":[],"source":"الشريحة 6","table":[]},{"title":"دور الموجه في المناقشة Role Of The Moderator:","body":["تقديم الموضوع أو القضية موضوع المناقشة.","ملاحظة الأعضاء وتسجيل الملاحظات والمناقشات.","لا ينبغي أن يكون جزء من المناقشات بل عليه أن يوجه المناقشة عن طريق الإقناع لتقديم المعلومات المطلوبة.","معاونة أعضاء الجماعة لحل المشاكل التي قد تواجهها.","التأكد من مشاركة جميع الأعضاء في المناقشة، وعدم سيطرة أي عضو عليها.","يجب أن يقوم أحد أعضاء قسم البحوث بمراقبة أقوال وأفعال وحركات أعضاء فريق المناقشة وذلك بالجلوس في مكان بحيث يراهم ولا يرونه (One – Way Mirror)"],"example":[],"source":"الشريحة 7","table":[]},{"title":"دور مؤتمرات الفيديو في مجموعات التركيز Video Conference","body":["تستخدم في حالة تعدد الأماكن الجغرافية للأفراد المشاركين.","يتم تشكيل مجموعة تركيز في كل إقليم بقيادة موجه مدرب لتعمل على نفس المشكلة.","تسهل مؤتمرات الفيديو تحقيق الاستفادة الكاملة من تلك الجماعات. ومن الممكن بالتركيز على عضو معين أن يلاحظ الآخرون على الجانب أو الجوانب الأخرى ما يرتسم على وجه كل عضو، وفهم إيماءاته وحركاته وكل ما يصدر عنه، كما أن هذه المؤتمرات تقلل حاجتنا إلى مراقب من جانب واحد.","وسائل أخرى:","يمكن عقد لقاءات مجموعات التركيز عن طريق:","التلفونات.","البريد الالكتروني ومواقع الانترنت والمحادثات التي تتم عن طريق الانترنت."],"example":[],"source":"الشريحة 8","table":[]},{"title":"2. العينات الدائمة","body":["أعضاء العينات الدائمة يجتمعون أكثر من مرة بخلاف مجموعات التركيز.","يتم اختيار أعضاء العينات الدائمة بطريقة عشوائية، وتكون العينات الدائمة مفيدة عندما تستمر دراسة التغيير لفترة طويلة.","وجود هذه العينات يخدم في تقييم التغييرات التي تدخلها الإدارة على سياساتها المختلفة . ويطلق على البحوث التي تتم باستخدامها \" بحوث العينات الدائمة ”.","مثال: إذا كان هدف البحث هو تقييم آثار الإعلان عن نوع معين من القهوة، فإنه يتم تعريض أفراد العينة الدائمة للإعلان عدة مرات، ثم يتم قياس اتجاهاتهم لشراء القهوة. وبعد عدة أشهر فقد يرغب مدير الإنتاج في إضافة طعم جديد للمنتجات التي تحمل هذه العلامة، وبالتالي فإنه يرغب في التعرف على مدى إقبال العملاء عليه فيلجأ إلى سؤال أفراد العينة بعد توزيع عينات من المنتج عليهم. لذا فوجود هذه العينات الدائمة يخدم في تقييم التغييرات التي تدخلها الإدارة على سياساتها المختلفة ."],"example":[],"source":"الشريحة 9","table":[]},{"title":"العينات الدائمة والمتغيرة :","body":["العينات الثابتة بمعنى أن نفس الأعضاء يستمرون لفترة طويلة.","العينات المتغيرة بمعنى أنه يتم تغيير مفردات العينة من فترة لأخرى خلال إجراء البحث.","مزايا العينات الدائمة","تقدم لنا مقياسا حساسا للتغيير الذي يحدث خلال إجراء البحث. وهي أفضل من استخدام مجموعة جديدة في كل مرحلة من مراحل البحث.","تستخدم عندما تريد الشركة دراسة عدد من خصائص المنتج من وقت لآخر.","مساوئ العينات الدائمة:","الأعضاء قد يصبحوا حساسين جدا للتغيير من كثرة عدد المقابلات التي تتم معهم، وبذلك تصبح العينة غير ممثلة للمجتمع."],"example":[],"source":"الشريحة 10","table":[]}]},{"title":"المقابلات والتحيز والآداب","steps":[{"title":"طرق تجميع البيانات Data Collection Methods","body":["هناك عدة طرق لتجميع البيانات لكل منها مزاياها وعيوبها وأهم طرق جمع البيانات في الدراسات التي فيها توجيه أسئلة لمفردات العينة:","المقابلات الشخصية Interview","الاستقصاءات Questionnaire","ملاحظة الأفراد أو الأشياء Observation"],"example":[],"source":"الشريحة 11","table":[]},{"title":"أولا: المقابلات Interviewing","body":["هي إحدى طرق جمع البيانات الأولية عن القضايا التي تهم الباحث. ومن الممكن أن تكون المقابلة مهيكلة أو غير مهيكلة. كما يمكن أن تتم وجها لوجه أو باستخدام الهاتف أو الكومبيوتر.","أنواع المقابلات:","1- المقابلات غير المهيكلة Unstructured Interviews","هي المقابلات التي يقوم بها الشخص دون الاعتماد على أسئلة محددة ومرتبة مسبقاً.","2- المقابلات المهيكلة Structured Interviews :","هي تلك المقابلات التي يتم إجراؤها بواسطة شخص يعلم بدقة ما المعلومات المطلوبة، ولديه قائمة محددة مسبقا بالأسئلة التي سوف يوجهها للمستجيب شخصيا أو عن طريق التليفون أو عن طريق الحاسب الآلي."],"example":["استخدم المقابلة غير المهيكلة للاستكشاف، ثم المهيكلة لجمع إجابات قابلة للمقارنة."],"source":"الشريحة 12","table":[]},{"title":"1- المقابلات غير المهيكلة Unstructured Interviews","body":["يهدف هذا النوع من المقابلات إلى استيضاح بعض القضايا التمهيدية حتى يتمكن الباحث من تنمية وصياغة وتحديد المتغيرات التي تحتاج إلى بحث متعمق في مرحلة تالية من مراحل البحث.","وفي المرحلة الأولى يقوم الباحث بتوجيه أسئلة مفتوحة وعامة فقط. ومن إجابات هذه الأسئلة يستنتج الباحث وجهة نظر وفهم العاملين للمشاكل التي يقوم ببحثها.","تختلف طبيعة الأسئلة الموجهة للأشخاص حسب مستوى الوظيفة ونوع العمل.","بعد إجراء عدد كاف من المقابلات غير المهيكلة مع عدد من الموظفين في مختلف المستويات، فسيكون بإمكان الباحث الحصول على فكرة جيدة عن المتغيرات التي تحتاج إلى تركيز أكثر، وعن مكان الحصول على المعلومات الدقيقة والمعمقة ويصبح الباحث بالتالي جاهزا للانتقال إلى مرحلة المقابلات المهيكلة.","نتائجها تستخدم كفروض للاختبار وليست كنتائج نهائية."],"example":[],"source":"الشريحة 13","table":[]},{"title":"2- المقابلات المهيكلة Structured Interviews :","body":["في هذه المقابلات تركز الأسئلة غالبا على المتغيرات والعوامل التي ظهرت أثناء المقابلات غير المهيكلة وتبين أن لها علاقة بمشكلة البحث.","يسجل الباحث إجابات المبحوثين في الجداول المعدة لذلك.","توجه نفس الأسئلة وبنفس الطريقة لجميع الأشخاص. وفي بعض الأحيان قد يتتبع الباحث بعض الخيوط التي يذكرها المستجيب، ويوجه له أسئلة غير موجودة في قائمة الأسئلة والحصول بالتالي على فهم أعمق للموضوع.","تستخدم المعاونات البصرية مثل الصور والرسوم الخطية والبطاقات والمواد الأخرى في إجراء المقابلات خاصة في بحوث التسويق من اجل التعرف على ما يحبه وما لا يحبه المستهلك من حيث التغليف والصور الإعلانية ....الخ. وتفيد الأدوات المرئية المساعدة في الظروف التي يصعب فيها التعبير عن بعض المشاعر والأفكار بأسلوب واضح خاصة إذا كانت العينة من الأطفال."],"example":[],"source":"الشريحة 14","table":[]},{"title":"بعض الإرشادات التي يمكن إتباعها خلال المقابلات some tips to follow in interviewing","body":["قد يتطلب البحث أن لا يقوم شخص واحد بإجراء جميع المقابلات لذا يجب أن يكون هناك فريق من المقابلين المدربين.","يجب أن تكون المعلومات التي تم الحصول عليها من المقابلات خالية من التحيز بقدر الإمكان، ويمكن أن يحدث التحيز من جانب المقابل أو المبحوث أو الموقف ذاته كما يلي:","أ- التحيز من جانب المقابل:","قد يتسبب المقابل في التحيز إذا لم يعزز الثقة مع المبحوث.","عندما يسيء تفسير الأجوبة أو يحرفها.","أو عندما يشجع أو يثبط المبحوث بدون قصد لإعطاء إجابة معينة من خلال التلميحات وتعبيرات الوجه."],"example":[],"source":"الشريحة 15","table":[]},{"title":"ب- التحيز من جانب المبحوث:","body":["يتسبب المبحوث في تحيز البيانات عندما لا يعطي رأيه الصريح بل يعطي معلومات يعتقد أن الباحث المقابل يرغب في سماعها أو يتوقعها","التحيز قد يحدث نتيجة لعدم فهم المبحوث للأسئلة وشعوره بحرج يمنعه من استيضاح معنى الأسئلة، لذا فإنه يجيب عن الأسئلة دون معرفة ما يعنيه السؤال بدقة.","ج- التحيز من جانب الموقف نفسه كما يلي:","الأشخاص غير المشاركين.","يتسبب عدم مشاركة بعض الأشخاص في المقابلات بسبب عدم القدرة أو الرغبة في تحيز البيانات، فمن الممكن أن تكون الإجابات التي تم الحصول عليها متحيزة ولا تمثل المجتمع الذي أخذت منه العينة."],"example":[],"source":"الشريحة 16","table":[]},{"title":"مستويات الثقة والصلة القائمة","body":["يمكن أن يحدث التحيز عندما يقوم عدد من المقابلين بتكوين مستويات مختلفة من الثقة والصلة مع من تتم مقابلتهم بحيث يتم الحصول على إجابات متباينة في صدقها وصراحتها.","البيئة المكانية لإجراء المقابلة:","قد تتسبب البيئة المكانية التي يتم إجراء المقابلة فيها في تحيز البيانات. فقد يشعر بعض الأشخاص بعدم الارتياح عندما يتم إجراء المقابلة في موقع العمل ولذا لا يقدمون إجابات صريحة وصادقة .","بإمكان المقابل أن يقلل التحيز الذي قد يحدث عن طريق:","إتباع نمط موحد في إلقاء الأسئلة.","عدم التدخل في المعلومات التي حصل عليها.","عدم التأثير على المبحوث."],"example":[],"source":"الشريحة 17","table":[]},{"title":"تنمية قدر من المصداقية والثقة وتحفيز الأفراد للإجابة.","body":["التدرج في الأسئلة","إلقاء الأسئلة غير المتحيزة","استيضاح بعض القضايا","مساعدة المبحوث على فهم الأسئلة","تدوين الملاحظات","استراتيجيات تساعد على تقليل مستوى التحيز:"],"example":[],"source":"الشريحة 18","table":[]},{"title":"يجب أن يوضح الباحث للمشاركين أنه ليس في جانب معين وأن وجوده ليس من أجل إيذاء الموظفين.","body":["يستطيع الباحث تكوين علاقات إذا كان لطيفا وصادقا وحساسا، ولا يطلق العنان لنفسه لإصدار الأحكام على الآخرين.","إبداء اهتماما حقيقيا بإجابات المستجيب ومحاولة تهدئة أي قلق أو خوف أو توتر يحدث خلال المقابلة يساعد المستجيب على الشعور بالارتياح .","إخبار المستجيب بهدف الدراسة يحسن الاتصال بين الطرفين.","1- تنمية قدر من المصداقية والثقة وتحفيز الأفراد للإجابة Establishing Credibility And Rapport, And Motivating Individuals To Respond"],"example":[],"source":"الشريحة 19","table":[]},{"title":"2- التدرج في الأسئلة Funneling","body":["التدرج من الأسئلة العامة إلى الأسئلة المحددة","في بداية المقابلة غير المهيكلة فإنه من المستحسن طرح أسئلة مفتوحة للحصول على انطباعات عامة.","من الردود يمكن للباحث طرح أسئلة إضافية مركزة يستنتجها من خلال إجابات المستجيبين ويحدد من خلالها بعض القضايا المهمة المرتبطة بالموقف ."],"example":["ابدأ بسؤال عام عن تجربة الموظف، ثم انتقل إلى أسئلة أكثر تحديدًا عن الصعوبات."],"source":"الشريحة 20","table":[]},{"title":"3- الأسئلة غير المتحيزة Unbiased Questions","body":["طرح أسئلة لا تتضمن وجود تحيز.","”اذكر لي كيف تمارس عملك“.","يعتبر سؤالاً أفضل من قولك :","”أعتقد أن العمل الذي تقوم ... دعني أسمع شعورك عنه؟“","فالسؤال الأخير مشحون بالانطباعات الشخصية للمقابل عن العمل ويؤثر على الإجابات التي يقدمها المستجيب.","ويمكن أن يحدث التحيز من خلال التأكيد على بعض الكلمات أو تغيير نبرة الصوت أو بعض الاقتراحات غير الملائمة."],"example":[],"source":"الشريحة 21","table":[]},{"title":"4- استيضاح بعض القضايا Clarifying Issues:","body":["لكي يتأكد الباحث أنه يفهم القضايا كما يعنيها المستجيب، فمن المستحسن أن يقوم بإعادة صياغة المعلومات المهمة التي يدلي بها المستجيب. وإذا لم تكن بعض النقاط التي ذكرت واضحة فعلى الباحث السعي لاستيضاحها.","مثال: إذا زعم المستجيب أن:","سياسة الترقية في المنظمة غير عادلة، حيث لا تؤخذ الأقدمية في الحسبان إطلاقاً،","فإن الباحث يستطيع أن يتدخل بالقول :","هل تعني بذلك أن الموظفين الجدد يحصلون دائماً على الترقية قبل الموظفين القدامى الأكفاء؟","وتساعد إعادة صياغة السؤال على استيضاح ما إذا كان المبحوث قد أعطى قضية الكفاءة ما تستحقه من اهتمام أم لا."],"example":[],"source":"الشريحة 22","table":[]},{"title":"5- مساعدة المستجيب على فهم السؤال: Helping The Respondent To Think Through Issues","body":["إذا لم يستطع المستجيب التعبير عن انطباعاته، أو أجاب بلا أعرف فعلى الباحث أن يطرح السؤال بطريقة أبسط أو يعيد السؤال.","مثال: إذا سأل الباحث السؤال التالي:","”ما هي الجوانب التي تكرهها في عملك؟“","وعجز المبحوث عن تحديد الجوانب التي يكرهها في عمله فان الباحث يستطيع أن يطرح السؤال بصيغة مبسطة مثلا:","”ما الأعمال التي تفضل أن تؤديها، خدمة العملاء أو بعض أعمال تنظيم الملفات؟“","يستطيع الباحث بعد ذلك استخدام جانب آخر من عمل المبحوث ويكرر الأسلوب السابق في وضع الخيارات."],"example":[],"source":"الشريحة 23","table":[]},{"title":"6- تدوين الملاحظات Taking Notes","body":["من المهم أن يقوم الباحث بتدوين الملاحظات وهو يجري المقابلة أو بعد نهايتها مباشرة.","ينبغي على المقابل ألا يعتمد على الذاكرة لأن المعلومات المسترجعة من الذاكرة لا تكون دقيقة وكثيراً لا تكون صحيحة.","إذا تم إجراء أكثر من مقابلة في اليوم فإن حجم المعلومات يزداد ومصادر الخطأ تتنوع عند استرجاع المعلومات من الذاكرة وتزيد التحيز.","يمكن تسجيل المقابلة على شرائط صوتية إذا لم يعترض المستجيب. وينبغي قبل الشروع في تسجيل المقابلة بالصوت أو بالصورة التأكد من أن هذه الطريقة لن تتسبب في تحيز المعلومات التي يتم الحصول عليها."],"example":[],"source":"الشريحة 24","table":[]},{"title":"المقابلات الشخصية والهاتفية Face-to-face and Telephone Interviews","body":["يمكن إجراء المقابلات إما وجها لوجه أو باستخدام الهاتف.","معظم المقابلات غير المهيكلة الخاصة بالبحوث التنظيمية تتم وجهاً لوجه إلا أن المقابلات المهيكلة يمكن أن تتم عن طريق الهاتف. ويعتمد ذلك على:","مستوى تعقد القضايا المطروحة","الزمن الذي تستغرقه المقابلة","ومدى ملاءمتها لأطراف المقابلة","المساحة الجغرافية التي تغطيها الدراسة."],"example":[],"source":"الشريحة 25","table":[]},{"title":"1- المقابلات الشخصية Face -to - face Interviews","body":["المزايا:","قدرة الباحث على تعديل الأسئلة عند الضرورة وتوضيح العناصر المشكوك فيها.","ضمان أن الباحث قد فهم إجابات المبحوثين من خلال تكرار أو إعادة صياغة الأسئلة.","يستطيع الباحث أن يلتقط بعض التلميحات والإرشادات غير اللفظية ويستشعر المشاكل أو الجهد الذي يعاني منه المستجيب من خلال تجهمه وقلقه والتعبيرات اللفظية التي تظهر دون قصد.","المساوئ:","تعتبر القيود الجغرافية من أهم مساوئ المقابلات الشخصية لأنها تقيد حجم الاستقصاءات، وتتطلب نفقات كبيرة إذا كانت هناك حاجة لإجراء المقابلات على المستوى الوطني أو العالمي.","تكاليف تدريب المقابلين لكي يقللوا من حجم تحيزهم تعتبر باهظة."],"example":[],"source":"الشريحة 26","table":[]},{"title":"المقابلات الهاتفية Telephone Interviews","body":["المزايا:","يمكن الوصول إلى عدد كبير من الناس المنتشرين في أنحاء الدولة أو العالم في وقت قصير نسبياً.","تجعل المبحوث أكثر ارتياحاً مما لو كان يقابل وجهاً لوجه","عدم شعور المبحوثين بالحرج عند كشف الكثير من المعلومات الشخصية على الهاتف مقارنة بالمقابلة الشخصية.","المساوئ:","قدرة المبحوث على إنهاء المقابلة من جانبه بإغلاق الهاتف دون تحذير أو تفسير.","عدم قدرة الباحث على رؤية المستجيب وملاحظة التغيرات غير اللفظية التي يمكن أن توضح كثيراً من المعلومات."],"example":[],"source":"الشريحة 27","table":[]}]},{"title":"الاستبيانات وصياغة الأسئلة","steps":[{"title":"ثانيا: الاستبيانات Questionnaires","body":["الاستبيان عبارة عن صياغة لمجموعة أسئلة معدة سلفا يقوم المستجيب بتسجيل إجاباته عليها عادة باختيار أحد البدائل المحددة.","يعتبر الاستبيان وسيلة فعالة لجمع البيانات عندما يكون الباحث على معرفة دقيقة بالمطلوب، وبكيفية قياس المتغيرات المطلوب دراستها.","يمكن توزيع الاستبيانات شخصيا أو بالبريد الإلكتروني."],"example":[],"source":"الشريحة 28","table":[]},{"title":"طرق توزيع الاستبيانات","body":["1- التوزيع الشخصي من الباحث نفسه أو بالاستعانة بفريق ميداني لتوزيع الاستبيانات وله عدة مزايا:","يعتبر أفضل وسيلة لجمع البيانات عندما يكون المسح مقصورا على منطقة معينة.","يمكن الباحث من جمع الإجابات في فترة قصيرة.","من الممكن توضيح أي استفسار أو إزالة أي شك يتعلق بالأسئلة للمستقصى فورا.","يتوفر لدى الباحث فرصة تقديم موضوع البحث إلى المستجيبين، وفرصة تحفيزهم للإدلاء بالإجابات الصادقة.","2- التوزيع بالبريد: الميزة الأساسية للاستبيانات البريدية هي إمكانية تغطية مساحة جغرافية واسعة، ويعاب عليه انخفاض نسبة الردود، وعدم القدرة على توضيح أي غموض أو شك يعتري المجيب على الاستقصاء.","3- التوزيع الكترونيا من خلال الكمبيوتر"],"example":[],"source":"الشريحة 29","table":[]},{"title":"تصميم الاستبيانات","body":["تركز مبادئ تصميم الاستبيانات الجيدة على ثلاثة مجالات هي:","صياغة ألفاظ الأسئلة .","تصنيف المتغيرات وقياسها وترميزها بعد الحصول على إجابات من تم استقصاؤهم .","الشكل العام للاستبيان .","والمجالات الثلاثة مهمة بالنسبة للاستبيانات لأنها تؤدي إلى تخفيض التحيز في البحوث ."],"example":[],"source":"الشريحة 30","table":[]},{"title":"شكل عام يوضح مبادئ تصميم الاستبيانات","body":["1- مبادئ الصياغة","نوع وشكل السؤال","اختيار اللغة والكلمات المناسبة","هدف السؤال ومحتوياته","تصنيف البيانات أو المعلومات الشخصية","تتابع الأسئلة","اختبار جودة البيانات"],"example":[],"source":"الشريحة 31","table":[]},{"title":"أولاً: مبادئ صياغة الألفاظ Principle Of Wording","body":["تشير مبادئ الصياغة إلى العوامل التالية:","ملائمة محتويات الأسئلة .","كيفية صياغة الأسئلة ومستوى التعقيد في اللغة المستخدمة.","نوع الأسئلة – مفتوحة أم مغلقة – وشكل الأسئلة المطروحة.","تتابع الأسئلة في الاستبيان.","البيانات الشخصية المطلوب الحصول عليها من المستجيب."],"example":[],"source":"الشريحة 32","table":[]},{"title":"محتويات وأهداف الأسئلة content and purpose of the questions","body":["تحدد طبيعة المتغير المراد قياسه نوع الأسئلة التي سيتم توجيهها، فإذا كانت المتغيرات ذات طبيعة شخصية، ( الرضا والمشاركة الوجدانية مثلا) حيث يتم قياس اعتقاد المجيبين واتجاهاتهم، فإن الأسئلة المطروحة يجب أن تركز على أبعاد وعناصر هذه المتغيرات.","وعند قياس متغيرات موضوعية مثل العمر، ومستوى التعليم، فقد يكون من المناسب توجيه سؤال مباشر واحد. وأن يحتوي السؤال على مقياس ترتيبي لفئات المتغير الذي يتم قياسه .","لذلك يجب أن يؤخذ هدف كل سؤال في الاعتبار بحيث يمكن قياس المتغيرات بطريقة ملائمة بحيث لا تطرح الأسئلة غير الضرورية ."],"example":[],"source":"الشريحة 33","table":[]},{"title":"لغة وألفاظ الاستبيان Language And Wording Of The Questionnaire","body":["يجب أن تراعي لغة الاستقصاء مستوى فهم المبحوثين.","أن يعتمد اختيار الألفاظ على مستوى تعليم أفراد العينة، وعلى الجمل والعبارات الاصطلاحية في ثقافتهم، وعلى قيمهم ومعتقداتهم. ومناسبة لقياس اتجاهاتهم وسلوكهم وانطباعاتهم.","صياغة الأسئلة باللغة التي يفهمها المبحوثين."],"example":[],"source":"الشريحة 34","table":[]},{"title":"أنواع وصيغ الأسئلة Type And Form Of Questions","body":["يشير نوع السؤال إلى كونه مفتوحا أو مغلقا، كما ترتبط صيغة السؤال بكون الأسئلة ذات ألفاظ إيجابية أو سلبية.","الأسئلة المفتوحة مقابل الأسئلة المغلقة :","1- الأسئلة المفتوحة Open – Ended Questions:","تسمح الأسئلة المفتوحة للمستجيب أن يجيب عن الأسئلة بأي طريقة شاء. ومن أمثلة ذلك سؤال المستجيب عن الأشياء التي يحبها في رئيسه أو في بيئة عمله.","2- الأسئلة المغلقة Closed Questions","تساعد الأسئلة المغلقة المستجيب على اتخاذ قرار سريع من خلال الاختيار بين عدة بدائل مطروحة ويجب التأكد من أن الخيارات جامعة مانعة.","يساعد هذا النوع من الأسئلة الباحث في ترميز المعلومات لعمل التحليلات اللاحقة ."],"example":[],"source":"الشريحة 35","table":[]},{"title":"الأسئلة الإيجابية والسلبية : Positively And Negatively Worded Questions","body":["من المستحسن إضافة بعض الأسئلة ذات الألفاظ السلبية لتقليل ميل المستقصي إلى الإجابة على الأسئلة دون تفكير، أو الاختيار الدائم لإجابة واحدة على المقياس دون تمعن في محتوى السؤال.","مثال: إذا قام المستجيب باختيار الرقم (5) مرة أخرى كإجابة عن سؤال مصاغ بلفظ إيجابي مثل:","\" أشعر بأنني استطعت إنجاز عدد من المهام المختلفة في عملي \"","فإنه لن يستطيع اختيار الرقم (5) مرة أخرى على سؤال مصاغ بلفظ سلبي مثل:","\" لا أشعر بأني فعال في عملي \".","وسيدفع هذا الأسلوب المستجيب إلى التمعن في الأسئلة ويبعده عن الإجابة بطريقة آلية. وفي حالة ما إذا حدث هذا فإن الباحث سيكون لديه فرصة اكتشاف مثل هذا التحيز. لذا فالاستبيان الجيد يجب أن يحتوي على الأسئلة المصاغة بألفاظ إيجابية وسلبية."],"example":[],"source":"الشريحة 36","table":[]},{"title":"يجب تفادي استخدام العبارات السلبية المضاعفة – نفي النفي – والاستخدام الكثير لكلمات مثل \" ليس \" و \" فقط \" في الأسئلة المصاغة بألفاظ","body":["مثال1: من الأفضل قول:","\"المجيء إلى العمل ليس ممتعا \"","بدلا من قول:","\"عدم المجيء إلى العمل أمتع من المجيء إليه \" .","مثال2: من الأفضل قول:","(الأصحاء من الناس لا يحتاجون إلى فيتامينات)","بدلا من القول:"],"example":[],"source":"الشريحة 37","table":[]},{"title":"الأسئلة المركبة : Double – Barreled Questions","body":["وهي الأسئلة التي يمكن أن يكون لها عدة إجابات صحيحة وينبغي تفادي مثل هذه الأسئلة بإعادة صياغتها في سؤالين منفصلين أو أكثر.","\" هل تعتقد أن هناك سوقا جيدة للمنتج وأنه سوف يباع بصورة جيدة \"","وفي هذه الحالة فمن المستحسن سؤالين :","هل تعتقد أن هناك سوقا جيدة للمنتج ؟","هل تعتقد أن المنتج سوف يباع بصورة جيدة ؟","فإذا جمعنا السؤالين معا في سؤال واحد مركب فإننا سنربك المستجيب وسنحصل على إجابات غامضة ."],"example":["السؤال «هل جودة التدريب والمكافآت ممتازة؟» يجمع محورين مختلفين، فافصله إلى سؤالين."],"source":"الشريحة 38","table":[]},{"title":"الأسئلة الغامضة : Ambiguous Questions","body":["قد لا تكون الأسئلة مركبة ولكنها مصاغة بأسلوب غامض. ويعني ذلك أن المبحوث غير متأكد مما تعنيه تلك الأسئلة.","\" إلى أي مدى يمكن أن تقول أنك سعيد \"","فربما لا يعرف المستجيب بالتحديد هل يقصد السائل سعادتهم في العمل أو في المنزل أو بصورة عامة .","لذلك فإن الإجابات عن الأسئلة الغامضة تحمل في طياتها تحيزا بقدر الاختلاف الموجود بين المبحوثين في تفسير مثل تلك الأسئلة. وتكون النتيجة خليطا من الإجابات الغامضة التي لا تعكس بدقة الإجابة الصحيحة للسؤال ."],"example":[],"source":"الشريحة 39","table":[]},{"title":"الأسئلة التي تعتمد على القدرة على التذكر : Recall – Dependent Questions","body":["ربما تتطلب بعض الأسئلة من المستجيبين تذكر تجارب ماضية قد لا تكون دقيقة في ذاكرتهم. ولذلك فإن الإجابات عن مثل تلك الأسئلة قد تكون متحيزة .","مثال: لو أن موظفا عمل بإحدى المنظمات لمدة ثلاثين سنة وطرح عليه سؤال: بشأن بداية العمل في قسم من أقسام المنظمة ومدة عمله فيه.","فإنه قد لا يستطيع أن يعطي إجابة صحيحة لذلك السؤال وربما تكون الإجابة الصحيحة بعيدة كل البعد عن الإجابة التي قدمها.","ولذلك تكون سجلات الموظفين مصدرا أفضل للحصول على تلك المعلومات ."],"example":[],"source":"الشريحة 40","table":[]},{"title":"الأسئلة التي تقود إلى إجابة معينة : Leading Questions","body":["يجب ألا تصاغ الأسئلة بأساليب توجه المستجيب لإعطاء إجابة معينة قد يرغب الباحث في الحصول عليها، أو يفهم منها أنه يرغب الحصول عليها.","\" ألا تعتقد أنه مثل هذه الأيام التي تزداد فيها تكاليف المعيشة زيادة كبيرة، أن الموظف يجب أن يحصل على زيادة جيدة في أجره؟“","مثل هذا السؤال يوجه المستجيب للإجابة ”بنعم“","ولذلك يمكن إعادة صياغة السؤال بشكل أكثر محايدةً كما يلي:","(إلى أي مدى توافق على أن الموظفين يجب أن يعطوا زيادة في الأجر)"],"example":["السؤال المحايد يساعد المستجيب على التعبير دون دفعه إلى إجابة بعينها."],"source":"الشريحة 41","table":[]},{"title":"الأسئلة المشحونة بالعواطف: Loaded Questions","body":["يجب ألا تصاغ الأسئلة بأسلوب مشحون بالعواطف .","\" إلى أي مدى تعتقد أن الإدارة تحاول الانتقام من العاملين إذا قرر اتحاد العمال القيام بإضراب ؟ \"","كلمة (إضراب وتنتقم) عبارة عن ألفاظ مشحونة بالعواطف تستقطب الإدارة واتحاد العمال. لذا فإن طرح سؤال مثل هذا سوف يؤدي إلى إجابة عاطفية متحيزة.","ولذلك ينبغي طرح سؤالين محددين للحصول على الإجابة المطلوبة إذا كان الهدف من السؤال:","معرفة مدى تفضيل الموظفين للإضراب","ومدى خوفهم من رد فعل الإدارة في حالة الإضراب عن العمل.","وربما يظهر جليا أن الموظفين لا يفضلون الإضراب كثيرا. كما أنهم لا يعتقدون أن الإدارة سوف تنتقم منهم في حالة الإضراب."],"example":[],"source":"الشريحة 42","table":[]},{"title":"الأسئلة المتأثرة برغبات مقبولة اجتماعيا Social Desirability","body":["يجب ألا تصاغ الأسئلة بحيث توحي بإجابات مرغوبة اجتماعيا.","\"هل تعتقد أنه يجب تسريح كبار السن ؟ ”","سوف يوحي بالإجابة بالنفي لأن المجتمع سوف يحقد على من يرى أن الكبار يجب أن يسرحوا من عملهم حتى لو كانوا قادرين على أدائه.","إذا كان الهدف من السؤال هو قياس الشعور بأن المنظمات ملتزمة بالإبقاء على الموظفين الذين يتجاوز أعمارهم 65 عاما فإنه يمكن طرح السؤال بصيغة أخرى أخف وطأة وأقل تأثرا بالرغبة الاجتماعية.","مثل: (ما هي محاسن ومساوئ الإبقاء على كبار السن ضمن القوة العاملة ؟ أو إلى أي مدى تعتقد أن على الشركة الاحتفاظ بكبار السن ضمن موظفيها ؟)"],"example":[],"source":"الشريحة 43","table":[]},{"title":"طـول الأسئلة Length Of Questions","body":["من المفضل أن تكون أسئلة الاستقصاء قصيرة وبسيطة. وكقاعدة عامة يجب ألا يتعدى السؤال أو الجملة في الاستبيان عشرين كلمة، أو سطراُ كاملاً."],"example":[],"source":"الشريحة 44","table":[]}]},{"title":"تنظيم الاستبيان وأخلاقيات البحث","steps":[{"title":"تتابع الأسئلة : Sequencing Of Questions","body":["يجب أن يتم ترتيب الأسئلة في الاستبيان بصورة تقود المستجيب من:","الأسئلة العامة إلى الأسئلة ذات الطابع الخاص.","ومن الأسئلة السهلة إلى الأسئلة المتدرجة في الصعوبة.","ويسمى هذا : المنهج البؤري Funnel Approach ويوفر هذا المنهج السهولة والتقدم السلس للمبحوث.","من المستحسن عدم تتابع الأسئلة المصاغة بألفاظ إيجابية تناقش مفهوما معينا بأسئلة سلبية تناقش نفس المفهوم.","مثال: وضع جملتين متتابعتين كما يلي يعتبر خطأ:","عندي فرصة جيدة للتفاعل مع زملائي خلال ساعات العمل."],"example":[],"source":"الشريحة 45","table":[]},{"title":"بيانات التصنيف أو البيانات الشخصية : Classification Data Or Personal Information","body":["تحتوي البيانات الشخصية أو البيانات الديموغرافية على بيانات عن العمر ومستوى التعليم والوضع الاجتماعي والدخل .... الخ وإذا كانت هناك ضرورة إلى التعرف على بيانات المستجيب، فمن الممكن إعطاء الاستبيانات أرقاما سرية مع الاحتفاظ بأسماء من تم استقصاؤهم في وثيقة سرية منفصلة يحتفظ بها الباحث ولا يطلع عليها أحد. ويجب أن توضح تلك الإجراءات لمن تم استقصاؤهم. ويوضح لهم كذلك أن سبب الترقيم هو التأكد من إخفاء اسم المستجيب إذا وقع الاستبيان في يد أي شخص آخر."],"example":[],"source":"الشريحة 46","table":[]},{"title":"ثانياً: بيانات التصنيف أو البيانات الشخصية Classification Data Or Personal Information","body":["موقع البيانات الشخصية في الاستقصاء مسألة اختيارية متروكة لقرار الباحث.","يفضل وضع الأسئلة التي تتطلب معلومات مفصلة عن الدخل أو أي معلومات حساسة أخرى ضرورية للبحث على شكل فئات.","مثال: مستوى دخلك هو:","اقل من: 1500 رــــــال 1600-3000 3100-4500 اكبر من 4500","وينصح في البحوث التنظيمية أن يجمع الباحث بيانات عن المتغيرات الديموغرافية، لأهميتها في وصف خصائص العينة."],"example":[],"source":"الشريحة 47","table":[]},{"title":"المظهر العام أو شكل الاستبيان General Appearance Or (Getup) Of The Questionnaire","body":["يجب الانتباه إلى مظهر الاستبيان من حيت العناصر التالية:","مقدمة الاستبيان.","تنظيم الأسئلة وإعطاء الإرشادات والتوجيهات والتنسيق الجيد","البيانات الشخصية.","المعلومات الخاصة بالدخل والبيانات الشخصية الأخرى.","الأسئلة المفتوحة في نهاية الاستبيان"],"example":[],"source":"الشريحة 48","table":[]},{"title":"المقدمة الجيدة A Good Introduction","body":["عزيزي المشارك: التاريخ: //","صمم هذا الاستقصاء لدراسة مظاهر الحياة في مكان العمل. وسوف تساعدنا على تحسين فهمنا لمستوى الجودة في مكان العمل. ونظراً لأنك أنت الذي تستطيع إعطاءنا صورة صحيحة عن تجربتك في مكان عملك فإنني أرجو أن تجيب عن أسئلة الاستقصاء بأمانة وصراحة.","سنحافظ على السرية التامة لإجاباتك ولن يتاح لأحد من غبر أعضاء الفريق الوصول إلى المعلومات التي تقدمها. ولكي نؤكد لك الخصوصية التامة فقد قمنا بتخصيص رقم لكل مشترك وسوف نستخدم هذا الرقم فقط في إجراءات المتابعة وسوف نرسل لك بالبريد ملخصاً للنتائج بعد تحليل البيانات.","أشكرك كثيراً على وقتك وتعاونك، وأقدر بعمق المساعدة التي قدمتها لإنجاز هذا البحث."],"example":[],"source":"الشريحة 49","table":[]},{"title":"تنظيم الأسئلة وإعطاء الإرشادات والتوجيهات والتنسيق الجيد Organizing Questions Giving Instructions And Guidance, And Good Alignment","body":["يساعد تنظيم الأسئلة في أجزاء مناسبة وكتابتها بأناقة وترتيبها بطريقة منطقية وتقديم تعليمات عن كيفية الإجابة على كل قسم المستجيب على إجابة الأسئلة دون أي صعوبة.","ومن الواجب ترتيب الأسئلة بطريقة تساعد المستجيب على الإجابة عليها دون بذل جهد ووقت كبيرين ودون إرهاق لعينيه."],"example":[],"source":"الشريحة 50","table":[]},{"title":"غير موافق بشدة | غير موافق | غير موافق قليلا | محايد | أوافق قليلا | موافق | أوفق بشدة","body":["7 | 6 | 5 | 4 | 3 | 2 | 1","تقدم الأسئلة التالية وصفاً لكيفية ممارستك لحياتك في مكان العمل. فكر من منطلق تجربتك اليومية، وما تنجزه في العمل، ثم اكتب رقم الإجابة المناسبة لك في المكان الموجود في نهاية كل جملة مستعيناً بالمقياس الآتي:","ــــــ | أقوم بأداء عملي بأفضل صورة عندما تكون المهام صعبة إلى حد ما | 1-","ــــــ | أسعى للحصول على دور ريادي في فريق العمل | 2-","ــــــ | أهتم جيداً بشعور الآخرين في العمل | 3-"],"example":[],"source":"الشريحة 51","table":[]},{"title":"البيانات الشخصية Personal Data","body":["يمكن تنظيم البيانات الشخصية كما هو موضح بالمثال الآتي:","يرجى وضع دائرة حول الرقم الذي يمثلك في الفئات الموجودة في المتغيرات الآتية:","3- المرتبة الوظيفية | 2- الحالة الاجتماعية | 1- العمر","1. الإدارة العليا | 1. متزوج | 1. تحت الـ 20","2. الإدارة الوسطى | 2. أعزب | 2. 20 – 35","3. المستوى الإشرافي الأول | 3. أرمل | 3. 36 – 50","4. وظائف غير إدارية | 4. مطلق | 4. 51 – 65"],"example":[],"source":"الشريحة 52","table":[]},{"title":"المعلومات الخاصة بالدخل والبيانات الشخصية الأخرى Information On Income And Other Sensetive Personal Data","body":["من الواجب تبرير طرح الأسئلة وبيان مقدار مساهمتها في حل المشكلة التي يواجهها الباحث للمستجيب حتى لا يعتبر ذلك تطفلا.","ويساعد طرح هذه الأسئلة في نهاية الاستبيان على تقليل مستوى تحيز المستجيب الناتج عن الاستفزاز الذي ربما تسببه الأسئلة ذات الطابع الشخصي ."],"example":[],"source":"الشريحة 53","table":[]},{"title":"نظراً لأن الكثير من الباحثين يعتقد أن الدخل عامل مهم في شرح القرارات التي يتخذها الأفراد، السؤال التالي مهم لهذا البحث. وسيتم المح","body":["- الدخل السنوي الإجمالي:","قبل خصم الضريبة والإعفاءات الأخرى","1. أقل من 36,000$","2. 36,000$ - 50,000 $","3. $50,001 - 70,000 $","4. 70,001 $ - 90,000 $","5. أعلى من 90,000 $"],"example":[],"source":"الشريحة 54","table":[]},{"title":"الأسئلة المفتوحة في نهاية الاستبيان : Open – Ended Question At The End","body":["هذه يوضع عادة سؤال مفتوح في نهاية الاستبيان من اجل تعليقات المبحوثين عن أي امر في الاستبيان أو عن أشياء ربما لم يتناولها الاستبيان.","ربما لم تعطك أسئلة الاستقصاء فرصة للتعبير عن رأيك في أشياء كثيرة ذات صلة بك أو بوظيفتك أو بالمنظمة التي تعمل فيها ، من فضلك اكتب أي تعليق بدور بخلدك في المساحة الخالية الآتية :"],"example":[],"source":"الشريحة 55","table":[]},{"title":"لمحة ختامية عن تصميم الاستبيانات:","body":["تعتبر الاستقصاءات من أكثر طرق جمع البيانات شيوعا وأكثرها فائدة خاصة إذا كانت العينة كبيرة ومنتشرة جغرافياً.","تمكن الاستقصاءات الباحثين من جمع البيانات وترميزها بيسر وسهولة.","الاستقصاء الذي تم التأكد من مصداقيته يحقق إضافات للأساس النظري الذي قام عليه البحث نظرا لأنه من الممكن تكرار الدراسة.","من الممكن أن يقوم الباحث بجمع البيانات بنفسه أو بمعاونة آخرين، ومن الممكن إلحاقها بإحدى المجلات أو الدوريات أو الصحف ، ومن الممكن إرسالها بالبريد أو بالبريد الإلكتروني.","هناك برامج كمبيوتر متاحة توجه المستقصى إلى السؤال الذي ينبغي إجابته بناء على الأسئلة أو السؤال السابق.","ومن الممكن استخدام مواقع الشركات الإلكترونية للحصول على إجابات للاستقصاءات مثل تلك الخاصة بخدمات العملاء."],"example":[],"source":"الشريحة 56","table":[]},{"title":"الباحث والأخلاق Ethics And The Researcher","body":["المحافظة على سرية وخصوصية بيانات المبحوثين.","عدم الخداع في شرح طبيعة الدراسة للمستجيبين.","لا ينبغي جمع المعلومات الشخصية إلا إذا كانت ضرورية جدا للبحث، ويجب أن يقدم بدقة الأسباب التي تجبره على ذلك.","لا يجب إجبار أي شخص على الإجابة على الاستقصاء.","لا ينبغي للملاحظ غير المشارك في العمل أن يتدخل فيه.","لا يجب تعريض المشاركين في الدراسة لظروف يكونون فيها عرضة للأضرار البدنية أو العقلية أو النفسية . وعلى الباحث أن يتحمل مسؤولية حمايتهم من هذه الأضرار.","لا يجوز للباحث إطلاقا أن يسيء شرح البيانات أو تشويهها عند تقديم تقرير عن البيانات التي تم جمعها ."],"example":["احم خصوصية المشاركين ولا تنشر الإجابات الفردية دون مسوغ وموافقة مناسبة."],"source":"الشريحة 57","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"أي مصدر يجمعه الباحث لأول مرة لأغراض دراسته؟","options":["المقابلات التي يجريها بنفسه","التقارير السنوية المنشورة","السجلات الحكومية السابقة","المقالات الصحفية القديمة"],"correct":0,"explain":"المقابلات المباشرة تجمع بيانات أولية خصيصًا للبحث الحالي."},{"num":2,"kind":"mc","question":"ما الفرق بين مجموعة التركيز والعينة الدائمة في المحاضرة؟","options":["كلاهما لا يجتمع إلا مرة واحدة","العينة الدائمة تُتابَع مرات متعددة","مجموعة التركيز عشوائية دائمًا","العينة الدائمة لا تجمع آراء الأفراد"],"correct":1,"explain":"العينات الدائمة تسمح بتتبع التغير عبر الزمن."},{"num":3,"kind":"mc","question":"في أي موقف تكون المقابلة غير المهيكلة أنسب؟","options":["فحص أولي لفهم مشكلة غامضة","تسجيل إجابات محددة موحدة من 1000 شخص","تطبيق اختبار تحصيلي موحد","توزيع استبيان مغلق"],"correct":0,"explain":"تتيح المقابلة غير المهيكلة أسئلة مفتوحة لاكتشاف العوامل المهمة."},{"num":4,"kind":"mc","question":"ما المثال الأفضل على سؤال غير متحيز؟","options":["ألا توافق أن التدريب ممتاز؟","لماذا لا تحب مديرك؟","كيف تصف تجربتك مع التدريب؟","أليس النظام الجديد فاشلًا؟"],"correct":2,"explain":"يسمح بوصف التجربة دون إيحاء بالإجابة."},{"num":5,"kind":"mc","question":"ما المقصود بالسؤال المركب (Double-barreled)؟","options":["سؤال يحوي موضوعين في وقت واحد","سؤال يتكون من سطرين فقط","سؤال فيه كلمة أجنبية","سؤال بنظام نعم/لا"],"correct":0,"explain":"دمج موضوعين مثل التدريب والراتب يجعل الإجابة ملتبسة."},{"num":6,"kind":"mc","question":"أي إجراء يقلل تحيز المقابلة؟","options":["إظهار رأي الباحث أثناء السؤال","توحيد طريقة طرح السؤال","تجاهل ملاحظات المبحوث","الضغط للحصول على جواب مرغوب"],"correct":1,"explain":"الطريقة الموحدة والمحايدة تساعد في تقليل التحيز."},{"num":7,"kind":"mc","question":"ما ميزة المقابلة وجهًا لوجه بحسب الشرائح؟","options":["عدم الحاجة إلى تدريب الباحث","إتاحة ملاحظة الإشارات غير اللفظية","منع أي تأثير للمقابل","أقل تكلفة دائمًا من الهاتف"],"correct":1,"explain":"يمكن للباحث ملاحظة لغة الجسد وطلب التوضيح المباشر."},{"num":8,"kind":"mc","question":"أي نوع من الأسئلة يُفضّل تجنبه في الاستبانة؟","options":["سؤال واضح قصير","سؤال أحادي الموضوع","سؤال يقود المبحوث إلى إجابة محددة","سؤال يعالج متغيرًا واحدًا"],"correct":2,"explain":"الأسئلة القيادية تضعف حياد القياس."},{"num":9,"kind":"tf","question":"البيانات الثانوية هي بيانات جُمعت مسبقًا لأهداف قد تختلف عن هدف الدراسة الحالية.","options":["صح","خطأ"],"correct":true,"explain":"يمكن إعادة استخدام بيانات منشورة أو سجلات إذا كانت صالحة للغرض الحالي."},{"num":10,"kind":"tf","question":"يجب أن يجيب كل شخص على جميع الأسئلة الشخصية الحساسة دون توضيح سبب جمعها.","options":["صح","خطأ"],"correct":false,"explain":"تذكر الشرائح الخصوصية والأخلاق والملاءمة في تصميم الأسئلة."},{"num":11,"kind":"short","question":"قارن بين المقابلة المهيكلة وغير المهيكلة بمثال.","options":[],"answer":"المهيكلة تتبع أسئلة مخططة موحدة. وغير المهيكلة تبدأ بأسئلة مفتوحة للاستكشاف؛ مثل استكشاف أسباب ضعف استخدام نظام معلومات."},{"num":12,"kind":"case","question":"حوّل سؤالًا موجهًا عن جودة التدريب إلى سؤال محايد.","options":[],"answer":"يمكن قول: «كيف تقيم جودة التدريب الذي تلقيته؟» بدلًا من «ألا ترى التدريب ممتازًا؟»."},{"num":13,"kind":"short","question":"ما المبادئ الثلاثة الأساسية لتصميم الاستبيان؟","options":[],"answer":"صياغة ألفاظ الأسئلة، ومبادئ القياس والتصنيف والترميز، والمظهر العام للاستبيان."}]},{"id":8,"title":"مجتمع الدراسة والعينات","source":"العرض 08.pptx — المحاضرة الثامنة","units":[{"title":"المجتمع والعينة ومبررات المعاينة","steps":[{"title":"المجتمع و العـيـنـات","body":["بعد تحديد الباحث لمشكلة البحث وفرضياته وقبل تحديد أداة القياس أو جمع المعلومات، لا بد له من تحديد مجتمع الدراسة Population Study، لأن صياغة الفرضية تكون على شكل عبارة تتكون من متغيرات تدل على سمات فراد أو أشياء تشكل المجتمع الإحصائي والذي يعرف بأنه جميع الأفراد أو الأشخاص أو الأشياء الذين يكونون موضوع مشكلة البحث.","وإذا استطاع الباحث إجراء دراسته على جميع أفراد المجتمع، فإن دراسته تكون ذات نتائج أقرب للواقع وأكثر دقة، ولكن الباحث قد يجد صعوبة في التعامل مع كل مشاهدة من مشاهدات المجتمع لعدة أسباب، مما سيضطره لإجراء الدراسة على مجموعة جزئية من مجتمع الدراسة، وهذه المجموعة نسميها عينة الدراسة."],"example":["مجتمع البحث هو جميع الوحدات المستهدفة، أما العينة فهي جزء يُختار منها وفق تصميم محدد."],"source":"الشريحة 2","table":[]},{"title":"المجتمع و العـيـنـات","body":["وبذلك نصوغ التعريفات التالية :","مجتمع الدراسة : كامل الأفراد أو الأحداث أو المشاهدات موضوع البحث أو الدراسة.","العينة : مجموعة جزئية من مجتمع الدراسة يتم اختيارها بطريقة معينة."],"example":[],"source":"الشريحة 3","table":[]},{"title":"المجتمع و العـيـنـات","body":["إن اختيار العينة بشكل دقيق ومناسب يعطي نتائج مشابهة إلى حد كبير للنتائج التي يمكن الحصول عليه عند دراسة كامل مجتمع الدراسة.","بشكل عام كلما كان حجم العينة اكبر كلما زاد تمثيلها لخصائص المجتمع موضوع الدراسة.","لذلك يمكن تعميم النتائج التي يتم التوصل إليها من خلال دراسة العينة على مجتمع الدراسة الأصلي.","حيث نعلم ان زيادة أفراد العينة تزيد من إمكانية تمثيل العينة لسمات مجتمع الدراسة مما يساعد في رفض الفرضية التي لا تتفق مع هذه السمات."],"example":[],"source":"الشريحة 4","table":[]},{"title":"أسباب اللجوء إلى استخدام العينات","body":["التكلفة والجهد وطول الوقت : فقد يكون مجتمع الدراسة يقع على مساحة جغرافية كبيرة مما يضطر الباحث للتنقل مسافات طويلة لفحص عناصر المجتمع، مما يكلف مالا وجهدا ووقتا طويلا، كما هو الحال لو كان موضوع الدراسة؛ العلاقة بين دخل الأسرة ومستوى التعليم لرب الأسرة، فإن إجراء الدراسة على كامل الأسر يتطلب تكلفة عالية وجهدًا كبيرين لجمع البيانات، خاصة إذا كانت الدراسة لمساعدة متخذي القرار على اتخاذ قرار مناسب وسريع، لذلك يمكن إجراء الدراسة على عينة ممثلة ومن ثم تعميم النتائج.","التجانس التام : فعندما تكون عناصر المجتمع متجانسة بشكل تام فإن نفس النتائج يمكن الحصول عليها سواء أجريت الدراسة على كامل المجتمع أو على أجزاء منه، فعند إجراء الدراسة على مادة كيماوية بتركيز معين لمختبرات وزارة التربية يكفي إجراء التجربة على جزء من المادة لأن المادة متجانسة."],"example":[],"source":"الشريحة 5","table":[]},{"title":"أسباب اللجوء إلى استخدام العينات","body":["تلف العناصر نتيجة اخذ المشاهدات عليها: لمعرفة مدى صلاحية نوع من الأدوية لا يعقل فتح جميع الأدوية للفحص والمعاينة.","عدم إمكانية حصر مجتمع الدراسة : فإذا كان موضوع الدارسة اختبار فعالية علاج معين جديد لمرض السرطان فلا يمكن حصر جميع المصابين والذين سيصابون بالمرض مستقبلا.","حساسية التجربة : إذا كان موضوع الدراسة طريقة جديدة لتعليم مبحث ما، فلا يعقل تطبيق الطريقة الجديدة على جميع الطلبة قبل التأكد من فعاليتها، ومن المنطقي إن تجرى التجربة على عينة من الطلبة، وفي ضوء النتائج يتم اتخاذ القرار المناسب بشأنها."],"example":[],"source":"الشريحة 6","table":[]}]},{"title":"حجم العينة وحساباته","steps":[{"title":"تحديد حجم العينة","body":["هناك ما يعرف بخطأ العينة وهو الخطأ الناتج عن اعتماد العينة في الدراسة، و أن مصدري الخطأ هما:","طرق اختيار العينة و حجم العينة.","ومن المعروف في علم الإحصاء حين نصف مقدار خطأ العينة الناتج عن حجم العينة يعبر عنه بنسبة مئوية مثل (+ أو – 5%) ويوصف إحصائياً بدرجة الثقة."],"example":[],"source":"الشريحة 7","table":[]},{"title":"حساب حجم العينة","body":["تستخدم الطريقة التالية لحساب حجم العينة، أي عدد المفردات الداخلة فيها. وصيغة هذه الطريقة كالآتي:","وتسمى صيغة مد الثقة","Confidence Interval Formula حين تكون"],"example":[],"source":"الشريحة 8","table":[]},{"title":"حجم العينة كنسبة مئوية من مجتمع البحث:","body":["يمكن تحديد حجم العينة من قبل الباحث على أساس نسبة مئوية من مجتمع البحث، مثلاً 5% أو 10 % فإذا كان حجم مجتمع البحث هو 1000 عميل فإن حجم العينة يحسب كما يلي:","حجم العينة : = 1000x5% = 50 مفردة (عميل)","أو حجم العينة =1000x10% = 100 مفردة (عميل)","ميزانية البحث:","يمكن تحديد حجم العينة على أساس ميزانية البحث ، أي أن عامل التكلفة هو أساس اختيار حجم العينة. فإذا كانت ميزانية البحث التسويقي عن مدا رضا متاجر التجزئة عن شروط البيع من المنتج هي 100000 ريال وكانت التكاليف الثابتة المخصصة لتصميم البحث وتحليل البيانات هي 20000 ريال وكانت تكلفة الحصول عل ى البيانات من المفردة الواحدة متجر التجزئة( هي 100 ريال فإن حجم العينة يحسب كما يلي:","حجم العينة = (100000-20000) ÷100","= 80000÷100"],"example":["مثال الشرائح: ميزانية 100000 وتكلفة ثابتة 20000 وتكلفة استجابة 100 تعطي 800 مفردة وفق نموذج التكاليف."],"source":"الشريحة 9","table":[]},{"title":"تنبيه منهجي: الحجم ليس نسبة ثابتة","body":["تذكر الشرائح طرقًا مبسطة مثل نسبة من المجتمع أو 1/(الخطأ²). هذه ليست بديلًا عامًّا لحساب الحجم بناء على مستوى الثقة والتباين والتصميم والاستجابة المتوقعة."],"example":["اختر طريقة تتلاءم مع هدف تقدير النسبة أو اختبار الفرضيات وخصائص المجتمع."],"source":"ملاحظة تعليمية حول الشرائح 8–9","table":[]}]},{"title":"العينات الاحتمالية","steps":[{"title":"أنواع العينات","body":["راجع الفكرة المذكورة في عنوان الشريحة ثم قارنها بموضوع الوحدة."],"example":[],"source":"الشريحة 10","table":[]},{"title":"العينة العشوائية البسيطة Simple Random Sample","body":["أنواع العينات Samples Types","هذا النوع من العينات يعني تكافؤ الفرص لجميع عناصر المجتمع لتكون أحد مفردات العينة، ويتم اختيارها إما باستخدام القرعة Lottery method، أو جداول الأرقام العشوائية Random number table ، ويتطلب استخدام هذه الطريقة ضرورة حصر ومعرفة كامل العناصر التي يتكون منها مجتمع الدراسة، وبذلك تكون فرصة الظهور لكل عنصر معروفة ومحددة مسبقا."],"example":[],"source":"الشريحة 11","table":[]},{"title":"القرعة Lottery method","body":["مثال: تقييم انتشار تسوس الأسنان بين 800 طفل يذهبون إلى المدرسة","- قائمة الأطفال الملتحقين بالمدرسة","- عدد الأطفال من 1 إلى 800","- حجم العينة = 40 طفلاً","- أخذ عينات عشوائية من 40 رقمًا بين 1 و 800"],"example":[],"source":"الشريحة 12","table":[]},{"title":"العينة المنتظمة Systematic Sample","body":["أنواع العينات Samples Types","في هذا النوع من العينات يتم حصر عناصر المجتمع وإعطاء أرقام متسلسلة لكل عنصر، ثم قسمة عدد عناصر المجتمع على العدد المطلوب للعينة ليكون الناتج طول فترة الاختيار، ويتم اختيار رقم عشوائي اصغر من طول فترة الاختيار، ويكون هو تسلسل أول عناصر العينة، ونضيف طول الفترة على تسلسل العنصر الأول لينتج تسلسل العنصر الثاني، وهكذا حتى ينتهي اختيار جميع المفردات، مثال على ذلك اختبار فحص الجودة والذي يتم فيه اخذ علبة من كل 100 علبة تسير على خط الإنتاج."],"example":[],"source":"الشريحة 13","table":[]},{"title":"مثال: ضع في اعتبارك مثال الأطفال وحدد حجم عينة من 40.","body":["أنواع العينات Samples Types العينة المنتظمة Systematic Sample","قسّم 800 طفل على 40 (حجم العينة) = 20 ، لذلك يتم أخذ عينة من كل 20 طفلًا. في هذا النهج ،","يجب أن نختار عددًا عشوائيًا بين 1 و 20 أولاً ، ثم نختار كل عشرين طفلًا.","لنفترض أننا قمنا باختيار الأطفال ذوي رقم الهوية 8 بشكل عشوائي. ثم ، تتكون العينة المنهجية من الأطفال الذين لديهم أرقام هوية 8 ، 28 ، 48 ، 68 ، 78 ، وما إلى ذلك ؛","يتم تحديد كل رقم لاحق عن طريق إضافة 20 إلى آخر رقم معرف"],"example":["إذا كان N=800 وn=40 فإن فترة المعاينة 20؛ نبدأ من 8 ثم 28،48،68،88. في الشريحة ظهر 78 بعد 68 وهو سهو في التسلسل."],"source":"الشريحة 14","table":[]},{"title":"العينة الطبقية Striated Sample","body":["أنواع العينات Samples Types","نستخدم هذا النوع من العينات عندما يكون هناك تباين (عدم تجانس) واضح في مجتمع الدراسة، بحيث يمكن تقسيم مجتمع الدراسة إلى مجموعات أو طبقات بناءًا على هذا التباين، فعند دراسة اتجاهات طلبة جامعة ما نحو العمل التطوعي، نجد انه من الأفضل تقسيم الطلبة إلى طبقات حسب السنة الدراسية أولى، ثانية، ثالثة، رابعة، دراسات عليا."],"example":["في العينة الطبقية نقسم المجتمع حسب فئات مهمة ثم نختار عينة من كل طبقة."],"source":"الشريحة 16","table":[]},{"title":"ولنفترض انه بالرجوع إلى السجلات الرسمية في الجامعة وجدت البيانات المبينة في الجدول التالي:","body":["أنواع العينات Samples Types","فئات الطلبة | سنه أولى | سنة ثانية | سنة ثالثة | سنة رابعة | دراسات عليا | المجموع","عدد الطلبة | 700 | 800 | 700 | 600 | 200 | 3000"],"example":[],"source":"الشريحة 17","table":[]},{"title":"العينة العنقودية Cluster Sample","body":["أنواع العينات Samples Types","وهذه تعني أن مجتمع الدراسة يمكن تقسيمه إلى عدة شرائح وكل شريحة يمكن تقسيمها إلى عدة شرائح أخرى وكأننا نتحدث عن عنقود عنب ضخم ،","على سبيل المثال فإن وزارة التربية والتعليم تمثل مجموعة مديريات وكل مديرية تمثل مجموعة مدارس وكل مدرسة تمثل مجموعة صفوف وكل صف يمثل مجموعة طلبة، وبذلك يمكن اختيار الصف السادس الابتدائي في مدرسة ما والصف السادس الابتدائي في مدرسة أخرى كعينة عنقودية عن طلبة الصف السادس في جميع أنحاء الدولة ،","تستخدم هذه العينة لعدة أسباب أهمها لتسهيل الالتقاء بأفراد العينة المدروسة، وعدم تعطيل العملية التربوية في المدارس بسبب اخذ العينة من الصفوف لإجراء التجارب."],"example":["العينة العنقودية تختار مجموعات طبيعية مثل مدارس أو صفوف بدلًا من أفراد متفرقين."],"source":"الشريحة 18","table":[]},{"title":"أنواع العينات Samples Types","body":["راجع الفكرة المذكورة في عنوان الشريحة ثم قارنها بموضوع الوحدة."],"example":[],"source":"الشريحة 19","table":[]},{"title":"العينة العشوائية البسيطة | جميع عناصر المجتمع لها نفس الفرصة في الظهور في العينة","body":["أنواع العينات Samples Types","العينة الطبقية | يقسم المجتمع إلى طبقتين على الأقل ثم نختار العينة من كل منهما","العينة المنتظمة | نختار نقطة بداية من المجتمع ثم نختار العنصر الموجود على بعد ثابت من هذه النقطة","العينة العنقودية | يقسم المجتمع إلى مساحات أو أجزاء ثم نختار عشوائيا بعض هذه المساحات، ثم نختار جميع عناصرها بالعينة."],"example":[],"source":"الشريحة 20","table":[]}]},{"title":"العينات غير الاحتمالية","steps":[{"title":"العينات غير العشوائية nonrandom Samples","body":["أنواع العينات Samples Types","تستخدم هذه العينات في حالة عدم القدرة على تحديد مجتمع الدراسة بشكل دقيق، وتتصف هذه العينات بأنها لا تعطي نفس الفرصة لجميع أفراد مجتمع الدراسة بالظهور في العينة. ومن أنواع هذه العينات ما يلي :","العينة الصدفة ( العرضية) Accidental Sample","وهذا النوع من العينة يتم اختياره بالصدفة مثلما تستطلع صحيفة معينة الرأي العام حول قضية معينة ، وغالبا ما يكون هذا النوع من العينات غير ممثلا لمجتمع الدراسة."],"example":[],"source":"الشريحة 21","table":[]},{"title":"العينة القصدية Purposive Sample","body":["أنواع العينات Samples Types","يتم استخدام أخذ العينات الملائمة في البحث الاستكشافي حيث يهتم الباحث بالحصول على تقدير تقريبي غير مكلف.","يتم اختيار العينة لأنها مريحة.","إنها طريقة غير عشوائية.","غالبًا ما تستخدم أثناء جهود البحث الأولية للحصول على تقدير دون تكبد التكلفة أو الوقت اللازم لاختيار عينة عشوائية","من الأمثلة الأكثر واقعية اختيار خمسة أشخاص من فصل أو اختيار الأسماء الخمسة الأولى من قائمة المرضى.","عينة كرة الثلج Snowball sampl"],"example":["تنبه: المثال الخاص بالاختيار «المريح» في الشريحة يدخل تحت العينة الملائمة، وليس القصدية بالمعنى الدقيق؛ تذكر أيضًا كرة الثلج."],"source":"الشريحة 22","table":[]},{"title":"العينة القصدية Purposive Sample","body":["أنواع العينات Samples Types","ينتقي الباحث أفراد عينته بما يخدم أهداف دراسته وبناءا على معرفته دون أن يكون هناك قيود أو شروط غير التي يراها هو مناسبة من حيث الكفاءة أو المؤهل العلمي أو الاختصاص أو غيرها، وهذه عينة غير ممثلة لكافة وجهات النظر ولكنها تعتبر أساس متين للتحليل العلمي ومصدر ثري للمعلومات التي تشكل قاعدة مناسبة للباحث حول موضوع الدراسة.","عينة التطوع Volunteer Sample","تحتاج بعض الدراسات إلى متطوعين لإجرائها مثل التحدث مع اختصاصي حول موضوع محدد، أو لإجراء التجارب التربوية أو النفسية، و غالبا لا تمثل هذه العينة مجتمع الدراسة، ولكنها تسهل على الباحث التعاون من قبل أفراد العينة وسرعة الإنجاز."],"example":[],"source":"الشريحة 23","table":[]},{"title":"العينة الحكمية Judgment sample","body":["أنواع العينات Samples Types","أخذ العينات الحكمية هو طريقة شائعة غير عشوائية.","يتم اختيار العينة بناءً على الحكم.","امتدادا لأخذ العينات الملائمة (convenience sampling) عند استخدام هذه الطريقة ، يجب أن يكون الباحث واثقًا من أن العينة المحددة تمثل حقًا المجتمع بأكمله.","في دراسة يريد فيها الباحث معرفة ما يتطلبه التخرج بامتياز في الكلية ، الأشخاص الوحيدون الذين يمكنهم تقديم المشورة للباحث مباشرة هم الأفراد الذين تخرجوا بامتياز. مع هذه المجموعة المحددة للغاية والمحدودة للغاية من الأفراد التي يمكن اعتبارها موضوعًا ، يجب على الباحث استخدام أخذ العينات الحكمية.","العينة الحصصية Quota sampl","أخذ العينات الحصصية هو المشابه غير العشوائي لأخذ العينات الطبقية."],"example":["العينة الحصصية ليست عشوائية تلقائيًا حتى عندما تطابق نسب الفئات في المجتمع."],"source":"الشريحة 24","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"ما تعريف مجتمع الدراسة؟","options":["جميع الوحدات محل البحث","الأشخاص الذين وافقوا على المقابلة فقط","العينة النهائية وحدها","عدد المتغيرات المقاسة"],"correct":0,"explain":"المجتمع هو جميع الأفراد أو الأحداث أو المشاهدات التي تتعلق بها المشكلة."},{"num":2,"kind":"mc","question":"إذا أردت اختيار كل عنصر رقم 20 بعد بداية عشوائية، فما نوع العينة؟","options":["الطبقية","المنتظمة","القصدية","كرة الثلج"],"correct":1,"explain":"العينة المنتظمة تستخدم فترة اختيار ثابتة وبداية عشوائية."},{"num":3,"kind":"mc","question":"ما العينة الأنسب عندما يتكون المجتمع من مستويات تعليمية واضحة ونريد تمثيل كل مستوى؟","options":["الطبقية","الصدفة","الملائمة","الحكمية"],"correct":0,"explain":"تقسيم المجتمع إلى طبقات ثم سحب أفراد من كل طبقة."},{"num":4,"kind":"mc","question":"ما مثال العينة العنقودية؟","options":["سحب أسماء أفراد من جدول عام","اختيار مدارس ثم اختيار طلاب ضمنها","اختيار من يحضر مبكرًا","اختيار الخبراء عمدًا"],"correct":1,"explain":"العنقودية تعتمد على اختيار مجموعات أو تجمعات طبيعية."},{"num":5,"kind":"mc","question":"ما نوع المعاينة المبنية على إحالات مشارك إلى مشارك؟","options":["العشوائية البسيطة","الطبقية","كرة الثلج","المنتظمة"],"correct":2,"explain":"كرة الثلج تستخدم إحالات المشاركين للوصول إلى أفراد يصعب حصرهم."},{"num":6,"kind":"mc","question":"إذا كان N=800 وn=40 فما فترة الاختيار المنتظم؟","options":["8","10","20","40"],"correct":2,"explain":"نقسم 800 على 40 فنحصل على 20."},{"num":7,"kind":"mc","question":"من نقطة بداية 8 وفترة اختيار 20، ما الرقم الخامس؟","options":["68","78","88","98"],"correct":2,"explain":"التسلسل الصحيح 8،28،48،68،88. ظهر في الشريحة 78 في موضع غير صحيح."},{"num":8,"kind":"mc","question":"إذا كانت الميزانية 100000 والتكاليف الثابتة 20000 وتكلفة الاستجابة 100، فما الحجم بحسب معادلة الميزانية؟","options":["200","500","800","1000"],"correct":2,"explain":"(100000−20000) ÷ 100 = 800 مفردة."},{"num":9,"kind":"tf","question":"زيادة حجم العينة وحدها تضمن إزالة جميع أشكال التحيز في الاختيار.","options":["صح","خطأ"],"correct":false,"explain":"يتوقف تمثيل المجتمع على أسلوب الاختيار والتغطية والتحيز، وليس الحجم فقط."},{"num":10,"kind":"tf","question":"العينة العشوائية البسيطة تمنح وحدات المجتمع فرص اختيار معلومة في إطار السحب المناسب.","options":["صح","خطأ"],"correct":true,"explain":"تقوم على اختيار عشوائي من إطار واضح للوحدات."},{"num":11,"kind":"short","question":"اشرح الفرق بين العينة الطبقية والعنقودية.","options":[],"answer":"الطبقية تختار أفرادًا من كل طبقة مهمة، والعنقودية تختار مجموعات طبيعية وقد تختار جميع أفرادها أو عينة منهم."},{"num":12,"kind":"case","question":"احسب الحجم باستخدام 1/e² إذا كان e=0.05، واذكر تحفظًا.","options":[],"answer":"الحساب المبسط في الشريحة = 1/0.0025 = 400، لكنه ليس صيغة عامة لكل تصميم؛ يلزم النظر في مستوى الثقة والتباين وغيرها."}]},{"id":9,"title":"تجهيز البيانات وتحليلها","source":"العرض 09.ppt — المحاضرة التاسعة (الشرائح 1–6)","units":[{"title":"خطوات تجهيز البيانات","steps":[{"title":"خطوات تحليل البيانات","body":["أولاً : تجهيز البيانات للتحليل:","مراجعة البيانات","معالجة الأسئلة التي تركت دون إجابة","إدخال البيانات إلى الحاسب","ثانياً : تحليل البيانات","التعرف على البيانات","اختبار جودة البيانات"],"example":[],"source":"الشريحة 2","table":[]},{"title":"1- مراجعة البيانات","body":["يفضل أن تراجع البيانات في اليوم الذي جمعت فيه لإمكانية الاتصال بمن جمعت منهم البيانات في حال ظهور حاجة لذلك .","يفضل كتابة البيانات المراجعة بلون مختلف عن الذي كتبت فيه البيانات الأصلية .","من الواجب الاحتفاظ بالبيانات الأصلية لإمكانية الرجوع لها."],"example":[],"source":"الشريحة 3","table":[]},{"title":"2- معالجة الأسئلة التي تركت دون إجابة","body":["قد لا يجيب المبحوثين عن كل أسئلة الاستقصاء نتيجة لعدم فهم السؤال، أو عدم معرفة الإجابة أو عدم الرغبة في ذلك.","إذا ترك جزء كبير من الاستقصاء دون إجابة (25% فأكثر) ، يتم إسقاط هذا الاستقصاء.","من المفضل ذكر عدد الاستقصاءات غير المفيدة والتي تم التخلص منها في التقرير النهائي .","إذا كان عدد الأسئلة المتروكة قليل على الباحث اتخاذ قرار بشأن ذلك"],"example":["لا تستخدم نسبة فقد 25% قاعدة عامة ثابتة في كل بحث؛ وثّق حجم القيم المفقودة ونمطها واختر المعالجة بحسب تحليل الحساسية."],"source":"الشريحة 4","table":[]},{"title":"طرق معالجة الأسئلة المتروكة","body":["إعطاء الإجابات الخالية القيمة المتوسطة في المقياس.","توجيه الكمبيوتر لإهمال الإجابات الخالية، وعدم احتسابها عند التحليل.","استبدالها بقيمة المتوسط الحسابي لإجابة أفراد العينة على كل متغير من تلك المتغيرات.","استبدالها بالمتوسط الحسابي لإجابة صاحب الاستبيان نفسه على كل الأسئلة التي تقيس هذا المتغير (الذي توجد فيه القيمة المفقودة).","أشهر الطرق لمعالجة الأسئلة المتروكة :","استبدال الأسئلة المتروكة بالقيمة المتوسطة على المقياس (3 على المقياس الخماسي ) .","إهمال الأسئلة المتروكة أثناء التحليل خاصة عندما يكون حجم العينة كبيراً ، لأن ذلك يعطي مستوى صلاحية أكبر ."],"example":["تعويض القيمة بالمتوسط قد يقلل التباين ويؤثر في العلاقات بين المتغيرات؛ لا تعتمد هذا الأسلوب دون مبرر."],"source":"الشريحة 5","table":[]},{"title":"3- الترميز coding","body":["إعطاء ترميز معين لمتغيرات الاستبانة (أرقام) بحسب فئات كل متغير.","4- التصنيف categorization:","يجب وضع خطة لتصنيف متغيرات البحث.","يجب تجميع المتغيرات التي تقيس ظاهرة معينة معاً قبل إدخال البيانات إلى الكمبيوتر.","تغيير اتجاهات بعض الأسئلة التي تمت صياغتها في صورة نفي (العبارات السلبية والعبارات الايجابية).","5- إدخال البيانات الى الحاسب"],"example":[],"source":"الشريحة 6","table":[]}]},{"title":"تطبيق تحريري قبل التحليل","steps":[{"title":"ما الترتيب الصحيح لمعالجة البيانات؟","body":["فحص الاستجابات ومراجعتها، والتعرف على المفقود، والترميز والتصنيف، وإدخال البيانات أو استيرادها، ثم فحص جودتها قبل الاختبارات.","احفظ الأصل، ووثّق كل تعديل، وحدد أسلوب معالجة القيم المفقودة قبل تقرير النتائج."],"example":["مثال: إذا كانت فقرة سالبة في مقياس ليكرت 1–5 فقد تحتاج عكس الترميز: الدرجة الجديدة = 6 − الدرجة الأصلية."],"source":"إيضاح تطبيقًا للمحاضرة التاسعة","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"ما أول خطوة قبل تحليل الاستجابات؟","options":["مراجعة البيانات","إعلان النتائج","اختيار الألوان","حذف كل استبيان ناقص تلقائيًا"],"correct":0,"explain":"تبدأ المحاضرة بمراجعة البيانات المكتملة والملاحظات."},{"num":2,"kind":"mc","question":"ما وظيفة الترميز؟","options":["تحويل فئات الإجابات إلى رموز منظمة","اختبار قيمة p مباشرة","زيادة حجم العينة","إعادة كتابة أهداف البحث"],"correct":0,"explain":"الترميز يخصص قيمًا أو تسميات منظمة لفئات المتغيرات."},{"num":3,"kind":"mc","question":"كيف يمكن عكس الدرجة على مقياس خماسي 1–5؟","options":["5−الدرجة","6−الدرجة","الدرجة÷5","الدرجة+1"],"correct":1,"explain":"الترميز المعكوس الصحيح لخمس فئات هو 6−القيمة الأصلية."},{"num":4,"kind":"mc","question":"ما التصرف المناسب عند اكتشاف إجابة مفقودة؟","options":["تعويضها دائمًا بالمتوسط","توثيقها ثم اختيار معالجة مبررة","حذف جميع المشاركين","تغييرها عشوائيًا"],"correct":1,"explain":"اختيار المعالجة يعتمد على حجم الفقد ونمطه وأثره في النتائج."},{"num":5,"kind":"mc","question":"ما المقصود بالتصنيف في تجهيز البيانات؟","options":["إلغاء الاستبيانات","تجميع المتغيرات والفئات وفق خطة تحليلية","تغيير العناوين","إثبات الفرضية"],"correct":1,"explain":"تتطلب المحاضرة خطة واضحة لتصنيف المتغيرات."},{"num":6,"kind":"tf","question":"يمكن الاحتفاظ بالبيانات الأصلية مع توثيق التعديلات التي تجري أثناء التنظيف.","options":["صح","خطأ"],"correct":true,"explain":"هذا ضروري للمراجعة والتتبع وإمكان العودة للأصل."},{"num":7,"kind":"tf","question":"تعويض جميع القيم المفقودة بالمتوسط لا يؤثر في التباين أو الارتباطات.","options":["صح","خطأ"],"correct":false,"explain":"التعويض غير المدروس بالمتوسط قد يخفض التباين ويشوه العلاقات."},{"num":8,"kind":"short","question":"رتب خطوات تجهيز البيانات الخمس الواردة في المحاضرة.","options":[],"answer":"مراجعة البيانات، معالجة الأسئلة المتروكة، الترميز، التصنيف، إدخال البيانات إلى الحاسب."},{"num":9,"kind":"case","question":"إذا كانت الدرجة الأصلية 2 على عبارة سلبية بمقياس خماسي، فما الدرجة المعكوسة؟","options":[],"answer":"6 − 2 = 4."}]},{"id":10,"title":"اختبار الفرضيات والمعلمية واللامعلمية","source":"العرض 09.ppt — المحاضرة العاشرة (الشرائح 7–54)","units":[{"title":"الفرضيات الصفرية والبديلة","steps":[{"title":"المحاضرة العاشرة اختبار الفرضيات Hypothesis Testing الاختبارات المعلمية واللامعلمية Parametric and Non-Parametric Tests","body":["راجع الفكرة المذكورة في عنوان الشريحة ثم قارنها بموضوع الوحدة."],"example":[],"source":"الشريحة 7","table":[]},{"title":"يهدف اختبار الفرضية إحصائيا إلى اتخاذ قرار حول ما إذا كانت الفرضية الصفرية Null Hypothesis مقبولة أم مرفوضة ويتم ذلك باستخدام دالة","body":["اختبار الفرضيات Hypothesis Testing","وقبول الفرضية الصفرية لا يعني بالضرورة أنها صحيحة وإنما لا يوجد أدلة كافية من بيانات العينة لرفضها، كما أن رفضها لا يعني بالضرورة أنها خاطئة بل يعني أن الإحصائي المحسوب من العينة كان بعيدا عن المعلمة المناظرة له في المجتمع لدرجة أن احتمال أن تكون قيمته متطرفة بهذا البعد عندما تكون الفرضية الصفرية صحيحة أمر نادر الحدوث مما يدفعنا إلى رفض هذه الفرضية الصفرية."],"example":["عدم رفض H0 لا يعني إثبات صحتها، وإنما عدم وجود أدلة كافية لرفضها وفق الاختبار المستخدم."],"source":"الشريحة 8","table":[]},{"title":"يهدف اختبار الفرضية إحصائيا إلى اتخاذ قرار حول ما إذا كانت الفرضية الصفرية Null Hypothesis مقبولة أم مرفوضة ويتم ذلك باستخدام دالة","body":["اختبار الفرضيات Hypothesis Testing","يوجد نوعان من الفرضيات يستخدمان في اختبار الفرضيات وهما الفرضية الصفرية أو العدمية (Null Hypothesis) ويرمز لها:","H0 (المتهم برئ)","والفرضية البديلة (alternative Hypothesis ) ويرمز لها:","H1 (المتهم مذنب)","إدانة المتهم تعني رفض (H0) أي أن هناك دليل كافي على أن المتهم مذنب، أما عدم رفض الفرضية (H0) فيعني انه لا يوجد دليل كافي لإدانة المتهم. وهنا نلاحظ أننا لم نقل بأننا قبلنا الفرضية الصفرية لان هذا يعني أن النتائج أثبتت أن المتهم برئ."],"example":[],"source":"الشريحة 9","table":[]},{"title":"بناء على ما سبق تكون الفرضيات كالتالي:","body":["الفرضية الصفرية Null Hypothesis (H0):","تتضمن القيمة المفترضة لمعلمة المجتمع.","يجب أن تتضمن إشارة التساوي (=).","الاختبار يجري للفرضية الصفرية مباشرة.","نتيجة الاختبار هي رفض الفرضية الصفرية أو عدم القدرة على رفضها.","الفرضية البديلة alternative Hypothesis (H1):","يرمز لها (H1 or Ha) وهي النقيض المنطقي للفرضية الصفرية ويكون لها ثلاث حالات :"],"example":[],"source":"الشريحة 10","table":[]},{"title":"كيفية تحديد كلاً من (H0 و H1)","body":["لتحديد الفرضية الصفرية والفرضية البديلة باستخدام الرموز تمهيدا لإجراء الاختبار الإحصائي ينبغي الالتزام بالخطوات التالية:","حدد الفرضية أو الادعاء المراد اختباره وذلك باستخدام الرموز.","حدد باستخدام الرموز الفرضية المقابلة التي ينبغي أن تكون صحيحة إذا ما كانت الفرضية الأصلية أو الادعاء المراد اختباره في الخطوة سابقة خاطئ.","بناء على الخطوتين السابقتين اجعل الفرضية التي لا تتضمن إشارة التساوي (=) هي الفرضية البديلة والتي ينبغي أن تتضمن احد الإشارات التالية (≠ ، <، >). اجعل الفرضية التي تتضمن إشارة التساوي هي الفرضية الصفرية"],"example":[],"source":"الشريحة 11","table":[]},{"title":"أمثلة على كيفية تحديد كلاً من (H0 و H1)","body":["حدد كلاً من الفرضية الصفرية (H0) والفرضية البديلة (H1) بناءً على الخطوات الثلاثة السابقة وذلك في كلٍ من الحالات التالية التي تمثل فرضيات أو ادعاءات يراد اختبارها:","نسبة مبيعات الشركة في السوق المحلية أكبر من 0.5","متوسط أرباح المصارف العاملة في فلسطين لا يتجاوز 3 مليون دولار في عام 2008.","الانحراف المعياري لودائع العملاء في المصارف الوطنية يساوي 20 مليون دولار."],"example":[],"source":"الشريحة 12","table":[]},{"title":"1- نسبة مبيعات الشركة في السوق المحلية أكبر من 0.5","body":["الفرضية أو الادعاء المراد اختباره بالرموز هو: (P > 0.5)","حسب الخطوة الثانية إذا كانت الفرضية السابقة خاطئة فان الفرضية التالية ستكون صحيحة (النقيض المنطقي لها) وباستخدام الرموز ستكون كما يلي: ( p ≤ 0.5).","حسب الخطوة الثالثة فان الفرضية التي لا تتضمن إشارة التساوي ستكون الفرضية البديلة والفرضية التي تتضمن إشارة التساوي ستكون الفرضية الصفرية كما يلي:","H0: p ≤ 0.5","H1: P > 0.5"],"example":[],"source":"الشريحة 13","table":[]},{"title":"2- متوسط أرباح المصارف العاملة في فلسطين لا يتجاوز 3 مليون دولار في عام 2008.","body":["الفرضية أو الادعاء المراد اختباره في البحث هنا باستخدام الرموز هو: ( μ ≤ 3).","النقيض المنطقي للفرضية السابقة هو: ( μ > 3).","الفرضية التي تتضمن إشارة التساوي هي الفرضية الصفرية: ( μ ≤ 3) H0:","والفرضية التي لا تتضمن إشارة التساوي هي الفرضية البديلة: ( μ > 3) H1:"],"example":[],"source":"الشريحة 14","table":[]},{"title":"3- الانحراف المعياري لودائع العملاء في المصارف الوطنية يساوي 20 مليون دولار.","body":["الفرضية أو الادعاء المراد اختباره في البحث هنا باستخدام الرموز هو: (σ = 20).","النقيض المنطقي للفرضية السابقة هو: (σ ≠ 20 ).","الفرضية التي تتضمن إشارة التساوي هي الفرضية الصفرية: (σ = 20) H0:","والفرضية التي لا تتضمن إشارة التساوي هي الفرضية البديلة: (σ ≠ 20 ) H1:"],"example":[],"source":"الشريحة 15","table":[]}]},{"title":"الدلالة والأخطاء وقوة الاختبار","steps":[{"title":"احصاءة الاختبار (Test Statistic)","body":["احصاءة الاختبار (Test Statistic): هي قيمة محسوبة من بيانات العينة باستخدام ما يعرف بدالة الاختبار، واعتمادا على احصاءة الاختبار يتم اتخاذ القرار بقبول أو عدم قبول الفرضية الصفرية. وتتم المقارنة بين قيمة دالة الاختبار الإحصائية المحسوبة من العينة مع قيمته المستخرجة من توزيعه الاحتمالي (توجد جداول خاصة لكل توزيع) وتسمى بالقيمة الجدولية وبناء عليه يتم اتخاذ القرار كما يلي:","1– إذا كانت القيمة المحسوبة اكبر من القيمة الجدولية يتم رفض الفرضية الصفرية.","2- إذا كانت القيمة المحسوبة اقل من القيمة الجدولية يتم قبول الفرضية الصفرية."],"example":["قرار الاختبار لا يقوم على «المحسوبة أكبر من الجدولية» دائمًا؛ الاتجاه وإشارة الإحصاء ونوع الاختبار تحدد المنطقة الحرجة."],"source":"الشريحة 16","table":[]},{"title":"مفهوم مستوى المعنوية the level of significance","body":["يمكن توضيح مستوى المعنوية من خلال المثال التالي:","شركة تنتج نوع معين من السيارات ادعت أن سياراتها توفر كثيرا في كمية الوقود وان متوسط المسافة التي تقطعها السيارة حوالي 60 ميل لكل جالون بنزين بانحراف معياري 10ميل لكل جالون. وقام الباحثون باختبار جميع السيارات المنتجة حيث وجدوا أن متوسط المسافة بلغ 61 ميل/جالون هل هذا الفرق معنوي (حقيقي) مقارنة بالمتوسط الذي حددته الشركة ؟","الإجابة نعم بالطبع.","لماذا: لان الفرق مبني على الإحصاء الشامل لجميع السيارات ولا يوجد أخطاء معاينة يمكن أن يعزى لها هذا الفرق، وهذا يشير بشكل واضح أن متوسط المجتمع تغير من 60 ميل إلى 61 ميل."],"example":[],"source":"الشريحة 17","table":[]},{"title":"المعنوية الإحصائية والمعنوية العملية practical & statistical significance","body":["هل هذا الفرق معنوي من الناحية العملية (practical significance) ؟","إذا قرر خبراء السيارات أن ميل واحد فرق المسافة ليس له أهمية حقيقية نقول أن هذا الفرق ذات معنوية إحصائية ولكن غير معنوي من الناحية العملية."],"example":[],"source":"الشريحة 18","table":[]},{"title":"ماذا لو أخذنا عينة عشوائية 25 سيارة من السيارات التي أنتجتها الشركة ووجدنا متوسط المسافة = 64 ميل|جالون هل هذا الفرق معنوي إحصائيا","body":["الجواب: الأمر غير واضح ولا نستطيع التقرير لان لدينا احتمالين وهما:","أن الفرق معنوي إذا كان هناك سبب جوهري للاعتقاد بان متوسط المجتمع تغير لأعلى من 60 ميل | جالون.","أن الفرق غير معنوي وان هذا الفرق يعزى لأخطاء المعاينة العشوائية (random sampling error).","إذن مهمة الباحث هنا هي معرفة ما إذا كان هذا الفرق معنوي أم انه فرق ناجم عن أخطاء المعاينة ليس أكثر. وانجاز هذه المهمة يتم من خلال خطوات اختبار الفرضيات."],"example":[],"source":"الشريحة 19","table":[]},{"title":"ومفهوم مستوى المعنوية (the level of significance): مرتبط بمفهوم الخطأ من النوع الأول والخطأ من النوع الثاني كما يلي:","body":["1- الخطأ من النوع الأول (a type I error) :","يحدث عند رفض الفرضية الصفرية وهي في الحقيقة صحيحة (إدانة الشخص وهو بريء).","2- الخطأ من النوع الثاني (a type II error):","يحدث عند قبول الفرضية الصفرية وهي في الحقيقة خاطئة (تبرئة المتهم وهو في الحقيقة مذنب) .","الجدول التالي يوضح النوعين من الخطأ"],"example":[],"source":"الشريحة 20","table":[]},{"title":"ويرمز للخطأ من النوع الأول (الفا α):","body":["وتمثل القيمة القصوى لاحتمال ارتكاب هذا الخطأ وهي نفسها التي يشار إليها بمستوى الدلالة الإحصائية (the level of significance) وتعني كلمة (الدلالة) أن الفرق بين القيمة النظرية لمعلمة المجتمع والقيمة المحسوبة للإحصائي المناظر من العينة فرق حقيقي وكبير بحيث لا يعزى لأخطاء المعاينة العشوائية.","الفرضية الصفرية خاطئة | الفرضية الصفرية صحيحة | القرار","القرار صائب","(power of test probability = 1- β) | خطأ من النوع الأول","(significance level probability = α) | القرار رفض","خطأ من النوع الثاني","(power of test probability = β) | القرار صائب"],"example":["الخطأ الأول: رفض H0 وهي صحيحة؛ الثاني: عدم رفض H0 وهي خاطئة."],"source":"الشريحة 21","table":[]},{"title":"وقيمة مستوى الدلالة يحددها الباحث ولكن الشائع في الدراسات الاجتماعية أن تأخذ القيم (0.01، 0.05) ويعني مستوى الدلالة (α= 0.05) انه ","body":["أما الخطأ من النوع الثاني فيرمز له بالرمز (بيتا β):","وهي عبارة عن القيمة القصوى لاحتمال ارتكابه. وهذا الاحتمال لا يحدده الباحث بل يتم حسابه ويعتمد على خمسة عوامل وهي:","القيمة الحقيقية لمعلمة المجتمع.","قيمة (α) المختارة","نوع الاختبار (ذات ذيلين أو ذيل واحد).","الانحراف المعياري للعينة.","حجم العينة."],"example":[],"source":"الشريحة 22","table":[]},{"title":"والعلاقة بين النوعين من الخطأ (α، β) علاقة عكسية مع الأخذ بعين الاعتبار ما يلي:","body":["لأي قيمة معينة محددة لألفا (α) فان زيادة حجم العينة يؤدي إلى نقصان الخطأ من النوع الثاني (β).","عند ثبات حجم العينة عند مستوى معين فان تخفيض قيمة (α) يؤدي إلى زيادة قيمة (β) والعكس صحيح.","تخفيض كلا النوعين من الخطأ يمكن أن يتم من خلال زيادة حجم العينة. بالإضافة إلى تطبيق إجراءات سليمة للمعاينة واستخدام طرق صحيحة ودقيقة لجمع البيانات لان ذلك يقلل من أخطاء البيانات والأخطاء العشوائية."],"example":[],"source":"الشريحة 23","table":[]},{"title":"قوة الاختبار Power Of The Test:","body":["قوة الاختبار هي عبارة عن قدرة الاختبار على رفض الفرضية الصفرية عندما تكون في الحقيقة خاطئة وتساوي:","power of test = (1 – β)","والخطأ من النوع الأول (إدانة المتهم وهو برئ) أكثر خطورة من الخطأ من النوع الثاني (تبرئة المذنب) .","وبناءً على ما سبق بيانه من المصطلحات المستخدمة في اختبار الفرضيات يمكننا الآن حصر خطوات اختبار الفرضيات كما يلي:"],"example":[],"source":"الشريحة 24","table":[]}]},{"title":"خطوات القرار وقيمة p","steps":[{"title":"خطوات اختبار الفرضيات:","body":["يتم اختبار الفرضية الصفرية بإتباع عدة خطوات كما يلي:","1- تحديد الفرضية الصفرية والبديلة.","2- اختيار الاختبار الإحصائي الملائم (appropriate statistical test): ويوجد العديد من الاختبارات الإحصائية ولكن اختيار الاختبار المناسب يتم بناء على عدة معايير بحسب طبيعة البحث من هذه المعايير مثلاً:","طبيعة سحب العينة (عشوائي أو غير عشوائي)","طبيعة المجتمع (يتبع التوزيع الطبيعي أو لا)","نوع القياس (اسمي، رتبي، فتري، نسبي)","3- تحديد مستوى الدلالة الإحصائية المناسب بحسب مدى المخاطرة النسبية للخطأين (الأول والثاني) بالنسبة للباحث."],"example":[],"source":"الشريحة 25","table":[]},{"title":"4- حساب قيمة دالة الاختبار الإحصائي لاختبار الفرضية الصفرية بعد جمع البيانات من عينة الدراسة . وبافتراض أن هذه الفرضية صحيحة يحدد ","body":["تحديد القيم الحرجة (critical test value): والتي بناء عليها يتم تحديد منطقة الرفض (region of rejection) ومنطقة القبول (region of acceptance) للفرضية الصفرية .","5- اتخاذ القرار: من خلال مقارنة القيمة المحسوبة (calculated value) من دالة الاختبار الإحصائي مع القيمة الجدولية أو الحرجة (critical value) عند مستوى الدلالة المحدد مسبقا. فإذا كانت القيمة المحسوبة اكبر من القيمة الجدولية يتم رفض الفرضية الصفرية أما إذا كانت اقل فيتم قبولها كما سبقت الإشارة إليه. مع الأخذ بعين الاعتبار هل الاختبار من طرف واحد أو من طرفين بحسب الفرضية البديلة (H1)."],"example":[],"source":"الشريحة 26","table":[]},{"title":"منطقة الرفض rejection region أو المنطقة الحرجة critical region: هي تلك المنطقة الذي إذا وقعت فيها قيمة دالة الاختبار الإحصائي فانه","body":["القيم الحرجة Critical Value: يتم تحديدها بناء على قيمة (α) وعلى نوع توزيع المعاينة لدالة الاختبار (the sampling distribution) وهي التي تحدد كلاً من منطقة رفض الفرضية الصفرية ومنطقة قبولها.","كما سبقت الإشارة إليه فان الفرضية البديلة لها ثلاث حالات (≠ ، <، >). وبحسب هذه الحالات هناك ثلاث أنواع اختبارات وهي:","Two-tailed test: اختبار ذات الذيلين أو الطرفين","Right (upper) -tailed test: اختبار ذات الذيل الأعلى أو الأيمن","Left (lower) -tailed test: اختبار ذات الذيل الأسفل أو الأيسر","والأشكال التالية توضح كيفية تحديد هذه الاختبارات:"],"example":[],"source":"الشريحة 27","table":[]},{"title":"تفسير قيمة p-value","body":["يمكن تفسير قيمة (p-value or sig-value) كما يلي:","إذا كانت قيمة (p-value < 0.01) فان هناك دليل كاسح على صحة الفرضية البديلة وخطأ الفرضية الصفرية وهنا يقال أن النتيجة معنوية بدرجة مرتفعة ( highly significance).","إذا كانت قيمة ( 0.01 < p-value < 0.05) فان هناك دليل قوي على صحة الفرضية البديلة وخطأ الفرضية الصفرية وهنا يقال أن النتيجة معنوية (significance).","إذا كانت قيمة ( 0.05 < p-value < 0.10) فان هناك دليل ضعيف على صحة الفرضية البديلة وخطأ الفرضية الصفرية وهنا يقال أن النتيجة غير معنوية (insignificance).","إذا كانت قيمة (p-value > 0.10) فانه لا يوجد دليل على صحة الفرضية البديلة وخطأ الفرضية الصفرية."],"example":["p-value ليست احتمال صحة الفرضية الصفرية؛ هي احتمال نتيجة مساوية أو أشد تطرفًا بافتراض H0 وشروط النموذج."],"source":"الشريحة 31","table":[]},{"title":"حدد نوع الاختبار في الحالات التالية من حيث كونه: (right – tailed test، left – tailed test، two– tailed test)","body":["ثم اوجد قيمة (p-value) ومن ثم حدد استنتاجك حول اختبار الفرضية الصفرية (H0).","استخدم مستوى الدلالة ( 0.05 = α) لاختبار الادعاء بأن نسبة التالف في الإنتاج اكبر من 25% (P > 0.25). وقد بينت نتائج عينة أخذت من الإنتاج أن احصاءة الاختبار (1.18(Z = .","استخدم مستوى الدلالة ( 0.05 = α) لاختبار الادعاء بأن نسبة التالف في الإنتاج لا يساوي 25% (P ≠ 0.25). وقد بينت نتائج عينة أخذت من الإنتاج أن احصاءة الاختبار (2.34(Z = ."],"example":[],"source":"الشريحة 32","table":[]},{"title":"حل الحالة الأولى: استخدم مستوى الدلالة ( 0.05 = α) لاختبار الادعاء بأن نسبة التالف في الإنتاج اكبر من 25% (P > 0.25). وقد بينت نتا","body":["حيث أن الفرضية (P > 0.25) تعتبر فرضية بديلة إذن الاختبار هنا هو اختبار الذيل الأعلى أو الأيمن (right – tailed test). ووفقاً للشكل السابق (7-6) فان قيمة (p-value) تساوي المساحة التي على يمين قيمة احصاءة الاختبار (1.18(Z = ، وهذه المساحة نستطيع استخراجها من جدول التوزيع الطبيعي المعياري والتي تساوي (0.1190). وبناء عليه نقارن هذه القيمة بقيمة مستوى الدلالة ( 0.05 = α) نلاحظ أنها اكبر منها وبالتالي لا نستطيع رفض الفرضية الصفرية."],"example":[],"source":"الشريحة 33","table":[]},{"title":"حل الحالة الثانية: استخدم مستوى الدلالة ( 0.05 = α) لاختبار الادعاء بأن نسبة التالف في الإنتاج لا يساوي 25% (P ≠ 0.25). وقد بينت ن","body":["حيث أن الفرضية (P ≠ 0.25) تعتبر فرضية بديلة إذن الاختبار هنا هو اختبار الذيلين (two– tailed test). وحيث ان قيمة احصاءة الاختبار (2.34(Z = تقع على يمين المركز (متوسط التوزيع) ووفقاً للشكل السابق (7-6) فان قيمة (p-value) تساوي ضعف المساحة التي على يمين قيمة z، وهذه المساحة نستطيع استخراجها من جدول التوزيع الطبيعي المعياري والتي تساوي (0.0096). وبناء عليه فان قيمة (p-value) تساوي (0.0096 = 0.0192 2 x) نقارن هذه القيمة بقيمة مستوى الدلالة ( 0.05 = α) نلاحظ أنها اقل منها وبالتالي نرفض الفرضية الصفرية."],"example":[],"source":"الشريحة 34","table":[]},{"title":"صيغة نتيجة اختبار الفرضية الصفرية","body":["هناك عدة صياغات تستخدم في البحوث والرسائل لنتائج اختبار الفرضيات الصفرية من هذه الصياغات:","(نقبل الفرضية الصفرية: accept the null hypothesis)","(لا نستطيع إثبات الفرضية الصفرية: we are not proving the null hypothesis).","(بيانات العينة لا تعطي دليل كافي وقوي لرفض الفرضية الصفرية: the sample evidence is not strong enough to warrant rejection )"],"example":[],"source":"الشريحة 35","table":[]}]},{"title":"اختيار الاختبار الإحصائي","steps":[{"title":"الاستدلال الإحصائي للعينات (مستويات اختبار الفرضيات)","body":["لوصف مجتمع (عينة) واحدة","لمقارنة مجتمعين","لمقارنة أكثر من مجتمعين","لتحليل العلاقة بين متغيرين","لتحليل العلاقة بين أكثر من متغيرين"],"example":[],"source":"الشريحة 36","table":[]},{"title":"أولا: الاختبارات المعلمية Parametric Tests","body":["الاختبارات حول: عينة واحدة وعينتين وأكثر من عينتين"],"example":[],"source":"الشريحة 37","table":[]},{"title":"مقارنة الطرق المعلمية بالطرق غير المعلمية","body":["الأساليب الإحصائية الاستدلالية تصنف إلى اختبارات بارامترية parametric tests واختبارات لامعلمية nonparametric tests.","والاختبارات المعلمية: هي تلك الأساليب التي تتطلب الاستيفاء بافتراضات أو شروط معينة حول المجتمع الذي تسحب منه عينة البحث واهم هذه الشروط هي: شرط اعتدالية التوزيع normality وشرط تجانس التباين.","الاختبارات اللامعلمية: فهي لا تضع أية افتراضات حول المجتمع الذي تسحب من العينة.","فيما يلي جدول يوضح مقارنة الطرق المعلمية بالطرق اللامعلمية:"],"example":[],"source":"الشريحة 38","table":[]},{"title":"الطرق اللامعلمية","body":["nonparametric tests | الطرق المعلمية","parametric tests | الرقم","تصلح للعينات الكبيرة والصغيرة (مثلا اذا كان حجم العينة 6 او اقل فلا بديل عن استخدام الاختبارات اللامعلمية | تصلح للعينات الكبيرة بشكل اساسي | 1","لا يشترط افتراضات او معلومات حول توزيع المجتمع | يشترط توفر معلومات عن توزيع المجتمع | 2","تستخدم في حالة التوزيعات الحرة غير المقيدة | تستخدم في التوزيعات المقيدة بالاعتدالية | 3","تناسب البيانات الاسمية nominal والرتبية ordinal كما يمكن استخدامها في حالة البيانات الفترية والنسبية | تناسب البيانات الفترية interval والنسبية ratio | 4","لا تشترط تجانس التباين | تشترط تجانس التباين في المجتمعات التي تسحب منها العينات | 5"],"example":["يتحدد الاختبار بناءً على طبيعة البيانات والافتراضات وتصميم العينة، لا على تصنيف المعلمي واللامعلمي وحده."],"source":"الشريحة 39","table":[]},{"title":"اختبار الفرضيات المتعلقة بمجتمع واحد","body":["إن الفرضية الصفرية في هذه الحالة هي عبارة عن تقدير لمعلمة المجتمع، ومن ثم يتم اختبار هذه الفرضية من خلال مقارنة الاحصاءة المناظرة للمعلمة والتي يتم حسابها من العينة، وهنا يطرح تساؤل حول مدى تمثيل العينة للمجتمع المسحوبة منه أي مدى انتماء العينة للمجتمع الذي سحبت منه العينة، ومن المعروف أن إحصائي العينة ليس بالضرورة أن يساوي معلمة المجتمع حيث انه إحصائيا قد يكون هناك فرق بين الإحصائي والمعلمة سواء بالزيادة أو النقصان وهذا الفرق يمكن تجاهله إحصائيا إذا كان فرقا ظاهريا وليس حقيقيا أو جوهريا وبالتالي ليس له خطورة على مدى تمثيل العينة للمجتمع. وفي هذه الحالة يمكن اعتبار متوسط العينة لا يختلف إحصائيا عن متوسط المجتمع وان العينة المسحوبة فعلا تمثل المجتمع وفي هذه الحالة نعتبر (µ= x).","وفي بعض الحالات لا يمكن أن نتجاهل هذا الفرق ونعتبره فرق حقيقي أو جوهري (معنوي) ومسالة تحديد ما إذا كان الفرق معنوي أو غير معنوي ليست متروكة للتقدير الشخصي للباحث ولكن تبنى اعتمادا على الخصائص الأساسية للتوزيع العيني للمتوسطات"],"example":[],"source":"الشريحة 40","table":[]},{"title":"مثال1 عملي بالتطبيق على SPSS","body":["البيانات التالية (ملف رقم 1) تمثل درجات عينة من 20 طالب في مساق الإحصاء بكلية التجارة بالجامعة الإسلامية والمطلوب هو اختبار ما إذا كان متوسط درجات الطلاب تساوي 65 درجة أم لا عند مستوى دلالة (α= 0.05).","H0: µ = 65","H1: µ ≠ 65","النتيجة حيث أن قيمة sig المحسوبة (0.02) >0.05 إذن فهي معنوية إحصائيا ونستنتج رفض الفرضية الصفرية بان المتوسط يساوي 65 درجة."],"example":[],"source":"الشريحة 41","table":[]},{"title":"اختبار الفرضيات حول الفرق بين وسطين hypothesis testing regarding the difference between two means","body":["هناك الكثير من المواقف التي نرغب فيها بإجراء مقارنة بين مجتمعين. مثلا المقارنة بين أداء الذكور وأداء الإناث.","هناك نوعين من البيانات في هذه الحالة: وهما البيانات المستقلة independent والبيانات المرتبطة أو غير المستقلة dependent حيث أن لكل منهما أسلوبه الخاص في التحليل الإحصائي."],"example":[],"source":"الشريحة 43","table":[]},{"title":"أولاً: اختبار الفرضيات حول الفرق بين وسطين لعينتين مستقلتين two independent samples t-test","body":["يقصد بالبيانات المستقلة تلك البيانات التي لا يوجد فيما بينها ارتباط ومن الأمثلة على ذلك:","أداء مجموعة من الذكور وأداء مجموعة من الإناث.","حجم الإنتاج في الفرع الأول وحجم الإنتاج في الفرع الثاني لمؤسسة صناعية.","وبالتالي فان وسط العينة الأولى في المثالين السابقين (وسط الذكور، ووسط حجم الإنتاج في الفرع الأول) مستقل عن وسط العينة الثانية (وسط الإناث، ووسط الانتاج في الفرع الثاني).","والفرضيات تكون على الشكل التالي:","Ho: μ1= μ2","H1: μ1≠μ2 or,"],"example":[],"source":"الشريحة 44","table":[]},{"title":"وعندما تكون الفرضية الصفرية صحيحة فان توزيع المعاينة لفروق الأوساط يتخذ شكل توزيع t بدرجات حرية (n1+n2 -2) حيث أن: n1 تمثل حجم الع","body":["1- التوزيع الطبيعي Normality: وهذا الافتراض يفترض أن العينة الأولى عينة عشوائية مسحوبة من المجتمع الأول يتبع التوزيع الطبيعي بوسط وانحراف معياري: N(µ1, σ1)، كذلك العينة الثانية عينة عشوائية مسحوبة من المجتمع الثاني يتبع التوزيع الطبيعي بوسط وانحراف معياري كما يلي: N(µ2, σ2).","2- تجانس التباين في المجتمعين homogeneity: هذا الافتراض يفترض تساوي التباين في كلا المجتمعين أي أن: σ22 =σ21","3- الاستقلالية independence: وهذا الافتراض يفترض أن مشاهدات العينة الأولى قد تم الحصول عليها عشوائيا من المجتمع الأول بشكل مستقل عن مشاهدات العينة الثانية المسحوبة من المجتمع الثاني."],"example":[],"source":"الشريحة 45","table":[]},{"title":"مثال2 عملي بالتطبيق على SPSS","body":["البيانات المرفقة في ملف 2 تمثل درجات مجموعتين من الطلبة في مساق الإحصاء الأولى مكونة من 59 طالب والثانية مكونة من 28 طالبة.","هل تعتقد بوجود فرق معنوي بين مستوى الطلبة في المجموعتين عند مستوى دلالة (0.05) ؟.","Ho: μ1= μ2","H1: μ1≠μ2","النتيجة حيث أن قيمة sig المحسوبة للفرق بين الوسطين (0.767) <0.05 إذن فهي غير معنوية إحصائيا ونستنتج عدم رفض الفرضية الصفرية بان متوسط درجات الطلاب يساوي متوسط درجات الطالبات."],"example":[],"source":"الشريحة 46","table":[]},{"title":"ثانياً: اختبار الفرضيات حول الفرق بين وسطين للعينات المرتبطة two paired sample t-test","body":["يقصد بالبيانات المرتبطة: تلك التي يوجد فيما بينها ارتباط وينشأ هذا الارتباط عندما يجرى الاختبار على المجموعة نفسها مرتين كاختبار قبلي واختبار بعدي أي أن البيانات تكون على شكل أزواج وبالتالي لابد أن يتساوى حجم العينتين أي أن: n1=n2 في العينات المرتبطة."],"example":[],"source":"الشريحة 48","table":[]},{"title":"مثال3 عملي بالتطبيق على SPSS","body":["البيانات المرفقة في الملف 3 تمثل نتائج تجربة أجريت على 20 شخص لاختبار مدى فعالية نظام غذائي خاص لتخفيف الوزن حيث تم قياس أوزان هؤلاء الأشخاص قبل البدء بتطبيق هذا النظام وقياس أوزانهم بعد مرور 3 شهور من بدء تطبيق النظام.","هل تستطيع أن تستنتج أن نظام الغذاء كان فعالاً في تخفيف الوزن عند مستوى دلالة (0.05)؟.","Ho: μbefore = μafter","H1: μbefore > μafter","من خلال النتائج يتضح أن قيمة (p-value or sig) تساوي sig/2 في هذه الحالة وتساوي صفر وهي اقل من (0.05) وبالتالي نرفض الفرضية الصفرية ونستنتج أن النظام الغذائي كان فعالاً."],"example":[],"source":"الشريحة 49","table":[]},{"title":"تحليل التباين الأحادي يركز على دراسة تأثير عامل واحد له عدة مستويات وعند كل مستوى تكرر التجربة عدد من المرات.","body":["مثال: اختبار ما إذا كان هناك فروق بين ثلاثة أساليب للإنتاج ويكون المطلوب هو معرفة ما إذا كانت هذه الأساليب الثلاثة لها تأثيرات متساوية على حجم الإنتاج أم لا.","وبالتالي فالانحراف الكلي المشاهد ينقسم لمركبتين:","الأولى ناتجة عن تأثير العامل (factor or treatment) (أسلوب الإنتاج)","الثانية ناتجة عن الخطأ التجريبي.","تحليل التباين Analysis Of VAriance ANOVA"],"example":[],"source":"الشريحة 51","table":[]},{"title":"مثال4 عملي بالتطبيق على SPSS","body":["ملف البيانات 4 عبارة عن درجات مجموعة من الطلبة تم تدريسهم مساق الرياضيات بثلاثة طرق مختلفة وهي: M1، M2، M3، هل هناك فرق بين الطرق التدريس الثلاثة في تحصيل الطلاب ؟ عند مستوى دلالة (0.05)","H0: μ1= μ2= μ3","H1: At least one mean is different","من خلال النتائج يلاحظ أن قيمة F معنوية إحصائيا (sig = 0.014) وهي اقل من 0.05 وبالتالي نرفض الفرضية الصفرية ولمعرفة أي طرق التدريس التي كانت أفضل يتم استخدام اختبار بنفروني او شيفيه من post-hoc كما يلي:","يلاحظ أن الفرق كان بين الطريقة الثانية والثالثة حيث أن قيمة Sig بلغت 0.018 وهي معنوية ويتضح أن الطريقة الثالثة في التدريس هي الأفضل (وضح لماذا )"],"example":[],"source":"الشريحة 52","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"أي رمز يُستخدم للفرضية الصفرية؟","options":["H0","H1","β","p"],"correct":0,"explain":"تُرمز الفرضية الصفرية بـ H0."},{"num":2,"kind":"mc","question":"ما القرار الصحيح عندما تكون p=0.03 وα=0.05 بافتراض تحقق شروط الاختبار؟","options":["عدم رفض H0","رفض H0","إثبات H1 يقينًا","لا يمكن المقارنة"],"correct":1,"explain":"0.03 أصغر من 0.05، فتُرفض H0 وفق مستوى الدلالة المحدد."},{"num":3,"kind":"mc","question":"أي اختبار يناسب H1: μ ≠ 20؟","options":["ذيل أيمن","ذيل أيسر","ذيلان","اختبار وصفي فقط"],"correct":2,"explain":"وجود ≠ يحدد اختبارًا ثنائي الطرف."},{"num":4,"kind":"mc","question":"أي فرضية بديلة تحدد الاختبار الأيمن؟","options":["μ < 5","μ = 5","μ ≠ 5","μ > 5"],"correct":3,"explain":"إشارة > تشير إلى اختبار الطرف الأيمن."},{"num":5,"kind":"mc","question":"أي حدث يمثل خطأ النوع الأول؟","options":["عدم رفض H0 صحيحة","رفض H0 صحيحة","رفض H0 خاطئة","عدم رفض H0 خاطئة"],"correct":1,"explain":"النوع الأول هو رفض الفرضية الصفرية عندما تكون صحيحة."},{"num":6,"kind":"mc","question":"ما قوة الاختبار الإحصائي؟","options":["α","β","1−β","1−α"],"correct":2,"explain":"قوة الاختبار هي احتمال رفض H0 عندما تكون خاطئة، وتساوي 1−β."},{"num":7,"kind":"mc","question":"إذا كانت z=1.18 في اختبار أيمن، فما قيمة p التقريبية؟","options":["0.1190","0.2380","0.0192","0.5000"],"correct":0,"explain":"تُذكر في العرض مساحة الطرف الأيمن عند z=1.18 بنحو 0.1190."},{"num":8,"kind":"mc","question":"إذا كانت z=2.34 في اختبار ثنائي الطرف، فما قيمة p التقريبية؟","options":["0.0096","0.0192","0.0960","0.2000"],"correct":1,"explain":"نضاعف مساحة الطرف الواحد 0.0096 فنحصل على 0.0192."},{"num":9,"kind":"mc","question":"أي اختبار يشيع لمقارنة متوسط مجموعتين مستقلتين مع تحقق الافتراضات؟","options":["t مستقلتين","t زوجي","تحليل تباين لمجموعة واحدة","ارتباط رتبي فقط"],"correct":0,"explain":"اختبار t لعينتين مستقلتين يقارن متوسطَي مجموعتين منفصلتين."},{"num":10,"kind":"mc","question":"ما النوع المناسب لمقارنة قياسات الأشخاص أنفسهم قبل وبعد؟","options":["t مستقلتين","t مرتبطتين","كاي تربيع للتجانس فقط","تحليل وصفي فقط"],"correct":1,"explain":"القياسان مرتبطان لأنهما للشخص نفسه."},{"num":11,"kind":"mc","question":"ما الاستخدام الأساسي لتحليل التباين الأحادي ANOVA؟","options":["مقارنة متوسط مجموعتين مرتبطتين فقط","مقارنة متوسطات ثلاث مجموعات أو أكثر وفق الشروط","حساب حجم العينة فقط","ترميز الاستبيان"],"correct":1,"explain":"تحليل التباين الأحادي يفحص فروق متوسطات مستويات عامل واحد."},{"num":12,"kind":"tf","question":"عدم رفض H0 يعني إثبات أنها صحيحة بنسبة 100%.","options":["صح","خطأ"],"correct":false,"explain":"عدم الرفض يعني عدم كفاية الأدلة ضد الفرضية وفق الاختبار، وليس إثبات صحتها."},{"num":13,"kind":"tf","question":"المعنوية الإحصائية لا تعني بالضرورة أن الأثر مهم عمليًا.","options":["صح","خطأ"],"correct":true,"explain":"قد يكون فرق صغير مهمًا إحصائيًا لكن أثره العملي محدود."},{"num":14,"kind":"short","question":"وضح الفرق بين الخطأين الأول والثاني.","options":[],"answer":"الأول رفض H0 وهي صحيحة (احتماله α). والثاني عدم رفض H0 وهي خاطئة (احتماله β)."},{"num":15,"kind":"short","question":"ما معنى قيمة p من الناحية الإحصائية؟","options":[],"answer":"احتمال ملاحظة إحصاء اختبار مساوٍ أو أشد تطرفًا من المشاهد بافتراض صحة H0 وشروط الاختبار. ليست احتمال صحة H0."}]},{"id":11,"kind":"workshop","title":"ورشة كتابة تقرير البحث","source":"العرض -تقرير البحث.ppt — محاضرة مستقلة دون رقم","units":[{"title":"المفهوم واللغة وأجزاء التقرير","steps":[{"title":"محاضرة: كتاربة تقرير البحث","body":["أولا: لغة البحث وأسلوبه.ِ","ثانيا: استخدام علامات الترقيم والأقواس","ثالثا: أقسام البحث وعناوينه الرئيسية والفرعية.","رابعا: الشكل المادي والفني للبحث.","خامسا: مناقشة البحث.","سادساً: مثال لــ:منهجية الجامعات..... في كتابة الرسائل العلمية."],"example":[],"source":"الشريحة 1","table":[]},{"title":"كتابة الشكل النهائي للبحث","body":["المقصود بتقرير البحث والغرض منه","يطلق على هذه المراحل من البحث \"كتابة تقرير البحث\"","حيث يقوم الباحث بمراجعة وافية ودقيقة لمسودات البحث التي جمعها وحللها ودونها","الغرض من تقرير البحث","التأكد من دقة وسلامة المعلومات الواردة في البحث علميا وموضوعيا","التأكد من دقة وسلامة استخدام المصطلحات العلمية والفنية المتخصصة في مجال البحث","توثيق المصادر والمعلومات بصورة علمية أكاديمية"],"example":[],"source":"الشريحة 2","table":[]},{"title":"تكون الرسالة العلمية مقبولة إذا توافرت فيها شروط عدة، منها ما يلي:","body":["1- أن تعالج مشكلة أو ظاهرة لها أهميتها من وجهة النظر العلمية أو التطبيقية أو الاقتصادية.","2- أن تقوم على منهج علمي سليم.","3- أن تراعي فيها النواحي الموضوعية والشكلية","من أجل كتابة تقرير بحث بصورة جيدة، يحتاج الباحث إلى:","1- القراءات الواسعة, و الاطلاع المستمر في موضوع الرسالة والاعتماد على المصادر الحديثة.","2- الالتزام بعنوان الرسالة، والحرص على احتوائه على ما هو وثيق الصلة بالموضوع فقط.","3- التعرف على آراء الغير، وفهمها فهماً صحيحاً، مع الدقة و الأمانة في نقل هذه الآراء، وتقييمها وليس مجرد سردها."],"example":[],"source":"الشريحة 3","table":[]},{"title":"1- لغة البحث وأسلوبه:","body":["1- لغة البحث المفهومة و الفعالة:","يجب على الباحث أن يعبر عن أفكاره في البحث بجمل بسيطة وموجزةو","أن يتجنب الإسهاب إلا إذا كان لغرض التأكيد على نقطة معينة و","أن استخدام المصطلحات العلمية بشكل دقيق ومفهوم.","2- استخدام الجمل و التعابير الدقيقة","يتجنب الحشو والعبارات الرنانة التي لا يجب استخدامها في البحث العلمي.","3- استخدام الجمل والتراكيب المناسبة والذي يجعل الباحث أكثر وضوحا"],"example":["اكتب جملًا واضحة ومحددة وتجنب الألفاظ الملتبسة والحشو."],"source":"الشريحة 4","table":[]},{"title":"2- استخدام علامات الترقيم والأقواس","body":["الفاصلة (،):","تمثل الفاصلة مقاطع قصيرة لاستمرارية الحديث والكتابة.","تستخدم الفاصلة بين سلسلة الأسماء والعبارات يكون عددها ثلاثة أو أكثر معينة بنفس المفهوم ومثال ذلك (ومن أهم المحافظات: الشمال، وغزة، والوسطى، والجنوب )","تستخدم الفاصلة للفصل بين العبارات كمثل عنوان إقامة شخص، ومحل عمله أو ما شابه ذلك.","تستخدم الفاصلة مع إشارات أخرى للفصل بين البيانات الببليوغرافية الخاصة بالكتاب والمقالات العلمية ومصادر المعلومات لأخرى.","الشرطة (-):","تستخدم عادة عند استخدام عبارة أو كلمة اعتراضية توضيحه. مثال: معظم الجامعات السعودية – إن لم تكن كلها – مهتمة بإدخال الحاسب في الإجراءات التوثيقية لمكتباتها."],"example":[],"source":"الشريحة 5","table":[]},{"title":"2- استخدام علامات الترقيم والأقواس","body":["القوسين الصغيرين ” ”:","يكونان في بداية ونهاية الحديث أو النص ويسميها بعض الكتاب ”أداة التنصيص\"","وتستخدم هذه الأقواس للدلالة على اقتباس معلومات ونصوص حرفيا نظرا لأهميتها أو أهمية كاتبها","قد تستخدم مثل هذه الأقواس لحصر عبارة معينة مثل مصطلح أو مفهوم خاص ويفضل أن تكتب مثل هذه الأقواس في بداية أو نهاية الحديث بشكل مرتفعة عن باقي الكتابة العادية.","الأقواس الاعتيادية ( ):","تستخدم عند ورود عبارة باللغة العربية الفصحى ولها ما يعادلها من العبارات الأجنبية العربية مثل: استخدام الحاسب (الكمبيوتر).","قد تستخدم الأقواس الاعتيادية لتوضيح عبارة بديلة أخرى ويشترط أن تكون أجنبية مثل : سكان المدن (الحضر)"],"example":[],"source":"الشريحة 6","table":[]},{"title":"3- أقسام البحث وعناوينه الرئيسية والفرعية:","body":["الصفحات التمهيدية.","صفحة العنوان:","صفحة لكتابة أسماء الأساتذة المشرفين والمناقشة (في الرسائل العلمية)","صفحة الإهداء.","صفحة الشكر والتقدير.","قوائم المحتويات و الجداول و الأشكال :","قائمة المحتويات (فهرس البحث)"],"example":[],"source":"الشريحة 7","table":[]},{"title":"المتن أو النص (صميم المادة):","body":["الفصل الأول: مقدمة البحث وتشمل على الجوانب التالية:","الدوافع التي تدفع الباحث على اختيار موضوع البحث ومشكلة البحث","أهداف البحث. - أهمية البحث.","منهج البحث وأدوات جمع المعلومات. - فرضيات البحث.","حدود البحث. - التعريف بالمصطلحات والمختصرات عند اللزوم.","الفصل الثاني: مراجعة الأدبيات ويضم هذا الفصل العناصر التالية:","- بيان الإطار النظري للدراسة."],"example":["رتب متن الرسالة منطقيًا من المقدمة، ثم الدراسات السابقة، فالمنهجية، فالنتائج، ثم التوصيات."],"source":"الشريحة 8","table":[]},{"title":"وينبغي توافر مجموعة من المواصفات في متن البحث:","body":["تشخيص الجوانب التي توصل إليها الباحث بشكل واضح عن طريق المنهج الذي اتبعه والأداة التي جمع بها المعلومات ويجب عدم ذكر أي استنتاجات لا تستند على هذا الأساس.","الابتعاد عن المجاملة والتحيز في ذكر الاستنتاجات واعتماد الموضوعية في طرح السلبيات والإيجابيات.","أن يتم سرد الاستنتاجات في تسلسل منطقي\"ان تكون لها علاقة بمشكلة وموضوع البحث ولا تخرج من هذا النطاق\""],"example":[],"source":"الشريحة 9","table":[]},{"title":"التوصيات (المقترحة):","body":["تمثل التوصيات النقاط والجوانب التي يرى الباحث ضرورة سردها في ضوء الاستنتاجات التي توصل إليها ويجب على الباحث الأخذ في الاعتبار عند ذكره للتوصيات عدة أمور هي:","أن تستند التوصيات على استنتاج أو أكثر خرج به الباحث وذكره في الجزء الخاص بالاستنتاجات ولا يشترط وجود توصية لكل نتيجة خرج بها الباحث.","ينبغي أن تكون التوصية والمقترحات مقبولة وقابلة للتنفيذ أي ضمن الإمكانيات المتاحة حاليا أو التي يمكن أن تتاح مستقبلا.","الابتعاد عن منطق العمومية في التوصيات – وينطبق ذلك على الاستنتاجات – لأنه يجب على الباحث أن يكون محددا وواضحا في توصياته فيجب الابتعاد عن القول ((يقترح الباحث زيادة عدد العاملين في القسم )) بل ينبغي أن يحدد العدد المطلوب ومبررات هذا العدد بالحقائق والأرقام.","قائمة المراجع والملاحق","أ- قائمة المراجع:","عبارة عن قائمة تضم المراجع (References ) التي تم الرجوع إليها في متن الرسالة، مرتبة أبجديا حسب اسم المؤلف أو رقميا حسب اماكن الظهور."],"example":["كل توصية مهمة ينبغي أن تكون قابلة للتنفيذ ومسنودة بنتيجة محددة."],"source":"الشريحة 10","table":[]}]},{"title":"التنسيق والتوصيات والمناقشة","steps":[{"title":"4- الشكل المادي والفني للبحث","body":["1) حجم البحث وعدد صفحاته.","2) الورق الجيد والموحد شكلا ونوعية.","3) الطباعة الواضحة والكتابة الخالية من الأخطاء المطبعية.","4) الحواشي والهوامش من حيث تنظيمها وتنسيقها بشكل واحد وبطريقة تميزها عن المعلومات الموجودة في النص سواء من ناحية الفراغات بين الأسطر أو وجود خطوط فاصلة بينها وبين المتن.","5) العناوين, حيث يجب التمييز بين العناوين المختلفة للبحث أو الرسالة من ناحية حجم الكتابة أو الطباعة أو لونها، ودرجة اللون ويجب أن تكون عناوين الفصول في الوسط صفحة مستقلة عناوين المباحث في وسط الصفحة الاعتيادية ثم العناوين الثانوية التابعة لها تكون معلق في بداية السطر وتحتها خط.","6) الترقيم ووضع الإشارات، حيث يجب التأكد من ترقيم صفحات البحث أو الرسالة وفي مكان ثابت وموحد وأيضا الأرقام الخاصة بأقسام البحث الرئيسية والثانوية أو حروف الهجاء بجانب الأرقام يجب استخدام الأرقام والإشارة في أماكنها المطلوبة والصحيحة في البحث.","7) الرسومات والخرائط والمخططات حيث يجب الاعتناء بها وان تظهر في شكل واضح وموحد وأنيق."],"example":[],"source":"الشريحة 11","table":[]},{"title":"التوازن في تقسيم الرسالة:: يقصد بالتوازن في الرسائل العلمية مراعاة ما يلي:","body":["التوازن في التقسيم الداخلي للفصول من حيث عدد المباحث في كل فصل. فلا ينبغي أن يحتوي فصل على مبحثين وفصل آخر على خمسة مباحث مثلاً.","التوازن في عدد صفحات كل فصل، فلا ينبغي أن يحتوي فصل ما على عشر صفحات وفصل على خمسين صفحة، إنما يفضل أن يكون عدد الصفحات متوازن، وليس بالضرورة أن يكون نفس العدد.","التوازن في تسلسل العناوين الرئيسية والفرعية والتفريعات"],"example":[],"source":"الشريحة 12","table":[]},{"title":"5- مناقشة البحوث","body":["مناقشة البحوث عادة ما تكون في مجالات عدة وعلى مستويات عدة أهمها:","أ- مناقشة الرسائل العلمية (دبلوم، ماجستير، دكتوراه)","ب- حلقات البحث وما يسمى بالسمينار","جـ- الندوات والمؤتمرات العلمية","وعلى الباحث الناجح أن يهيئ نفسه للمناقشة والنقد بالشكل يؤدي إلى حسن العرض وجودة المناقشة والإجابة على الأسئلة والاستفسارات.","ويوجد عدد من الجوانب الأساسية التي يجب أن ينتبه إليها الباحث في نقاشه ودفاعه عن بحثه أهمها:","تنظيم خلاصة البحث أو ملخص الرسالة وتوزيعها على المعنيين بالمناقشة."],"example":[],"source":"الشريحة 13","table":[]},{"title":"لا بد من التقيد بالأمور التالية في كتابة الرسائل الجامعية:","body":["أولاً: الإطار العام:","تطبع الرسالة على ورق أبيض (A4) بشكل واضح وعلى وجه واحد.","كتابة الرسالة بلغة واضحة والتأكد من خلو الرسالة من الشطب والأخطاء النحوية والإملائية والمطبعية قبل تسليمها للجنة المناقشة.","إرفاق ملخص للرسالة تتراوح عدد كلماته (200-600) كلمة.","4) تبدأ الجملة بكلمة ولا يجوز أن تكون رقماً أو اختصارا أو رمزاً، ومثال ذلك:","5) عناوين الرسالة الرئيسية وبداية كل فصل تكون في صفحات جديدة.","6) تقليل الاختصارات ما أمكن وتكتب لأول مرة كاملة ويوضع الاختصار بين هلالين بجانبها.ويكتب الاختصار بعد ذلك بدون هلالين."],"example":[],"source":"الشريحة 14","table":[]},{"title":"ثانياً: الخط والمسافات والهوامش يجب مراعاة ما يلي بخصوص هذا البند باعتبار لغة الرسالة:","body":["ملاحظات | أين يكتب؟ | اللغة الإنجليزية | اللغة العربية |","يجوز تصغيره داخل الجدول | متن الرسالة | 12 | 14 | حجم الحرف","يجوز تصغيره في المعادلات الطويلة | كتابة المعادلات في متن الرسالة | 12 | 12 |","| العناوين الرئيسية | 14 عريض | 16 عريض |","| العناوين الفرعية | 13 | 15 |","| الحواشي | 10 | 12 |","| متن الرسالة | Times New Roman | Simplified Arabic | نوع الخط"],"example":["الأحجام والهوامش المذكورة في الشرائح نموذج تنظيمي لإحدى الجامعات وليست قاعدة موحدة لكل الجامعات."],"source":"الشريحة 15","table":[]},{"title":"ثالثاً:الجداول والأشكال","body":["تظهر بعد ذكرها مباشرة سواء في المتن أو النتائج والمناقشة، ولا توضع في آخر الرسالة.","يتم توسيط عنوان الجدول أو الشكل وسط الصفحة.","ترقم الجداول/الأشكال تسلسلياً لكل فصل على حدة مع ذكر رقم الفصل الذي يقع فيه الجدول كما هو موضح:","شكل (1.1) الشكل الأول في الفصل الأول | جدول (1.1) الجدول الأول في الفصل الأول","شكل (1.1) الشكل الثاني في الفصل الأول | جدول (1.2) الجدول الثاني في الفصل الأول","شكل (1.1) الشكل الثالث في الفصل الأول | جدول (1.3) الجدول الثالث في الفصل الأول","4) يكتب عنوان الجدول في أعلاه، وأن يكون معبراً عن محتواه."],"example":[],"source":"الشريحة 16","table":[]},{"title":"رابعاً:ترقيم الصفحات","body":["1) الصفحات التمهيدية (الملخص, الإهداء, شكر، الفهرس,...الخ) يتم ترقيمها بالأحرف العربية الأبجدية(أ,ب,ج..) بالنسبة للرسائل العربية والأرقام الرومانية (i,ii,…. أو a,b,…..) بالنسبة للرسائل الإنجليزية.","2) يبدأ الترقيم من صفحة المقدمة في الرسالة وتحمل رقم 1.","3) يوضع الترقيم في وسط أسفل الصفحة.","4) لا يتم ترقيم صفحة العنوان وصفحة نتيجة الحكم."],"example":["تختلف متطلبات ترقيم الصفحات بحسب دليل الجامعة؛ ارجع إلى دليل مؤسستك عند التطبيق."],"source":"الشريحة 17","table":[]},{"title":"خامساً:الغلاف وترتيب صفحات الرسالة من الغلاف وحتى النهاية","body":["يتم تجليد الرسالة بعد المناقشة وإجراء التعديلات بالورق المقوى الأسود","ولون طباعته ذهبي ويطبع على الغلاف المعلومات كما هي في صفحة العنوان، وكما هو موضح في الشرائح","صفحة العنوان : وتحتوي على","* الجامعة – العمادة – الكلية – القسم","* عنوان الرسالة كما أقرت من عمادة الدراسات العليا.","* اسم مقدم الرسالة كما هو مسجل رسمياً في الجامعة.","* اسم المشرف/ والمشرف المشارك إن وجد."],"example":[],"source":"الشريحة 18","table":[]},{"title":"الغــــــــــلاف","body":["جامعة........... - صنعاء (على بعد 6سم من أعلى الصفحة)","عمادة الدراسـات العليا","كليـــة...........","قسم ........... (Arabic Transparent, 16-Bold)","عنوان الرسالة","(على بعد 12سم من أعلى الصفحة)","(Arabic Transparent, 24-Bold)"],"example":[],"source":"الشريحة 19","table":[]},{"title":"صفحــــــــة الحـــــــــــكم","body":["عنوان الرسالة (الخط 18)","اسم الطالب (الخط 18)","تمت الموافقة على قبول هذه الرسالة استكمالاً لمتطلبات درجة الماجستير أو الدكتوراه في (التخصص)","لجنة الحكم على الرسالة(الخط 16)","الأسماء و التوقيعات","1- دكتور..............(مشرفا)............","2- دكتور..............(عضوا)............"],"example":[],"source":"الشريحة 20","table":[]},{"title":"4) الملخص باللغة العربية (الرسائل العربية) والملخص باللغة الإنجليزية (الرسائل الإنجليزية).","body":["5) الملخص باللغة الإنجليزية (الرسائل العربية) والملخص باللغة العربية (الرسائل الإنجليزية).","يراعى في الملخصات أن عدد كلماتها بين(200-600)","وأن يتضمن أهداف الرسالة ومشكلة الدراسة ومنهج البحث والنتائج التي تم الوصول إليها.","6) صفحة الإهداء: (إن وجدت) وتكون صفحة مستقلة – ماذا يكتب فيها ؟","7) صفحة الشكر والعرفان:","يقتصرعلى المشرف والمشرف المشارك ولجنة المناقشة وبعض الأشخاص الذين سهلوا مهمة الباحث","ويتم عنونة هذه الصفحة بكلمة (شكر) في الرسائل العربية"],"example":[],"source":"الشريحة 21","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"أي جزء في الرسالة يتضمن النتائج واختبار الفرضيات؟","options":["المقدمة","تحليل البيانات والنتائج","الملحقات فقط","صفحة الغلاف"],"correct":1,"explain":"الفصل المخصص للنتائج والتحليل يعرض أدلة الفرضيات."},{"num":2,"kind":"mc","question":"أي توصية تعد أكثر قابلية للتنفيذ؟","options":["تحسين الأداء دائمًا","رفع الكفاءة قدر الإمكان","تنفيذ تدريب محدد لفرق محددة خلال فترة معلومة","زيادة الجودة دون تفاصيل"],"correct":2,"explain":"التوصية المحددة والقابلة للتنفيذ ترتبط بنتيجة ومجال عمل."},{"num":3,"kind":"mc","question":"ماذا يجب على الباحث عند استخدام فكرة مقتبسة؟","options":["إخفاء المصدر","توثيق المصدر الصحيح","تغيير الكلمات لإلغاء التوثيق","تجنب قائمة المراجع"],"correct":1,"explain":"التوثيق من أسس الأمانة العلمية."},{"num":4,"kind":"mc","question":"أين يعرض الباحث الأدوات الإضافية مثل نسخة الاستبيان؟","options":["الملاحق","الفهرس فقط","العنوان","الإهداء"],"correct":0,"explain":"تُخصص الملاحق للنماذج والوثائق الداعمة المرتبطة بمتن البحث."},{"num":5,"kind":"tf","question":"تتفق جميع الجامعات على أحجام خطوط وهوامش متطابقة للرسائل العلمية.","options":["صح","خطأ"],"correct":false,"explain":"تختلف أدلة التنسيق بين الجامعات، والأرقام في العرض أمثلة مؤسسية."},{"num":6,"kind":"tf","question":"من الأفضل إعداد ملخص واضح والتدرب على عرضه قبل المناقشة.","options":["صح","خطأ"],"correct":true,"explain":"تذكر المحاضرة التدريب والالتزام بالوقت والإلقاء والرد على الأسئلة."},{"num":7,"kind":"short","question":"اذكر الأقسام الأساسية للرسالة وفق العرض.","options":[],"answer":"صفحات تمهيدية، مقدمة، مراجعة أدبيات، منهجية، نتائج وتحليل، ملخص وتوصيات، مراجع، ملاحق."}]},{"id":12,"kind":"workshop","title":"ورشة العنوان والأسئلة والأهداف والفرضيات","source":"دليل صياغة العنوان والأسئلة والأهداف والفرضيات.docx + مثال أسئلة الدراسة.pdf","units":[{"title":"صياغة العنوان","steps":[{"title":"اختيار نوع العلاقة في عنوان البحث","body":["يعرض الدليل عنوانين: «أثر القيادة التحويلية في الإبداع الإداري: دراسة ميدانية على شركات الأسمنت في عدن» للبحث السببي، و«العلاقة بين القيادة التحويلية والإبداع الإداري» للبحث الارتباطي.","يلفت الدليل الانتباه إلى المتغيرات والمجتمع ونوع البحث وإمكان استنتاج التحليل المناسب."],"example":["قارن بين «أثر X في Y» و«العلاقة بين X وY» ووضح ما الذي يتطلبه كل منهما من تصميم مناسب."],"source":"دليل صياغة العنوان، الفقرة الأولى","table":[]},{"title":"فحص جودة العنوان","body":["على المتغيرات ؟\n\nهل المجتمع مذكور في العنوان؟\n\nهل نوع البحث مذكور في العنوان؟\n\nهل استطيع تحديد التحليل الاحصائي المناسب من العنوان؟\n"],"example":["لا يكفي ذكر لفظ «أثر» لاستنتاج السببية؛ انظر إلى تصميم البحث وإمكان التحكم في العوامل المربكة."],"source":"الدليل، أسئلة التقييم","table":[]}]},{"title":"الاتساق بين الأسئلة والأهداف والفرضيات","steps":[{"title":"السؤال الرئيس والأسئلة الفرعية","body":["يذكر الدليل السؤال الرئيس عن أثر القيادة التحويلية في الإبداع الإداري لدى شركات الأسمنت في عدن. ثم ينتقل إلى مستوى توافر المستقل والتابع وأثر أبعاد المستقل على التابع."],"example":["ابدأ بسؤال يحدد المتغيرين والمجتمع، ثم صغ أسئلة فرعية وصفية وتفسيرية دون تكرار."],"source":"الدليل، أسئلة الدراسة","table":[]},{"title":"تحويل السؤال إلى هدف","body":["أهداف الدليل تشمل معرفة مستوى توافر المتغير المستقل، ومعرفة مستوى توافر التابع، وقياس أثر المستقل على التابع."],"example":["السؤال: ما مستوى الرضا؟ ↔ الهدف: قياس مستوى الرضا. السؤال: ما أثر التدريب على الأداء؟ ↔ الهدف: اختبار أثر التدريب على الأداء."],"source":"الدليل، الأهداف","table":[]},{"title":"متى نحتاج إلى فرضية؟","body":["يعرض الدليل فرضيات لأثر القيادة التحويلية وأبعادها في الإبداع الإداري عند مستوى دلالة 0.05. ولا يلزم أن يقابل كل سؤال وصفي فرضية تأثيرية."],"example":["حدد أولًا ما يمكن اختباره من علاقات وفروق، ثم صغ فرضيات ذات متغيرات وتعريفات قابلة للقياس."],"source":"الدليل والملف التطبيقي (أسئلة الدراسة والأهداف والفرضيات)","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"ما السؤال الذي يعكس هدف قياس مستوى متغير؟","options":["ما مستوى الرضا الوظيفي؟","هل التدريب يسبب التغيير يقينًا؟","ما أفضل عنوان؟","كيف تكتب المراجع؟"],"correct":0,"explain":"يطلب قياس المستوى لا اختبار أثر بين متغيرات."},{"num":2,"kind":"mc","question":"أي صياغة تعبّر عن هدف مناسب لسؤال «ما أثر التدريب في الإنتاجية»؟","options":["وصف مجتمع الدراسة فقط","اختبار أثر التدريب على الإنتاجية","إلغاء المتغير المستقل","اختيار عنوان عام"],"correct":1,"explain":"الهدف المناسب هو اختبار العلاقة التي طرحها السؤال."},{"num":3,"kind":"mc","question":"ما العنصر المهم الذي ينبغي أن يظهر في عنوان بحث تطبيقي؟","options":["المتغيرات ومجتمع البحث المناسب","النتيجة النهائية مسبقًا","جميع فرضيات البحث حرفيًا","بيانات الباحث الشخصية"],"correct":0,"explain":"يساعد تحديد المتغيرات والمجتمع على ضبط نطاق البحث."},{"num":4,"kind":"tf","question":"يمكن إثبات علاقة سببية بمجرد استخدام كلمة «أثر» في عنوان الدراسة.","options":["صح","خطأ"],"correct":false,"explain":"السببية تحتاج تصميمًا ودليلًا مناسبًا، ولا تثبت من العنوان."},{"num":5,"kind":"case","question":"صغ سؤالًا رئيسًا وهدفًا متوافقين عن رضا العملاء.","options":[],"answer":"السؤال: ما مستوى رضا العملاء عن الخدمات الرقمية؟ الهدف: قياس مستوى رضا العملاء عن الخدمات الرقمية."}]},{"id":13,"kind":"workshop","title":"مختبر المتغير الوسيط والمتغير المعدّل","source":"سيناريوهات المتغير الوسيط والمعدل.pdf + ملف الحلول","units":[{"title":"خريطة الفرق بين الوسيط والمعدل","steps":[{"title":"المتغير الوسيط يشرح كيف","body":["المسار الوسيط: متغير مستقل ← متغير وسيط ← متغير تابع.","السؤال المركزي: كيف أو من خلال أي آلية ينتقل التأثير؟"],"example":["تبني خدمات رقمية ← رضا العملاء ← ولاء العملاء."],"source":"ورشة السيناريوهات، الحالة الرابعة","table":[]},{"title":"المتغير المعدّل يوضح متى أو لمن","body":["المعدل يؤثر في قوة أو اتجاه العلاقة بين المتغير المستقل والمتغير التابع، ولا يلزم أن يقع في مسار انتقال الأثر."],"example":["جاذبية الإعلان ← نية الشراء؛ وتختلف القوة باختلاف اهتمام المستهلك."],"source":"ورشة السيناريوهات، الحالة الثانية","table":[]}]},{"title":"عشر حالات مع التفسير","steps":[{"title":"سيناريو 1: التدريب والأداء الوظيفي","body":["تبحث الحالة في تأثير استراتيجيات التدريب على أداء الموظفين، مع دور محتمل لـدافعية الموظفين.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = استراتيجيات التدريب، التابع = أداء الموظفين، والعامل الثالث (دافعية الموظفين) متغير وسيط.","السبب: التدريب يزيد الدافعية، والدافعية تفسر كيف يتحسن الأداء."],"source":"سيناريو 1 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 2: الإعلان ونية الشراء","body":["تبحث الحالة في تأثير جاذبية الإعلان على نية الشراء، مع دور محتمل لـاهتمام المستهلك بالمنتج.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = جاذبية الإعلان، التابع = نية الشراء، والعامل الثالث (اهتمام المستهلك بالمنتج) متغير معدل.","السبب: قد يختلف أثر الإعلان في نية الشراء بين ذوي الاهتمام العالي والمنخفض."],"source":"سيناريو 2 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 3: هيكل رأس المال والربحية","body":["تبحث الحالة في تأثير قرارات هيكل رأس المال على ربحية الشركة، مع دور محتمل لـجودة حوكمة الشركات.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = قرارات هيكل رأس المال، التابع = ربحية الشركة، والعامل الثالث (جودة حوكمة الشركات) متغير معدل.","السبب: تغير جودة الحوكمة قوة علاقة هيكل رأس المال بالربحية."],"source":"سيناريو 3 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 4: الخدمات المصرفية الرقمية وولاء العملاء","body":["تبحث الحالة في تأثير تبني الخدمات الرقمية على ولاء العملاء، مع دور محتمل لـرضا العملاء.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = تبني الخدمات الرقمية، التابع = ولاء العملاء، والعامل الثالث (رضا العملاء) متغير وسيط.","السبب: تحسن الخدمات الرقمية رضا العملاء، الذي يفسر الانتقال إلى الولاء."],"source":"سيناريو 4 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 5: الأنماط القيادية والابتكار","body":["تبحث الحالة في تأثير أنماط القيادة على الابتكار التنظيمي، مع دور محتمل لـالثقافة التنظيمية.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = أنماط القيادة، التابع = الابتكار التنظيمي، والعامل الثالث (الثقافة التنظيمية) متغير معدل.","السبب: قد تقوى علاقة القيادة بالابتكار في ثقافة إبداعية وتضعف في ثقافة هرمية."],"source":"سيناريو 5 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 6: جودة التقارير وكفاءة الاستثمار","body":["تبحث الحالة في تأثير جودة التقارير المالية على كفاءة الاستثمار، مع دور محتمل لـشدة المنافسة.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = جودة التقارير المالية، التابع = كفاءة الاستثمار، والعامل الثالث (شدة المنافسة) متغير معدل.","السبب: يمكن أن يختلف أثر جودة التقارير المالية في القرارات باختلاف شدة المنافسة."],"source":"سيناريو 6 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 7: مرونة العمل والرفاه الوظيفي","body":["تبحث الحالة في تأثير سياسات مرونة العمل على الرفاهية الوظيفية، مع دور محتمل لـالدعم التنظيمي المدرك.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = سياسات مرونة العمل، التابع = الرفاهية الوظيفية، والعامل الثالث (الدعم التنظيمي المدرك) متغير وسيط.","السبب: يفسر الدعم التنظيمي المدرك كيف قد تتحول مرونة العمل إلى رفاهية وظيفية."],"source":"سيناريو 7 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 8: الأسواق الدولية والأداء","body":["تبحث الحالة في تأثير استراتيجية دخول السوق الأجنبية على الأداء الدولي، مع دور محتمل لـالتباعد الثقافي.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = استراتيجية دخول السوق الأجنبية، التابع = الأداء الدولي، والعامل الثالث (التباعد الثقافي) متغير معدل.","السبب: يحدد التباعد الثقافي متى تكون استراتيجية دخول سوق ما أكثر ملاءمة."],"source":"سيناريو 8 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 9: الحكومة الإلكترونية والتبني","body":["تبحث الحالة في تأثير جودة الخدمات الحكومية الإلكترونية على مستوى التبني، مع دور محتمل لـثقة المواطن في الحكومة.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = جودة الخدمات الحكومية الإلكترونية، التابع = مستوى التبني، والعامل الثالث (ثقة المواطن في الحكومة) متغير وسيط.","السبب: قد تؤدي جودة الخدمة إلى بناء الثقة، فتشجع الثقة على تبني الخدمة."],"source":"سيناريو 9 في ملفَي السيناريوهات والإجابات","table":[]},{"title":"سيناريو 10: سلسلة التوريد والأداء التشغيلي","body":["تبحث الحالة في تأثير تكامل سلسلة التوريد على الأداء التشغيلي، مع دور محتمل لـقدرات تكنولوجيا المعلومات.","حدد المتغير المستقل والتابع، وقرر هل العامل الثالث يفسر آلية التأثير (وسيط)، أم يغير قوة العلاقة أو اتجاهها (معدل)."],"example":["الحل من ملف الإجابات: المستقل = تكامل سلسلة التوريد، التابع = الأداء التشغيلي، والعامل الثالث (قدرات تكنولوجيا المعلومات) متغير معدل.","السبب: يمكن أن تقوى علاقة التكامل بالأداء كلما تحسنت القدرات التقنية."],"source":"سيناريو 10 في ملفَي السيناريوهات والإجابات","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"في سيناريو «التدريب والأداء الوظيفي»، ما الدور الذي يؤديه «دافعية الموظفين»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":2,"explain":"التدريب يزيد الدافعية، والدافعية تفسر كيف يتحسن الأداء."},{"num":2,"kind":"mc","question":"في سيناريو «الإعلان ونية الشراء»، ما الدور الذي يؤديه «اهتمام المستهلك بالمنتج»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":3,"explain":"قد يختلف أثر الإعلان في نية الشراء بين ذوي الاهتمام العالي والمنخفض."},{"num":3,"kind":"mc","question":"في سيناريو «هيكل رأس المال والربحية»، ما الدور الذي يؤديه «جودة حوكمة الشركات»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":3,"explain":"تغير جودة الحوكمة قوة علاقة هيكل رأس المال بالربحية."},{"num":4,"kind":"mc","question":"في سيناريو «الخدمات المصرفية الرقمية وولاء العملاء»، ما الدور الذي يؤديه «رضا العملاء»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":2,"explain":"تحسن الخدمات الرقمية رضا العملاء، الذي يفسر الانتقال إلى الولاء."},{"num":5,"kind":"mc","question":"في سيناريو «الأنماط القيادية والابتكار»، ما الدور الذي يؤديه «الثقافة التنظيمية»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":3,"explain":"قد تقوى علاقة القيادة بالابتكار في ثقافة إبداعية وتضعف في ثقافة هرمية."},{"num":6,"kind":"mc","question":"في سيناريو «جودة التقارير وكفاءة الاستثمار»، ما الدور الذي يؤديه «شدة المنافسة»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":3,"explain":"يمكن أن يختلف أثر جودة التقارير المالية في القرارات باختلاف شدة المنافسة."},{"num":7,"kind":"mc","question":"في سيناريو «مرونة العمل والرفاه الوظيفي»، ما الدور الذي يؤديه «الدعم التنظيمي المدرك»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":2,"explain":"يفسر الدعم التنظيمي المدرك كيف قد تتحول مرونة العمل إلى رفاهية وظيفية."},{"num":8,"kind":"mc","question":"في سيناريو «الأسواق الدولية والأداء»، ما الدور الذي يؤديه «التباعد الثقافي»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":3,"explain":"يحدد التباعد الثقافي متى تكون استراتيجية دخول سوق ما أكثر ملاءمة."},{"num":9,"kind":"mc","question":"في سيناريو «الحكومة الإلكترونية والتبني»، ما الدور الذي يؤديه «ثقة المواطن في الحكومة»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":2,"explain":"قد تؤدي جودة الخدمة إلى بناء الثقة، فتشجع الثقة على تبني الخدمة."},{"num":10,"kind":"mc","question":"في سيناريو «سلسلة التوريد والأداء التشغيلي»، ما الدور الذي يؤديه «قدرات تكنولوجيا المعلومات»؟","options":["متغير مستقل","متغير تابع","متغير وسيط","متغير معدّل"],"correct":3,"explain":"يمكن أن تقوى علاقة التكامل بالأداء كلما تحسنت القدرات التقنية."},{"num":11,"kind":"tf","question":"المتغير الوسيط يجيب غالبًا عن سؤال «كيف تنتقل العلاقة؟».","options":["صح","خطأ"],"correct":true,"explain":"الوسيط يوضح الآلية المقترحة بين المستقل والتابع."},{"num":12,"kind":"tf","question":"المتغير المعدّل يقع بالضرورة بين المستقل والتابع في سلسلة سببية.","options":["صح","خطأ"],"correct":false,"explain":"المعدّل يحدد قوة العلاقة أو اتجاهها ولا يلزم أن يكون مسارًا سببيًا وسيطًا."},{"num":13,"kind":"case","question":"ارسم لفظيًا نموذج وسيط من السيناريو الرابع.","options":[],"answer":"تبني الخدمات الرقمية ← رضا العملاء ← ولاء العملاء."},{"num":14,"kind":"case","question":"ارسم لفظيًا نموذج معدل من السيناريو الثاني.","options":[],"answer":"جاذبية الإعلان ← نية الشراء، ويختلف هذا التأثير بحسب مستوى اهتمام المستهلك بالمنتج."}]},{"id":14,"kind":"workshop","title":"ورشة الدراسات السابقة والفجوات البحثية","source":"فصل الدراسات السابقة في البحث العلمي مع نموذج مراجعة أدبية.pdf","units":[{"title":"لماذا نراجع الأدبيات؟","steps":[{"title":"المراجعة ليست سردًا فقط","body":["يوضح الملف أن المراجعة الأدبية عملية نقدية تحليلية لتحديد الفجوة البحثية، وبناء الإطار النظري، وتطوير المنهجية، ومناقشة النتائج، وتجنب التكرار."],"example":["اسأل عند قراءة كل دراسة: ماذا فعلت؟ كيف فعلت؟ ماذا وجدت؟ ماذا بقي دون بحث؟"],"source":"ملف الدراسات السابقة، ص1","table":[]},{"title":"أهداف الدراسات السابقة","body":["تحديد التطور المعرفي والمفاهيم والمتغيرات والمناهج والأدوات، وتقييم نقاط القوة والضعف، واكتشاف الاتجاهات المستقبلية."],"example":["قارن بين الدراسات بدل الاكتفاء بوصف كل واحدة في فقرة منفصلة."],"source":"الملف، ص1","table":[]}]},{"title":"خطوات البحث المنظم في الأدبيات","steps":[{"title":"الكلمات المفتاحية وقواعد البيانات","body":["ابدأ بالمصطلحات العربية والإنجليزية المتعلقة بالموضوع؛ ويقترح الدليل قواعد مثل Scopus وWeb of Science وGoogle Scholar وScienceDirect.","يمكن استخدام AND وOR وNOT لتضييق البحث أو توسيعه."],"example":["(التعلم الإحصائي OR التعلم الآلي) AND نظم المعلومات."],"source":"الملف، ص1","table":[]},{"title":"قراءة الدراسة وتصنيفها","body":["ابدأ بالملخص ثم الأجزاء ذات الصلة، وحدد الموضوع والمنهج والنتائج والفجوة والتقييم النقدي."],"example":["جدول الأدبيات: الباحث والسنة، السؤال، المنهج والعينة، النتائج، القيود، صلته ببحثي."],"source":"الملف، ص2","table":[]},{"title":"تنظيم المراجعة وكتابتها","body":["يمكن ترتيب الأدبيات زمنيًا أو موضوعيًا أو منهجيًا؛ ويبرز الملف أهمية التحليل النقدي المقارن."],"example":["قسم النتائج بحسب موضوع أو متغير، ثم قارن الاتفاقات والتناقضات بدل سرد مستقل لكل دراسة."],"source":"الملف، ص2–3","table":[]}]},{"title":"استخراج الفجوة وصياغتها","steps":[{"title":"التعليق النقدي والفجوة","body":["تلخص نهاية الفصل مواطن الاتفاق والاختلاف وتحدد جوانب لا تزال غير مدروسة بما يكفي، ثم تبرر قيمة الدراسة الجديدة."],"example":["فجوة سياقية: عُرفت العلاقة بقطاع آخر ولم تُختبر في مجتمع الدراسة الحالي. لا تجعل مجرد تغيير المكان دليلًا كافيًا على الأصالة دون تبرير."],"source":"الملف، ص3","table":[]},{"title":"أنواع المراجعات الأدبية","body":["يناقش الملف المراجعة السردية والمنهجية والتحليل التلوي ومراجعة النطاق، مع اختلاف الأهداف ودرجة الصرامة المنهجية."],"example":["المراجعة المنهجية تتبع خطة بحث واختيار وتقييم شفافة؛ والتحليل التلوي يجمع نتائج كمية قابلة للدمج."],"source":"الملف، ص4–5","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"ما الوظيفة الأبرز للمراجعة الأدبية الجيدة؟","options":["جمع مراجع دون تحليل","تحليل الدراسات واكتشاف الفجوات","إعادة طباعة الدراسات","إثبات الفروض قبل جمع بيانات"],"correct":1,"explain":"تتطلب المراجعة المقارنة والتحليل النقدي وتحديد ما لم يُبحث بما يكفي."},{"num":2,"kind":"mc","question":"أي قاعدة بحث يمكن أن تساعد الباحث في العثور على مقالات أكاديمية؟","options":["Scopus","برنامج الرسم فقط","تطبيق آلة حاسبة","برنامج أرشفة صور"],"correct":0,"explain":"Scopus من قواعد البيانات الأكاديمية المذكورة في الملف."},{"num":3,"kind":"mc","question":"ما الفرق الرئيسي بين المراجعة السردية والمنهجية؟","options":["المنهجية تتبع خطوات بحث واختيار وتقييم شفافة","السردية لا تحتوي أي مصادر","المنهجية تستخدم مقابلات فقط","لا فرق بينهما"],"correct":0,"explain":"المراجعة المنهجية تصف استراتيجية بحث واختيار وتقييم أكثر صرامة."},{"num":4,"kind":"mc","question":"ما المقصود بالتحليل التلوي Meta-Analysis؟","options":["جمع نتائج كمية من دراسات مستقلة ملائمة إحصائيًا","كتابة قائمة مراجع","ترجمة دراسة واحدة","اختيار استبانة جديدة"],"correct":0,"explain":"يمكن التحليل التلوي من دمج مقادير الأثر من عدة دراسات مناسبة."},{"num":5,"kind":"mc","question":"ما الجدول المفيد لمراجعة الأدبيات؟","options":["اسم الباحث والمنهج والنتائج والفجوة","اسم الجامعة وحده","أسماء المواد الدراسية","أسماء أعضاء اللجنة"],"correct":0,"explain":"جدول المقارنة يساعد على ربط المنهج والنتائج والقيود بسؤال البحث."},{"num":6,"kind":"tf","question":"تحديد الفجوة البحثية يعني دائمًا إثبات عدم وجود أي دراسة سابقة.","options":["صح","خطأ"],"correct":false,"explain":"قد تكون فجوة في السياق أو النظرية أو الطريقة أو النتائج المتعارضة."},{"num":7,"kind":"short","question":"اذكر أربع معلومات يمكن استخراجها من كل دراسة سابقة.","options":[],"answer":"الهدف، المنهج والعينة، أهم النتائج، القيود/الفجوة أو الصلة بالبحث الحالي."},{"num":8,"kind":"short","question":"كيف تختلف مراجعة النطاق عن المراجعة المنهجية؟","options":[],"answer":"مراجعة النطاق ترسم خريطة اتساع الأدبيات وأشكالها، أما المنهجية فتسعى إلى سؤال محدد بخطة اختيار وتقييم شفافة."}]},{"id":15,"kind":"workshop","title":"ورشة بناء الإطار النظري والنموذج البحثي","source":"الإطار النظري الفصل الثالث.pdf — صفحات ممسوحة ضوئيًا + عروض المحاضرات","units":[{"title":"المكونات الأساسية","steps":[{"title":"خمسة مكونات للإطار النظري","body":["تحديد المتغيرات وتسميتها، وشرح العلاقات بينها، وتوقع اتجاهها، وتقديم تبرير نظري من الدراسات السابقة، ثم رسم توضيحي يربط العلاقات."],"example":["ابدأ بتحديد التابع، ثم المستقلات والمعدل/الوسيط عند وجود مبرر علمي."],"source":"الإطار النظري، الصفحة الأولى (ص112–113 من الكتاب)","table":[]},{"title":"مثال شركات الطيران ومخالفة التعليمات","body":["يعرض الملف مثالًا عن العوامل المرتبطة بمخالفة تعليمات الأمن الجوي، منها الاتصالات والتنسيق واللامركزية والتدريب.","العلاقة المقترحة يجب أن توضح لماذا قد يزيد/يقل المتغير التابع بناء على الأسباب المحددة."],"example":["حدد المتغير التابع «مخالفة تعليمات الأمن» وربطه بعوامل تنظيمية وبشرية."],"source":"الصفحتان الأولى والثانية من الملف المصوّر","table":[]},{"title":"إضافة متغير معترض إلى النموذج","body":["توضح الرسوم المصورة كيف يمكن إضافة متغير يفسر الآلية بين أحد العوامل والنتيجة، مع شرح منطق ارتباطه بالأسباب السابقة."],"example":["لا يكفي وضع الأسهم؛ اشرح لماذا تتوقع العلاقات وكيف يمكن اختبارها."],"source":"الصفحة الثالثة من الملف المصوّر","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"ما المخرج البصري المهم للإطار النظري؟","options":["رسم علاقات المتغيرات","فهرس الأشكال فقط","ميزانية المشروع","توقيع المشاركين"],"correct":0,"explain":"الملف المصور يعرض الرسوم لتوضيح المتغيرات والعلاقات المتوقعة."},{"num":2,"kind":"mc","question":"أي عنصر يجب تبريره نظريًا؟","options":["العلاقات المتوقعة بين المتغيرات","لون الخط","ترقيم الصفحة","عدد الملاحق"],"correct":0,"explain":"تحتاج العلاقات إلى تفسير من الدراسات والنظرية وليس إلى أسهم فقط."},{"num":3,"kind":"tf","question":"يمكن بناء إطار نظري قوي من قائمة متغيرات دون بيان العلاقات بينها.","options":["صح","خطأ"],"correct":false,"explain":"من مكونات الإطار بيان طبيعة العلاقة والاتجاه والمبرر النظري."},{"num":4,"kind":"short","question":"اذكر خمسة مكونات للإطار النظري.","options":[],"answer":"تحديد المتغيرات، بيان العلاقات، تحديد اتجاهاتها، تبريرها نظريًا، رسم توضيحي."}]},{"id":16,"kind":"workshop","title":"ورشة صياغة المشكلة البحثية والوساطة والتعديل","source":"المشكلة البحثية بوجود متغير وسيط.pdf + متغير معدل.pdf + مثال الأسئلة والأهداف","units":[{"title":"صياغة مشكلة بمتغير وسيط","steps":[{"title":"العلاقة الوسيطة في البنوك","body":["تعرض المادة مثال أثر الإدارة التحويلية في الابتكار الإداري عبر الرشاقة التنظيمية لدى البنوك اليمنية في عدن.","الرشاقة التنظيمية تشرح كيف تنتقل آثار القيادة إلى الابتكار، وليست مجرد شرط خارجي."],"example":["مستقل: الإدارة التحويلية ← وسيط: الرشاقة التنظيمية ← تابع: الابتكار الإداري."],"source":"ملف المشكلة بمتغير وسيط، ص1–2","table":[]},{"title":"بناء نص المشكلة من العام إلى الخاص","body":["السياق العام، أهمية المتغير التابع، تقديم المستقل، الربط النظري، إدخال الوسيط، الفجوة البحثية، ثم الصياغة النهائية."],"example":["لا تبدأ بنتيجة مُسبقة؛ بين سبب أهمية السؤال وما لم توضحه الأدبيات حتى الآن."],"source":"ملف المشكلة بمتغير وسيط، ص2–4","table":[]}]},{"title":"صياغة مشكلة بمتغير معدل","steps":[{"title":"المرونة التنظيمية بوصفها معدّلًا","body":["يعرض الملف تطبيقًا يكون فيه أثر القيادة التحويلية في الابتكار الإداري أقوى أو أضعف حسب مستوى المرونة التنظيمية."],"example":["السؤال هنا «متى/تحت أي شرط؟» لا «كيف ينتقل الأثر؟»."],"source":"ملف المشكلة بمتغير معدل، ص1–2","table":[]},{"title":"تنبيه إلى اختلاف في تسمية المستند","body":["يظهر في بداية ملف المتغير المعدل عنوان قد يذكر «متغير وسيط»، لكن متن المثال يشرح صراحة الدور المعدّل للمرونة التنظيمية.","لهذا نعتمد في التصنيف على العلاقة الموصوفة في المتن والرسومات لا على العبارة الملتبسة في العنوان."],"example":["ملاحظة مقارنة بالملف، ص1–2"],"source":"","table":[]}]},{"title":"مواءمة السؤال والهدف والفرضية","steps":[{"title":"مثال أسئلة الدراسات والأهداف والفرضيات","body":["يربط الملف بين الأسئلة الوصفية والأهداف المقابلة، ثم يميز بينها وبين الفرضيات التي تختبر التأثير والوساطة والفروق بين الفئات."],"example":["ما مستوى ممارسة الإدارة التحويلية؟ سؤال وصفي. هل تتوسط الرشاقة العلاقة؟ سؤال سببي/تفسيري يحتاج فرضية قابلة للفحص."],"source":"ملف مثال الأسئلة والأهداف والفرضيات، ص1–4","table":[]}]}],"questions":[{"num":1,"kind":"mc","question":"في مثال الإدارة التحويلية والابتكار من خلال الرشاقة، ما دور الرشاقة التنظيمية؟","options":["تابع","مستقل","وسيط","معدل"],"correct":2,"explain":"تفسر الرشاقة آلية انتقال أثر الإدارة التحويلية إلى الابتكار."},{"num":2,"kind":"mc","question":"في مثال أثر القيادة مع اختلاف قوة العلاقة حسب المرونة، ما دور المرونة التنظيمية؟","options":["معدل","تابع","مستقل","حجم عينة"],"correct":0,"explain":"المرونة تغيّر شدة العلاقة بحسب مستوى توافرها."},{"num":3,"kind":"mc","question":"ما الخطوة المناسبة بعد تقديم السياق العام للمشكلة؟","options":["إعلان النتيجة","إبراز أهمية المتغير التابع","حذف المراجع","اختبار الفروض فورًا"],"correct":1,"explain":"يعرض الدليل تسلسلًا من السياق إلى التابع ثم المستقل والعلاقات والفجوة."},{"num":4,"kind":"mc","question":"أي سؤال يتطلب فرضية علاقة غالبًا؟","options":["ما مستوى الابتكار الإداري؟","كم عدد الموظفين؟","هل تتوسط الرشاقة علاقة الإدارة التحويلية بالابتكار؟","ما تاريخ تأسيس البنك؟"],"correct":2,"explain":"يتناول اختبار دور وسيط في علاقة بين متغيرات."},{"num":5,"kind":"tf","question":"كل سؤال وصفي يتطلب بالضرورة فرضية تأثيرية.","options":["صح","خطأ"],"correct":false,"explain":"الأسئلة الوصفية يمكن الإجابة عنها بالتقديرات الوصفية دون فرضية علاقة."},{"num":6,"kind":"case","question":"اكتب النموذجين مع بيان سؤال كل منهما.","options":[],"answer":"الوسيط: X → M → Y؛ يسأل كيف. المعدل: X → Y مع تأثير W في قوة أو اتجاه الرابط؛ يسأل متى أو لمن."}]}];
